    public Profilewindow(GratisData.User user) {
        this.currentUser = user;
        this.loggedInUser = user.name;
        
        // Initialize currentClientId from Database or GratisData
        this.currentClientId = Database.getCurrentClientId();
        if (this.currentClientId == null || this.currentClientId.isEmpty()) {
            this.currentClientId = user.clientId;
        }
        if (this.currentClientId == null || this.currentClientId.isEmpty()) {
            // Try to get from cloud as fallback
            this.currentClientId = Database.getClientIdFromCloud(user.email);
        }
        
        LOGGER.info("========== Profilewindow Constructor START ==========");
        LOGGER.info("User: " + user.name);
        LOGGER.info("ClientId: " + currentClientId);
        
        setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));
        
        JPanel loadingPanel = createLoadingPanel();
        setContentPane(loadingPanel);
        setSize(1200, 800);
        setLocationRelativeTo(null);
        setTitle("PoS Management System - " + loggedInUser);
        setDefaultCloseOperation(WindowConstants.DO_NOTHING_ON_CLOSE);
        
        try {
            if (!isDisplayable()) {
                setBackground(new Color(0, 0, 0, 0));
            }
        } catch (Exception ignored) {}
        
        addWindowListener(new WindowAdapter() {
            @Override
            public void windowClosing(WindowEvent e) {
                signOut();
            }
        });
        
        SwingWorker<Void, Void> worker = new SwingWorker<>() {
            @Override
            protected Void doInBackground() throws Exception {
                LOGGER.info("Starting background initialization...");
                
                try {
                    defaultLookAndFeel = UIManager.getLookAndFeel();
                    LOGGER.info("✅ Default L&F captured");
                } catch (Exception e) {
                    LOGGER.log(Level.WARNING, "Failed to capture default L&F", e);
                }
                
                try {
                    setupFlatLaf();
                    LOGGER.info("✅ FlatLaf setup complete");
                } catch (Exception e) {
                    LOGGER.log(Level.WARNING, "FlatLaf setup failed", e);
                }
                
                return null;
            }
            
            @Override
            protected void done() {
                LOGGER.info("Background initialization complete, building UI...");
                
                JPanel mainPanel = new JPanel(new BorderLayout());
                mainPanel.setBackground(new Color(248, 249, 250));
                mainPanel.setOpaque(true);
                
                JPanel sidebarPanel = createSidebar();
                JPanel contentPanel = createContentPanel();
                
                mainPanel.add(sidebarPanel, BorderLayout.WEST);
                mainPanel.add(contentPanel, BorderLayout.CENTER);
                
                setContentPane(mainPanel);
                
                revalidate();
                repaint();
                
                setCursor(Cursor.getDefaultCursor());
                
                LOGGER.info("UI built, loading data in background...");
                
                loadDataInBackground();
                
                // ========== TEMPORARY FIX: Sync all SQLite users to LocalUserStore ==========
                // RUN THIS ONCE, then remove or comment out after verifying all users can login
                new Thread(() -> {
                    try {
                        // Wait a bit for database to be fully ready
                        Thread.sleep(3000);
                        fixAllExistingLinkedUsers();
                    } catch (Exception e) {
                        LOGGER.log(Level.WARNING, "Failed to fix existing linked users", e);
                    }
                }).start();
                // ========== END OF TEMPORARY FIX ==========
                
                LOGGER.info("========== Profilewindow Constructor COMPLETE ==========");
            }
        };
        
        worker.execute();
    }
    public void syncAllSqliteUsersToLocalStore() {
        try (Connection conn = Database.getConnection();
             PreparedStatement stmt = conn.prepareStatement("SELECT email, username, password, privileges FROM users")) {
            
            ResultSet rs = stmt.executeQuery();
            int synced = 0;
            LocalUserStore store = LocalUserStore.getInstance();
            
            while (rs.next()) {
                String email = rs.getString("email");
                String username = rs.getString("username");
                String password = rs.getString("password");
                String privileges = rs.getString("privileges");
                
                if (email == null || email.isEmpty()) continue;
                
                if (store.getUser(email) == null) {
                    LocalUserStore.Role role = convertRoleStringToEnum(privileges);
                    store.registerUser(email, username, role, password);
                    synced++;
                    System.out.println("Synced user: " + email);
                }
            }
            
            store.saveUsers();
            System.out.println("Synced " + synced + " users to LocalUserStore");
            
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
    private void fixAllExistingLinkedUsers() {
        try (Connection conn = Database.getConnection();
             PreparedStatement stmt = conn.prepareStatement(
                 "SELECT email, username, password, privileges FROM users")) {
            
            ResultSet rs = stmt.executeQuery();
            int fixedCount = 0;
            LocalUserStore store = LocalUserStore.getInstance();
            
            while (rs.next()) {
                String email = rs.getString("email");
                String username = rs.getString("username");
                String password = rs.getString("password");
                String privileges = rs.getString("privileges");
                
                // Skip if email is null
                if (email == null || email.isEmpty()) continue;
                
                // Check if user already exists in LocalUserStore
                LocalUserStore.LocalUser existing = store.getUser(email);
                if (existing == null) {
                    // Map role
                    LocalUserStore.Role role = convertRoleStringToEnum(privileges);
                    
                    // Register user in LocalUserStore
                    LocalUserStore.LocalUser newUser = store.registerUser(email, username, role, password);
                    if (newUser != null) {
                        fixedCount++;
                        System.out.println("Fixed: Added " + email + " (" + username + ") to LocalUserStore");
                    } else {
                        // Fallback: manual add
                        LocalUserStore.LocalUser fallbackUser = new LocalUserStore.LocalUser(email, username, role, true, password);
                        store.addUser(fallbackUser);
                        fixedCount++;
                        System.out.println("Fixed: Manually added " + email + " to LocalUserStore");
                    }
                }
            }
            
            store.saveUsers();
            System.out.println("✅ Fixed " + fixedCount + " users. All SQLite users are now in LocalUserStore.");
            
            // Show result to user (optional)
            final int finalFixedCount = fixedCount;
            SwingUtilities.invokeLater(() -> {
                if (finalFixedCount > 0) {
                    JOptionPane.showMessageDialog(this,
                        "✅ User sync completed!\n\n" +
                        finalFixedCount + " user(s) were added to the login system.\n" +
                        "All linked users can now login.",
                        "Fix Complete", JOptionPane.INFORMATION_MESSAGE);
                }
            });
            
        } catch (SQLException e) {
            LOGGER.log(Level.SEVERE, "Failed to fix existing linked users", e);
        }
    }
    
    
    
