    private JPanel createLoadingPanel() {
    JPanel panel = new JPanel(new GridBagLayout());
    panel.setBackground(new Color(248, 249, 250));
    
    JPanel loadingCard = new JPanel();
    loadingCard.setLayout(new BoxLayout(loadingCard, BoxLayout.Y_AXIS));
    loadingCard.setBackground(Color.WHITE);
    loadingCard.setBorder(BorderFactory.createCompoundBorder(
        BorderFactory.createLineBorder(new Color(52, 144, 220, 100), 2),
        BorderFactory.createEmptyBorder(40, 60, 40, 60)
    ));
    
    // Animated spinner using custom painting
    JPanel spinnerPanel = new JPanel() {
        private float angle = 0f;
        private Timer spinTimer;
        {
            spinTimer = new Timer(20, e -> {
                angle = (angle + 10f) % 360f;
                repaint();
            });
            spinTimer.start();
        }
        
        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2d = (Graphics2D) g.create();
            g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            
            int cx = getWidth() / 2;
            int cy = getHeight() / 2;
            int radius = 25;
            
            // Draw outer circle
            g2d.setColor(new Color(52, 144, 220, 50));
            g2d.setStroke(new BasicStroke(4));
            g2d.drawOval(cx - radius, cy - radius, radius * 2, radius * 2);
            
            // Draw spinning arc
            g2d.setColor(new Color(52, 144, 220));
            g2d.setStroke(new BasicStroke(4, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
            g2d.drawArc(cx - radius, cy - radius, radius * 2, radius * 2, (int) angle, 270);
            
            // Draw center dot
            g2d.setColor(new Color(52, 144, 220));
            g2d.fillOval(cx - 4, cy - 4, 8, 8);
            
            g2d.dispose();
        }
        
        @Override
        public Dimension getPreferredSize() {
            return new Dimension(80, 80);
        }
    };
    spinnerPanel.setOpaque(false);
    spinnerPanel.setAlignmentX(Component.CENTER_ALIGNMENT);
    
    JLabel textLabel = new JLabel("Loading Profile Window...");
    textLabel.setFont(new Font("Segoe UI", Font.BOLD, 20));
    textLabel.setForeground(new Color(33, 37, 41));
    textLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
    
    JLabel subTextLabel = new JLabel("Please wait while we prepare your workspace");
    subTextLabel.setFont(new Font("Segoe UI", Font.PLAIN, 12));
    subTextLabel.setForeground(new Color(108, 117, 125));
    subTextLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
    
    JProgressBar progressBar = new JProgressBar();
    progressBar.setIndeterminate(true);
    progressBar.setPreferredSize(new Dimension(250, 6));
    progressBar.setAlignmentX(Component.CENTER_ALIGNMENT);
    progressBar.setBorderPainted(false);
    progressBar.setBackground(new Color(230, 230, 230));
    
    // Custom progress bar color
    UIManager.put("ProgressBar.selectionForeground", new Color(52, 144, 220));
    
    loadingCard.add(spinnerPanel);
    loadingCard.add(Box.createVerticalStrut(25));
    loadingCard.add(textLabel);
    loadingCard.add(Box.createVerticalStrut(8));
    loadingCard.add(subTextLabel);
    loadingCard.add(Box.createVerticalStrut(25));
    loadingCard.add(progressBar);
    
    panel.add(loadingCard);
    
    
    
    return panel;
}

