    private void showGlassMessage(Component parent, String message, String title, String type) {
        Dialog owner = null;
        if (parent instanceof Dialog) {
            owner = (Dialog) parent;
        } else if (parent instanceof Frame) {
            owner = (Dialog) parent;
        } else if (parent != null) {
            Window window = SwingUtilities.getWindowAncestor(parent);
            if (window instanceof Dialog) {
                owner = (Dialog) window;
            } else if (window instanceof Frame) {
                owner = (Dialog) window;
            }
        }
        
        // Create a JDialog as fallback instead of JFrame
        if (owner == null) {
            JDialog tempDialog = new JDialog();
            owner = tempDialog;
        }
        
        JDialog msgDialog = new JDialog(owner, title, true);
        msgDialog.setSize(350, 180);
        msgDialog.setLocationRelativeTo(parent);
        msgDialog.setUndecorated(true);
        msgDialog.setBackground(new Color(0, 0, 0, 0));
        
        Color accentColor = type.equals("success") ? new Color(46, 204, 113) : 
                            type.equals("error") ? new Color(231, 76, 60) : 
                            type.equals("warning") ? new Color(255, 193, 7) : new Color(52, 152, 219);
        String icon = type.equals("success") ? "✅" : type.equals("error") ? "❌" : type.equals("warning") ? "⚠️" : "ℹ️";
        
        JPanel glassPanel = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2d = (Graphics2D) g.create();
                g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2d.setColor(new Color(33, 37, 41, 240));
                g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 20, 20);
                g2d.setColor(accentColor);
                g2d.setStroke(new BasicStroke(2));
                g2d.drawRoundRect(1, 1, getWidth() - 3, getHeight() - 3, 20, 20);
                g2d.dispose();
            }
        };
        glassPanel.setLayout(new GridBagLayout());
        glassPanel.setBorder(new EmptyBorder(20, 20, 20, 20));
        
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.insets = new Insets(10, 10, 10, 10);
        
        JLabel iconLabel = new JLabel(icon);
        iconLabel.setFont(new Font("Segoe UI Emoji", Font.PLAIN, 40));
        gbc.gridx = 0; gbc.gridy = 0;
        glassPanel.add(iconLabel, gbc);
        
        JLabel messageLabel = new JLabel("<html><center>" + message + "</center></html>");
        messageLabel.setFont(new Font("Segoe UI", Font.PLAIN, 12));
        messageLabel.setForeground(Color.WHITE);
        gbc.gridy = 1;
        glassPanel.add(messageLabel, gbc);
        
        JButton okBtn = createGlassButton("OK", accentColor);
        okBtn.addActionListener(e -> msgDialog.dispose());
        gbc.gridy = 2;
        glassPanel.add(okBtn, gbc);
        
        msgDialog.setContentPane(glassPanel);
        msgDialog.setVisible(true);
    }

private void updateComponentTheme(Container container) {
    Font mainFont = new Font("Segoe UI", Font.PLAIN, 14);

    for (Component comp : container.getComponents()) {

        // recurse first
        if (comp instanceof Container) {
            updateComponentTheme((Container) comp);
        }

        if (!(comp instanceof JComponent jc)) continue;

        jc.setFont(mainFont);

        // =========================
        // SAFE OPAQUE HANDLING
        // =========================

        if (comp instanceof JTable ||
            comp instanceof JTextField ||
            comp instanceof JTextArea) {

            jc.setOpaque(true);
            jc.setBackground(new Color(45, 50, 55));
            jc.setForeground(Color.WHITE);
        }

        else if (comp instanceof JScrollPane) {
            jc.setOpaque(false);
            ((JScrollPane) comp).getViewport().setOpaque(false);
        }

        else if (comp instanceof JComboBox<?>) {
            jc.setOpaque(true);
            jc.setBackground(new Color(60, 60, 60));
            jc.setForeground(Color.WHITE);
        }

        else if (comp instanceof JButton) {
            jc.setOpaque(true);
            jc.setForeground(Color.WHITE);
            jc.setBackground(new Color(52, 152, 219));
            jc.setBorder(BorderFactory.createEmptyBorder(6, 12, 6, 12));
            // Cast to JButton to access setFocusPainted
            ((JButton) comp).setFocusPainted(false);
        }

        else if (comp instanceof JLabel) {
            jc.setForeground(Color.WHITE);
            jc.setOpaque(false);
        }

        else {
            // default glass mode for containers/panels
            jc.setOpaque(false);
        }
    }
}

private void applyGlassDialogTheme(JDialog dialog) {
    dialog.setBackground(new Color(0, 0, 0, 0));

    // Ensure consistent rendering on different LAFs
    dialog.getRootPane().setOpaque(false);

    // Optional: prevents weird white flicker on some systems
    dialog.getContentPane().setBackground(new Color(0, 0, 0, 0));
}

private void applyGlassFrameTheme(JFrame frame) {
    frame.getRootPane().setOpaque(false);
    frame.getContentPane().setBackground(new Color(0, 0, 0, 0));
}

private void loadDataInBackground() {
    java.util.concurrent.CompletableFuture.runAsync(() -> {
        try {
            loadUserRestrictions();
        } catch (Exception e) {
            LOGGER.log(Level.FINE, "Restriction load skipped", e);
        }
    });

    java.util.concurrent.CompletableFuture.runAsync(() -> {
        try {
            List<Database.Product> products = Database.getProductsPaginated(0, 100);
            List<Database.Category> categories = Database.getAllCategoryObjects();
            Map<Integer, String> categoryMap = new HashMap<>();
            for (Database.Category cat : categories) categoryMap.put(cat.getId(), cat.getName());

            List<Object[]> rows = new ArrayList<>();
            for (Database.Product p : products) {
                rows.add(new Object[]{
                    p.getName(),
                    categoryMap.getOrDefault(p.getCategoryId(), "Unknown"),
                    p.getStockQuantity(),
                    p.getExpireDate() != null ? p.getExpireDate().toString() : "N/A"
                });
            }
            SwingUtilities.invokeLater(() -> {
                for (Object[] row : rows) tableModel.addRow(row);
            });
        } catch (Exception e) {
            LOGGER.log(Level.FINE, "Initial product load skipped", e);
        }

        try {
            List<Database.Product> rest = Database.getProductsPaginated(100, 500);
            List<Database.Category> categories = Database.getAllCategoryObjects();
            Map<Integer, String> categoryMap = new HashMap<>();
            for (Database.Category cat : categories) categoryMap.put(cat.getId(), cat.getName());

            List<Object[]> rows = new ArrayList<>();
            for (Database.Product p : rest) {
                rows.add(new Object[]{
                    p.getName(),
                    categoryMap.getOrDefault(p.getCategoryId(), "Unknown"),
                    p.getStockQuantity(),
                    p.getExpireDate() != null ? p.getExpireDate().toString() : "N/A"
                });
            }
            if (!rows.isEmpty()) {
                SwingUtilities.invokeLater(() -> {
                    for (Object[] row : rows) tableModel.addRow(row);
                });
            }
        } catch (Exception e) {
            LOGGER.log(Level.FINE, "Remaining products load skipped", e);
        }

        SwingUtilities.invokeLater(this::startBackgroundServices);
    });
}

    private void startBackgroundServices() {
    Timer dateTimeTimer = new Timer(1000, e -> updateDateTime());
    dateTimeTimer.start();

    Timer statusTimer = new Timer(60000, e -> updateConnectionStatus());
    statusTimer.start();

    Timer tursoSyncTimer = new Timer(30000, e ->
    java.util.concurrent.CompletableFuture.runAsync(() -> {
        try {
            if (Database.checkTursoConnection()) {
                boolean synced = SyncEngine.fullSync();
                if (synced) {
                    LOGGER.info("SyncEngine full sync complete");
                    SwingUtilities.invokeLater(this::loadProductsData);
                }
            }
        } catch (Exception ex) {
            LOGGER.log(Level.FINE, "Auto-sync silent fail", ex);
        }
    })
);
tursoSyncTimer.start();

   
   
}

