    private void testDatabaseConnection() {
        try {
            Connection conn = Database.getConnection();
            System.out.println("✅ Database connected successfully!");
            
            // Check if users table exists
            DatabaseMetaData meta = conn.getMetaData();
            ResultSet tables = meta.getTables(null, null, "users", null);
            if (tables.next()) {
                System.out.println("✅ Users table exists");
            } else {
                System.out.println("❌ Users table does not exist!");
            }
            
            // Check for superadmin user
            String sql = "SELECT * FROM users WHERE username = 'superadmin'";
            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(sql)) {
                if (rs.next()) {
                    System.out.println("✅ superadmin user found!");
                    System.out.println("Username: " + rs.getString("username"));
                    System.out.println("Password: " + rs.getString("password"));
                    System.out.println("Privileges: " + rs.getString("privileges"));
                } else {
                    System.out.println("❌ superadmin user NOT found!");
                }
            }
            
            // Check for ubuntujoro user
            sql = "SELECT * FROM users WHERE username = 'ubuntujoro'";
            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(sql)) {
                if (rs.next()) {
                    System.out.println("✅ ubuntujoro user found!");
                    System.out.println("Username: " + rs.getString("username"));
                    System.out.println("Password: " + rs.getString("password"));
                    System.out.println("Privileges: " + rs.getString("privileges"));
                } else {
                    System.out.println("❌ ubuntujoro user NOT found!");
                }
            }
            
            conn.close();
        } catch (SQLException e) {
            System.out.println("❌ Database error: " + e.getMessage());
            e.printStackTrace();
        }
    }

    private void loadProductsDataPaginated(int offset, int limit) {
        SwingWorker<List<Object[]>, Void> worker = new SwingWorker<>() {
            @Override
            protected List<Object[]> doInBackground() throws Exception {
                List<Object[]> rows = new ArrayList<>();
                
                try {
                    List<Database.Product> products = Database.getProductsPaginated(offset, limit);
                    List<Database.Category> categories = Database.getAllCategoryObjects();
                    
                    Map<Integer, String> categoryMap = new HashMap<>();
                    for (Database.Category cat : categories) {
                        categoryMap.put(cat.getId(), cat.getName());
                    }
                    
                    for (Database.Product product : products) {
                        rows.add(new Object[]{
                            product.getName(),
                            categoryMap.getOrDefault(product.getCategoryId(), "Unknown"),
                            product.getStockQuantity(),
                            product.getExpireDate() != null ? product.getExpireDate().toString() : "N/A"
                        });
                    }
                } catch (SQLException e) {
                    LOGGER.log(Level.WARNING, "Error loading products", e);
                }
                
                return rows;
            }
            
            @Override
            protected void done() {
                try {
                    List<Object[]> rows = get();
                    SwingUtilities.invokeLater(() -> {
                        for (Object[] row : rows) {
                            tableModel.addRow(row);
                        }
                        
                        if (rows.size() == limit) {
                            loadProductsDataPaginated(offset + limit, limit);
                        }
                    });
                } catch (Exception e) {
                    LOGGER.log(Level.WARNING, "Error processing products", e);
                }
            }
        };
        worker.execute();
    }

