    private ImageIcon getCachedButtonImage(String imageName) {
        return imageCache.computeIfAbsent(imageName, name -> {
            try {
                InputStream imgStream = getClass().getResourceAsStream("/hIMs/App/resources/" + name);
                if (imgStream != null) {
                    BufferedImage bufferedImage = ImageIO.read(imgStream);
                    Image scaledImg = bufferedImage.getScaledInstance(64, 64, Image.SCALE_SMOOTH);
                    imgStream.close();
                    return new ImageIcon(scaledImg);
                }
            } catch (Exception e) {
                LOGGER.log(Level.FINE, "Could not load image: " + name, e);
            }
            return null;
        });
    }

    private String getConnectionStatus() {
        if (connectionStatus != null && System.currentTimeMillis() - lastStatusCheck < 30000) {
            return connectionStatus;
        }
        
        String status = "Offline Mode";
        try {
            URL url = new URL("https://www.google.com");
            HttpURLConnection connection = (HttpURLConnection) url.openConnection();
            connection.setConnectTimeout(2000);
            connection.setReadTimeout(2000);
            connection.setRequestMethod("HEAD");
            int responseCode = connection.getResponseCode();
            status = (responseCode == 200) ? "Online Mode" : "Offline Mode";
            connection.disconnect();
        } catch (Exception e) {
            // Already offline
        }
        
        connectionStatus = status;
        lastStatusCheck = System.currentTimeMillis();
        return status;
    }

