    private void showImageUploadDialog() {
        JFileChooser fileChooser = new JFileChooser();
        fileChooser.setDialogTitle("Select Profile Image");
        fileChooser.setFileFilter(new javax.swing.filechooser.FileFilter() {
            @Override
            public boolean accept(File f) {
                if (f.isDirectory()) return true;
                String name = f.getName().toLowerCase();
                return name.endsWith(".png") || name.endsWith(".jpg") || name.endsWith(".jpeg") || name.endsWith(".gif");
            }

            @Override
            public String getDescription() {
                return "Image files (*.png, *.jpg, *.jpeg, *.gif)";
            }
        });

        int result = fileChooser.showOpenDialog(this);
        if (result == JFileChooser.APPROVE_OPTION) {
            File selectedFile = fileChooser.getSelectedFile();
            saveUserProfileImage(selectedFile);
        }
    }

    private void saveUserProfileImage(File sourceFile) {
        try {
            File profileDir = new File(PROFILE_IMAGES_DIR);
            if (!profileDir.exists()) {
                profileDir.mkdirs();
            }

            String targetPath = PROFILE_IMAGES_DIR + File.separator + loggedInUser + "_profile.png";
            BufferedImage originalImage = ImageIO.read(sourceFile);
            BufferedImage resizedImage = new BufferedImage(150, 150, BufferedImage.TYPE_INT_ARGB);
            Graphics2D g2d = resizedImage.createGraphics();
            g2d.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
            g2d.drawImage(originalImage, 0, 0, 150, 150, null);
            g2d.dispose();

            ImageIO.write(resizedImage, "PNG", new File(targetPath));
            repaint();

            JOptionPane.showMessageDialog(this, "Profile image updated successfully!", "Success", JOptionPane.INFORMATION_MESSAGE);
        } catch (Exception e) {
            JOptionPane.showMessageDialog(this, "Error saving profile image: " + e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    private JPanel createProfileSection() {
        JPanel profilePanel = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2d = (Graphics2D) g.create();
                g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                
                // Glass effect
                g2d.setColor(SIDEBAR_COLOR);
                g2d.fillRect(0, 0, getWidth(), getHeight());
                
                // Bottom separator with glass effect
                g2d.setColor(new Color(255, 255, 255, 50));
                g2d.setStroke(new BasicStroke(1));
                g2d.drawLine(20, getHeight()-1, getWidth()-20, getHeight()-1);
                
                g2d.dispose();
            }
        };
        profilePanel.setOpaque(false);
        profilePanel.setLayout(new BoxLayout(profilePanel, BoxLayout.Y_AXIS));
        profilePanel.setBorder(new EmptyBorder(20, 20, 30, 20));

        JPanel avatarPanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
        avatarPanel.setOpaque(false);

        JPanel circularAvatar = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

                // Glass effect background
                g2.setColor(new Color(52, 144, 220, 200));
                g2.fillOval(0, 0, getWidth(), getHeight());
                
                // Inner glow
                g2.setColor(new Color(255, 255, 255, 100));
                g2.setStroke(new BasicStroke(2));
                g2.drawOval(2, 2, getWidth()-5, getHeight()-5);

                String userImagePath = PROFILE_IMAGES_DIR + File.separator + loggedInUser + "_profile.png";
                boolean imageLoaded = false;

                try {
                    File userImageFile = new File(userImagePath);
                    if (userImageFile.exists()) {
                        BufferedImage userImage = ImageIO.read(userImageFile);
                        if (userImage != null) {
                            g2.setClip(new java.awt.geom.Ellipse2D.Float(5, 5, getWidth()-10, getHeight()-10));
                            g2.drawImage(userImage, 5, 5, getWidth()-10, getHeight()-10, null);
                            g2.setClip(null);
                            imageLoaded = true;
                        }
                    }
                } catch (Exception e) {
                    System.err.println("Error loading user image: " + e.getMessage());
                }

                if (!imageLoaded) {
                    g2.setColor(Color.WHITE);
                    g2.setFont(new Font("Segoe UI", Font.BOLD, 32));
                    FontMetrics fm = g2.getFontMetrics();
                    String text = loggedInUser.substring(0, 1).toUpperCase();
                    int x = (getWidth() - fm.stringWidth(text)) / 2;
                    int y = ((getHeight() - fm.getHeight()) / 2) + fm.getAscent();
                    g2.drawString(text, x, y);
                }

                // Outer ring with glow
                g2.setColor(new Color(255, 255, 255, 150));
                g2.setStroke(new BasicStroke(3));
                g2.drawOval(1, 1, getWidth()-3, getHeight()-3);
                
                g2.dispose();
            }
        };
        circularAvatar.setPreferredSize(new Dimension(90, 90));
        circularAvatar.setOpaque(false);
        circularAvatar.setCursor(new Cursor(Cursor.HAND_CURSOR));

        circularAvatar.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                showImageUploadDialog();
            }
        });

        avatarPanel.add(circularAvatar);
        profilePanel.add(avatarPanel);
        profilePanel.add(Box.createVerticalStrut(10));

        JLabel adminLabel = new JLabel(loggedInUser);
        adminLabel.setFont(new Font("Segoe UI", Font.BOLD, 18));
        adminLabel.setForeground(Color.WHITE);
        adminLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
        profilePanel.add(adminLabel);

        profilePanel.add(Box.createVerticalStrut(5));

        JLabel statusLabel = new JLabel();
        statusLabel.setFont(new Font("Segoe UI", Font.PLAIN, 12));
        statusLabel.setAlignmentX(Component.CENTER_ALIGNMENT);

        Timer statusTimer = new Timer(5000, e -> {
            String status = getConnectionStatus();
            statusLabel.setText(status);
            if (status.equals("Online Mode")) {
                statusLabel.setForeground(Color.GREEN);
            } else {
                statusLabel.setForeground(new Color(149, 165, 166));
            }
        });
        statusTimer.start();

        String initialStatus = getConnectionStatus();
        statusLabel.setText(initialStatus);
        if (initialStatus.equals("Online Mode")) {
            statusLabel.setForeground(Color.GREEN);
        } else {
            statusLabel.setForeground(new Color(149, 165, 166));
        }

        profilePanel.add(statusLabel);
        return profilePanel;
    }

