    private JButton createNavButton(String icon, String text) {
        JButton button = new JButton() {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2d = (Graphics2D) g.create();
                g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                
                if (getModel().isPressed()) {
                    g2d.setColor(new Color(255, 255, 255, 50));
                    g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
                } else if (getModel().isRollover()) {
                    if (!text.equals("Admin")) {
                        g2d.setColor(new Color(255, 255, 255, 30));
                        g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
                    }
                }
                
                // Glass border
                g2d.setColor(new Color(255, 255, 255, 20));
                g2d.setStroke(new BasicStroke(1));
                g2d.drawRoundRect(0, 0, getWidth()-1, getHeight()-1, 10, 10);
                
                g2d.dispose();
                super.paintComponent(g);
            }
        };
        button.setLayout(new BorderLayout(10, 0));
        button.setBorder(new EmptyBorder(8, 15, 8, 15));
        button.setBackground(SIDEBAR_COLOR);
        button.setForeground(Color.WHITE);
        button.setFont(new Font("Segoe UI", Font.PLAIN, 14));
        button.setFocusPainted(false);
        button.setBorderPainted(false);
        button.setContentAreaFilled(false);
        button.setOpaque(false);
        button.setCursor(new Cursor(Cursor.HAND_CURSOR));

        JLabel iconLabel = new JLabel();
        
        String[] fontNames = {
            "Segoe UI Emoji",
            "Segoe UI Symbol",
            "Arial Unicode MS",
            "Lucida Sans Unicode"
        };
        
        boolean emojiRendered = false;
        for (String fontName : fontNames) {
            Font testFont = new Font(fontName, Font.PLAIN, 20);
            if (testFont.canDisplayUpTo(icon) == -1) {
                iconLabel.setFont(testFont);
                iconLabel.setText(icon);
                emojiRendered = true;
                break;
            }
        }
        
        if (!emojiRendered) {
            Map<String, String> asciiMap = new HashMap<>();
            asciiMap.put("⚙️", "[*]");
            asciiMap.put("🔧", "[T]");
            asciiMap.put("📋", "[L]");
            asciiMap.put("🔒", "[S]");
            asciiMap.put("💡", "[H]");
            asciiMap.put("🔔", "[N]");
            asciiMap.put("📖", "[B]");
            asciiMap.put("☁️", "[C]");
            asciiMap.put("⏻", "[X]");
            
            iconLabel.setFont(new Font("Monospaced", Font.BOLD, 16));
            iconLabel.setText(asciiMap.getOrDefault(icon, "[?]"));
        }
        
        iconLabel.setForeground(Color.WHITE);

        JLabel textLabel = new JLabel(text);
        textLabel.setForeground(Color.WHITE);

        button.add(iconLabel, BorderLayout.WEST);
        button.add(textLabel, BorderLayout.CENTER);

        button.addActionListener(createNavigationActionListener(text));

        if (isRestricted(text)) {
            button.setEnabled(false);
            button.setForeground(new Color(149, 165, 166));
            iconLabel.setForeground(new Color(149, 165, 166));
            textLabel.setForeground(new Color(149, 165, 166));
        }

        return button;
    }

