    private class SearchListener implements DocumentListener {
        private Timer searchTimer;

        @Override
        public void insertUpdate(DocumentEvent e) {
            filterTable();
        }

        @Override
        public void removeUpdate(DocumentEvent e) {
            filterTable();
        }

        @Override
        public void changedUpdate(DocumentEvent e) {
            filterTable();
        }

        private void filterTable() {
            if (searchTimer != null && searchTimer.isRunning()) {
                searchTimer.stop();
            }

            searchTimer = new Timer(150, e -> performSearch());
            searchTimer.setRepeats(false);
            searchTimer.start();
        }

        private void performSearch() {
            String query = searchField.getText().trim().toLowerCase();

            SwingWorker<Void, Object[]> worker = new SwingWorker<Void, Object[]>() {
                @Override
                protected Void doInBackground() throws Exception {
                    try {
                        List<Database.Product> allProducts = Database.getAllProducts();
                        List<Database.Category> categories = Database.getAllCategoryObjects();

                        Map<Integer, String> categoryMap = new HashMap<>();
                        for (Database.Category cat : categories) {
                            categoryMap.put(cat.getId(), cat.getName());
                        }

                        for (Database.Product product : allProducts) {
                            if (query.isEmpty() || product.getName().toLowerCase().contains(query)) {
                                String categoryName = categoryMap.getOrDefault(product.getCategoryId(), "Unknown");
                                String expireDate = product.getExpireDate() != null ? 
                                    product.getExpireDate().toString() : "N/A";
                                
                                publish(new Object[]{
                                    product.getName(),
                                    categoryName,
                                    product.getStockQuantity(),
                                    expireDate
                                });
                            }
                        }
                    } catch (SQLException ex) {
                        LOGGER.log(Level.WARNING, "Search error", ex);
                    }
                    return null;
                }
                
                @Override
                protected void process(java.util.List<Object[]> chunks) {
                    tableModel.setRowCount(0);
                    for (Object[] row : chunks) {
                        tableModel.addRow(row);
                    }
                }
            };
            
            worker.execute();
        }
    }

    private void loadProductsData() {
    tableModel.setRowCount(0);
    
    SwingWorker<Void, Object[]> worker = new SwingWorker<Void, Object[]>() {
        @Override
        protected Void doInBackground() throws Exception {
            try {
                List<Database.Product> products = Database.getAllProducts();
                List<Database.Category> categories = Database.getAllCategoryObjects();
                Map<Integer, String> categoryMap = new HashMap<>();
                for (Database.Category cat : categories) categoryMap.put(cat.getId(), cat.getName());
                for (Database.Product product : products) {
                    String categoryName = categoryMap.getOrDefault(product.getCategoryId(), "Unknown");
                    String expireDate = product.getExpireDate() != null ? product.getExpireDate().toString() : "N/A";
                    publish(new Object[]{product.getName(), categoryName, product.getStockQuantity(), expireDate});
                }
            } catch (Exception e) {
                LOGGER.log(Level.FINE, "Product load from local DB skipped", e);
            }
            return null;
        }
        
        @Override
        protected void process(java.util.List<Object[]> chunks) {
            for (Object[] row : chunks) tableModel.addRow(row);
        }
        
        @Override
        protected void done() {
            LOGGER.info("Products loaded: " + tableModel.getRowCount() + " rows");
            productsTable.revalidate();
            productsTable.repaint();
        }
    };
    worker.execute();
}

