    JPanel viewUsersCard = createGlassAdminCard("User Panel", "View and message users", new Color(52, 152, 219));
    JButton btnViewUsers = createGlassAdminButton("View All Users", new Color(52, 152, 219));
    
    viewUsersCard.add(btnViewUsers);
    viewUsersCard.add(Box.createVerticalStrut(6));
    
    userMgmtPanel.add(viewUsersCard);

    JPanel createUserCard = createGlassAdminCard("Create User", "Add new system user", new Color(46, 204, 113));
    JButton btnCreateUser = createGlassAdminButton("Create New User", new Color(46, 204, 113));
    createUserCard.add(btnCreateUser);
    userMgmtPanel.add(createUserCard);

    JPanel manageCard = createGlassAdminCard("Manage Users", "Roles and restrictions", new Color(155, 89, 182));
    JButton btnManageUsers = createGlassAdminButton("Manage Users", new Color(155, 89, 182));
    JButton btnUserLimit = createGlassAdminButton("User-Limit Setting", new Color(155, 89, 182));
    manageCard.add(btnManageUsers);
    manageCard.add(Box.createVerticalStrut(6));
    manageCard.add(btnUserLimit);
    userMgmtPanel.add(manageCard);

    JPanel blockCard = createGlassAdminCard("Block / Delete", "Restrict user access", new Color(231, 76, 60));
    JButton btnBlock = createGlassAdminButton("Block / Delete User", new Color(231, 76, 60));
    blockCard.add(btnBlock);
    userMgmtPanel.add(blockCard);

    // ========== TAB 1: Role Management ==========
    JPanel roleMgmtPanel = new JPanel(new GridLayout(2, 2, 12, 12));
    roleMgmtPanel.setOpaque(false);
    roleMgmtPanel.setBorder(new EmptyBorder(15, 20, 15, 20));

    JPanel roleStatsCard = createGlassAdminCard("Role Statistics", "View role distribution", new Color(46, 204, 113));
    JButton btnRoleStats = createGlassAdminButton("Role Statistics", new Color(46, 204, 113));
    roleStatsCard.add(btnRoleStats);
    roleMgmtPanel.add(roleStatsCard);

    JPanel roleLimitsCard = createGlassAdminCard("Role Limits", "Limits per role", new Color(52, 152, 219));
    JButton btnRoleLimits = createGlassAdminButton("View Role Limits", new Color(52, 152, 219));
    roleLimitsCard.add(btnRoleLimits);
    roleMgmtPanel.add(roleLimitsCard);

    roleMgmtPanel.add(new JPanel() {{ setOpaque(false); }});
