    securityPanel.setBorder(new EmptyBorder(15, 20, 15, 20));

    JPanel auditCard = createGlassAdminCard("Audit Logs", "Full activity audit trail", new Color(255, 140, 0));
    JButton btnAudit = createGlassAdminButton("View Audit Logs", new Color(255, 140, 0));
    auditCard.add(btnAudit);
    securityPanel.add(auditCard);

    JPanel secCard = createGlassAdminCard("Security Settings", "Passwords and 2FA", new Color(155, 89, 182));
    JButton btnSecurity = createGlassAdminButton("Security Settings", new Color(155, 89, 182));
    secCard.add(btnSecurity);
    securityPanel.add(secCard);

    securityPanel.add(new JPanel() {{ setOpaque(false); }});
    securityPanel.add(new JPanel() {{ setOpaque(false); }});

    // ========== TAB 3: Sales Management ==========
    JPanel salesPanel = createSalesManagementPanel();

 // ========== TAB 4: Received Management ==========
