// ==================== SALES MANAGEMENT PANEL ====================

    private JPanel createSalesManagementPanel() {
    JPanel mainPanel = new JPanel(new BorderLayout(15, 15));
    mainPanel.setOpaque(false);
    mainPanel.setBorder(new EmptyBorder(15, 15, 15, 15));
    
    // Get current client ID filter
    String currentClientId = Database.getCurrentClientId();
    if (currentClientId == null || currentClientId.isEmpty()) {
        currentClientId = this.currentClientId;
    }
    final String clientIdFilter = currentClientId;
    
    // ================= TITLE SECTION =================
    JPanel titlePanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
    titlePanel.setOpaque(false);
    JLabel titleLabel = new JLabel("💰 SALES MANAGEMENT SYSTEM");
    titleLabel.setFont(new Font("Segoe UI", Font.BOLD, 24));
    titleLabel.setForeground(new Color(52, 152, 219));
    titlePanel.add(titleLabel);
    
    // ================= STATS CARDS (5 Cards) =================
    JPanel statsPanel = new JPanel(new GridLayout(1, 5, 12, 0));
    statsPanel.setOpaque(false);
    statsPanel.setBorder(new EmptyBorder(20, 0, 20, 0));
    
    StatCard totalSalesCard = new StatCard("💰 Total Sales", "TSh 0", new Color(46, 204, 113));
    StatCard itemsSoldCard = new StatCard("📦 Items Sold", "0", new Color(52, 152, 219));
    StatCard discountCard = new StatCard("🎁 Discount", "TSh 0", new Color(255, 193, 7));
    StatCard netSalesCard = new StatCard("📊 Net Sales", "TSh 0", new Color(155, 89, 182));
    StatCard salesTargetCard = new StatCard("🎯 Sales Target", "Not Set", new Color(231, 76, 60));
    
    statsPanel.add(totalSalesCard);
    statsPanel.add(itemsSoldCard);
    statsPanel.add(discountCard);
    statsPanel.add(netSalesCard);
    statsPanel.add(salesTargetCard);
    
    // ================= DATE RANGE & MENU BUTTONS =================
    JPanel controlPanel = new JPanel(new FlowLayout(FlowLayout.CENTER, 15, 10));
    controlPanel.setOpaque(false);
    controlPanel.setBorder(new EmptyBorder(10, 0, 20, 0));
    
    // Date range with calendar
    JLabel fromLabel = new JLabel("From:");
    fromLabel.setForeground(Color.WHITE);
    fromLabel.setFont(new Font("Segoe UI", Font.BOLD, 12));
    
    JButton fromBtn = new JButton("📅 " + LocalDate.now().minusDays(30).toString());
    fromBtn.setBackground(new Color(52, 152, 219));
    fromBtn.setForeground(Color.WHITE);
    fromBtn.setFocusPainted(false);
    fromBtn.setCursor(new Cursor(Cursor.HAND_CURSOR));
    fromBtn.setFont(new Font("Segoe UI", Font.PLAIN, 11));
    
    JLabel toLabel = new JLabel("To:");
    toLabel.setForeground(Color.WHITE);
    toLabel.setFont(new Font("Segoe UI", Font.BOLD, 12));
    
    JButton toBtn = new JButton("📅 " + LocalDate.now().toString());
    toBtn.setBackground(new Color(52, 152, 219));
    toBtn.setForeground(Color.WHITE);
    toBtn.setFocusPainted(false);
    toBtn.setCursor(new Cursor(Cursor.HAND_CURSOR));
    toBtn.setFont(new Font("Segoe UI", Font.PLAIN, 11));
    
    // Calendar popups
    fromBtn.addActionListener(e -> selectDate(fromBtn, true, fromBtn, toBtn, clientIdFilter, 
        totalSalesCard, itemsSoldCard, discountCard, netSalesCard, salesTargetCard));
    toBtn.addActionListener(e -> selectDate(toBtn, false, fromBtn, toBtn, clientIdFilter, 
        totalSalesCard, itemsSoldCard, discountCard, netSalesCard, salesTargetCard));
    
    // Menu buttons
    JButton targetBtn = createIconButton("Sales Target", "💰", new Color(255, 193, 7));
    JButton trendBtn = createIconButton("Product Trend", "📈", new Color(52, 152, 219));
    JButton userTrendBtn = createIconButton("User Trend", "👥", new Color(155, 89, 182));
    
    controlPanel.add(fromLabel);
    controlPanel.add(fromBtn);
    controlPanel.add(toLabel);
    controlPanel.add(toBtn);
    controlPanel.add(targetBtn);
    controlPanel.add(trendBtn);
    controlPanel.add(userTrendBtn);
    
    // ================= SALES TABLE =================
    String[] columns = {"Product Name", "Quantity", "Unit Price", "Total Price", "User"};
    DefaultTableModel model = new DefaultTableModel(columns, 0) {
        @Override public boolean isCellEditable(int r, int c) { return false; }
    };
    
    JTable salesTable = new JTable(model);
    styleModernTable(salesTable);
    
    // Set column widths
    salesTable.getColumnModel().getColumn(0).setPreferredWidth(300);
    salesTable.getColumnModel().getColumn(1).setPreferredWidth(100);
    salesTable.getColumnModel().getColumn(2).setPreferredWidth(150);
    salesTable.getColumnModel().getColumn(3).setPreferredWidth(150);
    salesTable.getColumnModel().getColumn(4).setPreferredWidth(150);
    
    JScrollPane scrollPane = new JScrollPane(salesTable);
    scrollPane.setBorder(BorderFactory.createLineBorder(new Color(52, 152, 219, 60), 2));
    scrollPane.getViewport().setBackground(new Color(30, 34, 42));
    scrollPane.getVerticalScrollBar().setUI(new ModernScrollBarUI());
    
    // ================= BOTTOM SUMMARY LABELS =================
    JPanel bottomPanel = new JPanel(new GridLayout(1, 3, 20, 0));
    bottomPanel.setOpaque(false);
    bottomPanel.setBorder(new EmptyBorder(20, 0, 0, 0));
    
    JLabel totalEntriesLabel = createSummaryLabel("📋 Total Product Entries: 0");
    JLabel totalProfitLabel = createSummaryLabel("💰 Total Profit: TSh 0");
    JLabel totalUsersLabel = createSummaryLabel("👥 Total User Entries: 0");
    
    bottomPanel.add(totalEntriesLabel);
    bottomPanel.add(totalProfitLabel);
    bottomPanel.add(totalUsersLabel);
    
    // ================= ASSEMBLE PANEL =================
    mainPanel.add(titlePanel, BorderLayout.NORTH);
    mainPanel.add(statsPanel, BorderLayout.CENTER);
    mainPanel.add(controlPanel, BorderLayout.BEFORE_FIRST_LINE);
    mainPanel.add(scrollPane, BorderLayout.SOUTH);
    mainPanel.add(bottomPanel, BorderLayout.PAGE_END);
    
    // Store target value locally
    final BigDecimal[] salesTarget = {BigDecimal.ZERO};
    
    // ================= BUTTON ACTIONS =================
    targetBtn.addActionListener(e -> {
        String input = JOptionPane.showInputDialog(mainPanel, 
            "Enter your sales target amount (TSh):", 
            "Set Sales Target", JOptionPane.QUESTION_MESSAGE);
        if (input != null && !input.trim().isEmpty()) {
            try {
                salesTarget[0] = new BigDecimal(input.trim());
                salesTargetCard.setValue("TSh " + formatNumber(salesTarget[0]));
                showMessage(mainPanel, "Sales target set to TSh " + formatNumber(salesTarget[0]), 
                    "Target Set", "success");
            } catch (NumberFormatException ex) {
                showMessage(mainPanel, "Invalid amount entered", "Error", "error");
            }
        }
    });
    
    trendBtn.addActionListener(e -> {
        String fromDate = fromBtn.getText().replace("📅 ", "");
        String toDate = toBtn.getText().replace("📅 ", "");
        showProductTrendDialog(fromDate, toDate, clientIdFilter);
    });
    
    userTrendBtn.addActionListener(e -> {
        String fromDate = fromBtn.getText().replace("📅 ", "");
        String toDate = toBtn.getText().replace("📅 ", "");
        showUserTrendDialog(fromDate, toDate, clientIdFilter, salesTarget[0]);
    });
    
    // Load data on date change
    Runnable loadData = () -> {
        String fromDate = fromBtn.getText().replace("📅 ", "");
        String toDate = toBtn.getText().replace("📅 ", "");
        loadSalesData(fromDate, toDate, clientIdFilter, model, totalSalesCard, itemsSoldCard, 
            discountCard, netSalesCard, totalEntriesLabel, totalProfitLabel, totalUsersLabel);
    };
    
    fromBtn.addActionListener(e -> loadData.run());
    toBtn.addActionListener(e -> loadData.run());
    
    // Auto load on panel show
    SwingUtilities.invokeLater(loadData);
    
    return mainPanel;
}

private void selectDate(JButton btn, boolean isFrom, JButton fromBtn, JButton toBtn, String clientId,
        StatCard totalSalesCard, StatCard itemsSoldCard, StatCard discountCard,
        StatCard netSalesCard, StatCard salesTargetCard) {
    JDateChooser chooser = new JDateChooser();
    try {
        String current = btn.getText().replace("📅 ", "");
        chooser.setDate(java.sql.Date.valueOf(current));
    } catch (Exception ex) {
        chooser.setDate(new java.util.Date());
    }
    int result = JOptionPane.showConfirmDialog(null, chooser, 
        isFrom ? "Select Start Date" : "Select End Date",
        JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
    if (result == JOptionPane.OK_OPTION && chooser.getDate() != null) {
        java.sql.Date selected = new java.sql.Date(chooser.getDate().getTime());
        btn.setText("📅 " + selected.toString());
    }
}

private void loadSalesData(String fromDate, String toDate, String clientId, DefaultTableModel model,
        StatCard totalSalesCard, StatCard itemsSoldCard, StatCard discountCard,
        StatCard netSalesCard, JLabel totalEntriesLabel, JLabel totalProfitLabel, JLabel totalUsersLabel) {
    
    model.setRowCount(0);
    
    int totalQuantity = 0;
    BigDecimal totalSales = BigDecimal.ZERO;
    BigDecimal totalDiscount = BigDecimal.ZERO;
    BigDecimal totalCost = BigDecimal.ZERO;
    Set<String> uniqueUsers = new HashSet<>();
    int rowCount = 0;
    
    String sql = "SELECT p.name, si.quantity, si.unit_price, si.total_price, s.discount, p.cost_price, s.user " +
                "FROM sales s " +
                "JOIN sale_items si ON s.id = si.sale_id " +
                "JOIN products p ON si.product_id = p.id " +
                "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ?";
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, clientId);
        stmt.setString(2, fromDate);
        stmt.setString(3, toDate);
        ResultSet rs = stmt.executeQuery();
        
        while (rs.next()) {
            int qty = rs.getInt("quantity");
            BigDecimal subtotal = rs.getBigDecimal("total_price");
            BigDecimal discount = rs.getBigDecimal("discount");
            BigDecimal costPrice = rs.getBigDecimal("cost_price");
            String user = rs.getString("user");
            
            totalQuantity += qty;
            totalSales = totalSales.add(subtotal);
            totalDiscount = totalDiscount.add(discount);
            totalCost = totalCost.add(costPrice.multiply(BigDecimal.valueOf(qty)));
            if (user != null) uniqueUsers.add(user);
            rowCount++;
            
            model.addRow(new Object[]{
                rs.getString("name"),
                qty,
                "TSh " + formatNumber(rs.getBigDecimal("unit_price")),
                "TSh " + formatNumber(subtotal),
                user != null ? user : "System"
            });
        }
        
        BigDecimal netSales = totalSales.subtract(totalDiscount);
        BigDecimal totalProfit = netSales.subtract(totalCost);
        
        totalSalesCard.setValue("TSh " + formatNumber(totalSales));
        itemsSoldCard.setValue(String.valueOf(totalQuantity));
        discountCard.setValue("TSh " + formatNumber(totalDiscount));
        netSalesCard.setValue("TSh " + formatNumber(netSales));
        totalEntriesLabel.setText("📋 Total Product Entries: " + rowCount);
        totalProfitLabel.setText("💰 Total Profit: TSh " + formatNumber(totalProfit));
        totalUsersLabel.setText("👥 Total User Entries: " + uniqueUsers.size());
        
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading sales data", e);
        showMessage(null, "Error loading sales: " + e.getMessage(), "Error", "error");
    }
}

private void showProductTrendDialog(String fromDate, String toDate, String clientId) {
    JDialog dialog = new JDialog((Frame) SwingUtilities.getWindowAncestor(this), "Product Trend Analysis", true);
    dialog.setSize(800, 600);
    dialog.setLocationRelativeTo(this);
    dialog.setUndecorated(true);
    dialog.setBackground(new Color(0, 0, 0, 0));
    
    JPanel glass = new JPanel() {
        @Override protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(new Color(10, 12, 18));
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), 20, 20);
            g2.setColor(new Color(52, 152, 219, 160));
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawRoundRect(1, 1, getWidth()-3, getHeight()-3, 20, 20);
            g2.dispose();
        }
    };
    glass.setLayout(new BorderLayout());
    glass.setBorder(new EmptyBorder(15, 15, 15, 15));
    
    JLabel title = new JLabel("📈 Product Trend Analysis");
    title.setFont(new Font("Segoe UI", Font.BOLD, 20));
    title.setForeground(new Color(52, 152, 219));
    title.setHorizontalAlignment(SwingConstants.CENTER);
    
    String[] columns = {"Rank", "Product Name", "Quantity Sold", "Revenue", "Percentage"};
    DefaultTableModel trendModel = new DefaultTableModel(columns, 0) {
        @Override public boolean isCellEditable(int r, int c) { return false; }
    };
    
    JTable trendTable = new JTable(trendModel);
    styleModernTable(trendTable);
    
    String sql = "SELECT p.name, SUM(si.quantity) as total_qty, SUM(si.total_price) as total_revenue " +
                "FROM sale_items si " +
                "JOIN sales s ON si.sale_id = s.id " +
                "JOIN products p ON si.product_id = p.id " +
                "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ? " +
                "GROUP BY p.id ORDER BY total_revenue DESC";
    
    BigDecimal totalRevenue = BigDecimal.ZERO;
    List<Object[]> data = new ArrayList<>();
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, clientId);
        stmt.setString(2, fromDate);
        stmt.setString(3, toDate);
        ResultSet rs = stmt.executeQuery();
        
        int rank = 1;
        while (rs.next()) {
            BigDecimal revenue = rs.getBigDecimal("total_revenue");
            totalRevenue = totalRevenue.add(revenue);
            data.add(new Object[]{
                rank++, rs.getString("name"), rs.getInt("total_qty"), revenue
            });
        }
        
        for (Object[] row : data) {
            BigDecimal revenue = (BigDecimal) row[3];
            double percentage = totalRevenue.compareTo(BigDecimal.ZERO) > 0 ?
                revenue.doubleValue() / totalRevenue.doubleValue() * 100 : 0;
            trendModel.addRow(new Object[]{
                row[0], row[1], row[2], "TSh " + formatNumber(revenue), String.format("%.1f%%", percentage)
            });
        }
        
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading product trend", e);
    }
    
    JScrollPane scrollPane = new JScrollPane(trendTable);
    scrollPane.setBorder(BorderFactory.createLineBorder(new Color(60, 80, 100), 1));
    
    JButton closeBtn = createActionButton("Close", new Color(149, 165, 166));
    closeBtn.addActionListener(e -> dialog.dispose());
    
    JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
    btnPanel.setOpaque(false);
    btnPanel.add(closeBtn);
    
    glass.add(title, BorderLayout.NORTH);
    glass.add(scrollPane, BorderLayout.CENTER);
    glass.add(btnPanel, BorderLayout.SOUTH);
    
    dialog.setContentPane(glass);
    dialog.setVisible(true);
}

private void showUserTrendDialog(String fromDate, String toDate, String clientId, BigDecimal salesTarget) {
    JDialog dialog = new JDialog((Frame) SwingUtilities.getWindowAncestor(this), "User Performance Ranking", true);
    dialog.setSize(900, 650);
    dialog.setLocationRelativeTo(this);
    dialog.setUndecorated(true);
    dialog.setBackground(new Color(0, 0, 0, 0));
    
    JPanel glass = new JPanel() {
        @Override protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(new Color(10, 12, 18));
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), 20, 20);
            g2.setColor(new Color(155, 89, 182, 160));
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawRoundRect(1, 1, getWidth()-3, getHeight()-3, 20, 20);
            g2.dispose();
        }
    };
    glass.setLayout(new BorderLayout());
    glass.setBorder(new EmptyBorder(15, 15, 15, 15));
    
    JLabel title = new JLabel("👥 User Performance Ranking");
    title.setFont(new Font("Segoe UI", Font.BOLD, 20));
    title.setForeground(new Color(155, 89, 182));
    title.setHorizontalAlignment(SwingConstants.CENTER);
    
    String[] columns = {"Rank", "User", "Total Sales", "Status", "Performance"};
    DefaultTableModel userModel = new DefaultTableModel(columns, 0) {
        @Override public boolean isCellEditable(int r, int c) { return false; }
    };
    
    JTable userTable = new JTable(userModel);
    styleModernTable(userTable);
    
    String sql = "SELECT s.user, COALESCE(SUM(si.total_price), 0) as total_sales " +
                "FROM sales s " +
                "JOIN sale_items si ON s.id = si.sale_id " +
                "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ? " +
                "GROUP BY s.user ORDER BY total_sales DESC";
    
    List<Object[]> userData = new ArrayList<>();
    BigDecimal totalSalesAll = BigDecimal.ZERO;
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, clientId);
        stmt.setString(2, fromDate);
        stmt.setString(3, toDate);
        ResultSet rs = stmt.executeQuery();
        
        int rank = 1;
        while (rs.next()) {
            BigDecimal sales = rs.getBigDecimal("total_sales");
            totalSalesAll = totalSalesAll.add(sales);
            
            String status;
            String performance;
            
            if (salesTarget.compareTo(BigDecimal.ZERO) > 0) {
                if (sales.compareTo(salesTarget) >= 0) {
                    status = "✅ TARGET ACHIEVED";
                    performance = "🎉 Excellent!";
                } else {
                    double percent = sales.doubleValue() / salesTarget.doubleValue() * 100;
                    status = "⚠️ BELOW TARGET";
                    performance = String.format("📉 %.1f%% of target", percent);
                }
            } else {
                status = "📊 NO TARGET SET";
                performance = "Set target from main panel";
            }
            
            userData.add(new Object[]{rank++, rs.getString("user"), sales, status, performance});
        }
        
        // Find top performer
        if (!userData.isEmpty()) {
            userData.get(0)[4] = "🏆 TOP PERFORMER - " + userData.get(0)[4];
        }
        
        // Find bottom performer
        if (userData.size() > 1) {
            Object[] last = userData.get(userData.size() - 1);
            last[4] = "⚠️ NEED IMPROVEMENT - " + last[4];
        }
        
        for (Object[] row : userData) {
            userModel.addRow(new Object[]{
                row[0], row[1], "TSh " + formatNumber((BigDecimal) row[2]), row[3], row[4]
            });
        }
        
        // Add summary row
        if (userData.size() > 0) {
            userModel.addRow(new Object[]{"---", "---", "---", "---", "---"});
            userModel.addRow(new Object[]{"", "TOTAL SALES", "TSh " + formatNumber(totalSalesAll), 
                salesTarget.compareTo(BigDecimal.ZERO) > 0 && totalSalesAll.compareTo(salesTarget) >= 0 ? "✅ TARGET MET" : "⚠️ TARGET NOT MET", ""});
        } else {
            userModel.addRow(new Object[]{"", "No sales data found", "", "", ""});
        }
        
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading user trend", e);
    }
    
    // Target summary panel
    JPanel targetSummary = new JPanel(new FlowLayout(FlowLayout.CENTER));
    targetSummary.setOpaque(false);
    targetSummary.setBorder(BorderFactory.createTitledBorder(
        BorderFactory.createLineBorder(new Color(255, 193, 7), 1),
        "Target Summary",
        TitledBorder.LEFT, TitledBorder.TOP,
        new Font("Segoe UI", Font.BOLD, 12),
        new Color(255, 193, 7)
    ));
    
    JLabel targetLabel = new JLabel("Sales Target: " + (salesTarget.compareTo(BigDecimal.ZERO) > 0 ? 
        "TSh " + formatNumber(salesTarget) : "Not Set (Click Sales Target button to set)"));
    targetLabel.setFont(new Font("Segoe UI", Font.PLAIN, 12));
    targetLabel.setForeground(new Color(255, 193, 7));
    targetSummary.add(targetLabel);
    
    JScrollPane scrollPane = new JScrollPane(userTable);
    scrollPane.setBorder(BorderFactory.createLineBorder(new Color(60, 80, 100), 1));
    
    JButton closeBtn = createActionButton("Close", new Color(149, 165, 166));
    closeBtn.addActionListener(e -> dialog.dispose());
    
    JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
    btnPanel.setOpaque(false);
    btnPanel.add(closeBtn);
    
    glass.add(title, BorderLayout.NORTH);
    glass.add(targetSummary, BorderLayout.BEFORE_FIRST_LINE);
    glass.add(scrollPane, BorderLayout.CENTER);
    glass.add(btnPanel, BorderLayout.SOUTH);
    
    dialog.setContentPane(glass);
    dialog.setVisible(true);
}

