    receivedTable.getColumnModel().getColumn(2).setPreferredWidth(120);
    receivedTable.getColumnModel().getColumn(3).setPreferredWidth(120);
    receivedTable.getColumnModel().getColumn(4).setPreferredWidth(80);
    receivedTable.getColumnModel().getColumn(5).setPreferredWidth(120);
    
