private void loadProfitLossChart(JTextArea area, String fromDate, String toDate, String clientId) {
    StringBuilder chart = new StringBuilder();
    chart.append("PROFIT BREAKDOWN\n");
    chart.append("=".repeat(50)).append("\n\n");
    
    try (Connection conn = Database.getConnection()) {
        // Get total sales
        String salesSql = "SELECT COALESCE(SUM(si.total_price), 0) as sales, " +
                         "COALESCE(SUM(s.discount), 0) as discount " +
                         "FROM sales s JOIN sale_items si ON s.id = si.sale_id " +
                         "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ?";
        
        BigDecimal netSales = BigDecimal.ZERO;
        try (PreparedStatement stmt = conn.prepareStatement(salesSql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                netSales = rs.getBigDecimal("sales").subtract(rs.getBigDecimal("discount"));
            }
        }
        
        // Get COGS
        String cogsSql = "SELECT COALESCE(SUM(si.quantity * p.cost_price), 0) as cogs " +
                        "FROM sale_items si JOIN sales s ON si.sale_id = s.id " +
                        "JOIN products p ON si.product_id = p.id " +
                        "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ?";
        
        BigDecimal cogs = BigDecimal.ZERO;
        try (PreparedStatement stmt = conn.prepareStatement(cogsSql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) cogs = rs.getBigDecimal("cogs");
        }
        
        BigDecimal profit = netSales.subtract(cogs);
        double profitPercent = netSales.compareTo(BigDecimal.ZERO) > 0 ?
            profit.doubleValue() / netSales.doubleValue() * 100 : 0;
        double cogsPercent = netSales.compareTo(BigDecimal.ZERO) > 0 ?
            cogs.doubleValue() / netSales.doubleValue() * 100 : 0;
        
        int barWidth = 40;
        int profitBars = (int) (profitPercent / 100 * barWidth);
        int cogsBars = (int) (cogsPercent / 100 * barWidth);
        
        chart.append(String.format("Net Sales: TSh %s\n", formatNumber(netSales)));
        chart.append(String.format("COGS:      TSh %s (%.1f%%)\n", formatNumber(cogs), cogsPercent));
        chart.append(String.format("Profit:    TSh %s (%.1f%%)\n\n", formatNumber(profit), profitPercent));
        
        chart.append("DISTRIBUTION CHART\n");
        chart.append("-".repeat(40)).append("\n");
        chart.append(String.format("🟢 Profit: %s\n", "█".repeat(Math.max(1, profitBars))));
        chart.append(String.format("🔴 COGS:   %s\n", "█".repeat(Math.max(1, cogsBars))));
        
        if (profit.compareTo(BigDecimal.ZERO) > 0) {
            chart.append("\n✅ PROFITABLE PERIOD");
        } else {
            chart.append("\n❌ LOSS PERIOD");
        }
        
    } catch (SQLException e) {
        chart.append("Error: " + e.getMessage());
    }
    
    area.setText(chart.toString());
}

private void updateSummaryCards(String fromDate, String toDate, String clientId,
        StatCard totalSalesCard, StatCard totalDiscountCard, StatCard netSalesCard,
        StatCard transactionCountCard, StatCard avgTransactionCard, StatCard totalItemsCard,
        StatCard profitCard, StatCard topStaffCard) {
    
    try (Connection conn = Database.getConnection()) {
        String sql = "SELECT COALESCE(SUM(si.total_price), 0) as sales, " +
                    "COALESCE(SUM(s.discount), 0) as discount, " +
                    "COUNT(DISTINCT s.id) as orders, " +
                    "COALESCE(SUM(si.quantity), 0) as items " +
                    "FROM sales s JOIN sale_items si ON s.id = si.sale_id " +
                    "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ?";
        
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            
            if (rs.next()) {
                BigDecimal sales = rs.getBigDecimal("sales");
                BigDecimal discount = rs.getBigDecimal("discount");
                BigDecimal netSales = sales.subtract(discount);
                int orders = rs.getInt("orders");
                int items = rs.getInt("items");
                BigDecimal avgTransaction = orders > 0 ? netSales.divide(BigDecimal.valueOf(orders), 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
                
                totalSalesCard.setValue("TSh " + formatNumber(sales));
                totalDiscountCard.setValue("TSh " + formatNumber(discount));
                netSalesCard.setValue("TSh " + formatNumber(netSales));
                transactionCountCard.setValue(String.valueOf(orders));
                avgTransactionCard.setValue("TSh " + formatNumber(avgTransaction));
                totalItemsCard.setValue(String.valueOf(items));
            }
        }
        
        // Get profit and top staff
        String profitSql = "SELECT COALESCE(SUM(si.quantity * p.cost_price), 0) as cogs " +
                          "FROM sale_items si JOIN sales s ON si.sale_id = s.id " +
                          "JOIN products p ON si.product_id = p.id " +
                          "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ?";
        
        BigDecimal cogs = BigDecimal.ZERO;
        try (PreparedStatement stmt = conn.prepareStatement(profitSql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) cogs = rs.getBigDecimal("cogs");
        }
        
        // Get sales total again for profit calculation
        BigDecimal totalSales = BigDecimal.ZERO;
        BigDecimal totalDiscount = BigDecimal.ZERO;
        String salesSql = "SELECT COALESCE(SUM(si.total_price), 0) as sales, COALESCE(SUM(s.discount), 0) as discount " +
                         "FROM sales s JOIN sale_items si ON s.id = si.sale_id " +
                         "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ?";
        try (PreparedStatement stmt = conn.prepareStatement(salesSql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                totalSales = rs.getBigDecimal("sales");
                totalDiscount = rs.getBigDecimal("discount");
            }
        }
        
        BigDecimal netSalesCalc = totalSales.subtract(totalDiscount);
        BigDecimal profit = netSalesCalc.subtract(cogs);
        profitCard.setValue((profit.compareTo(BigDecimal.ZERO) >= 0 ? "🟢 " : "🔴 ") + "TSh " + formatNumber(profit));
        
        // Get top staff
        String staffSql = "SELECT s.user, SUM(si.total_price) as revenue " +
                         "FROM sales s JOIN sale_items si ON s.id = si.sale_id " +
                         "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ? " +
                         "GROUP BY s.user ORDER BY revenue DESC LIMIT 1";
        
        try (PreparedStatement stmt = conn.prepareStatement(staffSql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                topStaffCard.setValue(rs.getString("user") + " (TSh " + formatNumber(rs.getBigDecimal("revenue")) + ")");
            } else {
                topStaffCard.setValue("-");
            }
        }
        
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error updating summary cards", e);
    }
}

