private void loadStaffPerformanceReport(String fromDate, String toDate, String clientId, DefaultTableModel model) {
    model.setRowCount(0);
    
    BigDecimal totalRevenue = BigDecimal.ZERO;
    List<StaffPerformance> performances = new ArrayList<>();
    
    try (Connection conn = Database.getConnection()) {
        String sql = 
            "SELECT s.user, COUNT(DISTINCT s.id) as sales_count, " +
            "SUM(si.quantity) as items_sold, " +
            "COALESCE(SUM(si.total_price), 0) as total_revenue, " +
            "COALESCE(AVG(si.total_price), 0) as avg_transaction " +
            "FROM sales s " +
            "JOIN sale_items si ON s.id = si.sale_id " +
            "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ? " +
            "GROUP BY s.user " +
            "ORDER BY total_revenue DESC";
        
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            
            while (rs.next()) {
                BigDecimal revenue = rs.getBigDecimal("total_revenue");
                totalRevenue = totalRevenue.add(revenue);
                
                StaffPerformance sp = new StaffPerformance();
                sp.staff = rs.getString("user");
                sp.salesCount = rs.getInt("sales_count");
                sp.itemsSold = rs.getInt("items_sold");
                sp.revenue = revenue;
                sp.avgTransaction = rs.getBigDecimal("avg_transaction");
                performances.add(sp);
            }
        }
        
        // Calculate contributions and bonuses
        for (StaffPerformance sp : performances) {
            double contribution = totalRevenue.compareTo(BigDecimal.ZERO) > 0 ?
                sp.revenue.doubleValue() / totalRevenue.doubleValue() * 100 : 0;
            BigDecimal bonus = sp.revenue.multiply(BigDecimal.valueOf(0.02)); // 2% bonus
            
            // Determine bonus color based on performance
            String bonusText = "TSh " + formatNumber(bonus);
            if (sp.salesCount > 50) {
                bonusText = "🏆 " + bonusText;
            } else if (sp.salesCount > 20) {
                bonusText = "⭐ " + bonusText;
            }
            
            model.addRow(new Object[]{
                sp.staff,
                sp.salesCount,
                sp.itemsSold,
                "TSh " + formatNumber(sp.revenue),
                "TSh " + formatNumber(sp.avgTransaction),
                String.format("%.1f%%", contribution),
                bonusText
            });
        }
        
        // Add summary row
        if (performances.size() > 0) {
            model.addRow(new Object[]{
                "━━━━━━━━━━", "━━━━━━", "━━━━━━", "━━━━━━━━━━━━", "━━━━━━━━━━━━", "━━━━━━━━", "━━━━━━━━━━"
            });
            model.addRow(new Object[]{
                "TOTAL / AVERAGE",
                performances.stream().mapToInt(p -> p.salesCount).sum(),
                performances.stream().mapToInt(p -> p.itemsSold).sum(),
                "TSh " + formatNumber(totalRevenue),
                "TSh " + formatNumber(totalRevenue.divide(BigDecimal.valueOf(performances.size()), 2, RoundingMode.HALF_UP)),
                "100%",
                "-"
            });
        }
        
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading staff performance", e);
        showGlassMessage(null, "Error loading staff performance: " + e.getMessage(), "Error", "error");
    }
}

// Export staff performance to Excel
private void exportStaffPerformanceToExcel(DefaultTableModel model, String fromDate, String toDate) {
    JFileChooser fileChooser = new JFileChooser();
    fileChooser.setDialogTitle("Export Staff Performance Report");
    fileChooser.setSelectedFile(new File("staff_performance_" + fromDate + "_to_" + toDate + ".csv"));
    
    if (fileChooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
        try (PrintWriter pw = new PrintWriter(fileChooser.getSelectedFile())) {
            pw.println("Staff Performance Report");
            pw.println("Period: " + fromDate + " to " + toDate);
            pw.println("Generated: " + LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
            pw.println();
            
            // Write headers
            for (int i = 0; i < model.getColumnCount(); i++) {
                pw.print("\"" + model.getColumnName(i) + "\"");
                if (i < model.getColumnCount() - 1) pw.print(",");
            }
            pw.println();
            
            // Write data (skip separator row)
            for (int row = 0; row < model.getRowCount(); row++) {
                String firstCol = model.getValueAt(row, 0).toString();
                if (firstCol.contains("━━━━")) continue; // Skip separator
                
                for (int col = 0; col < model.getColumnCount(); col++) {
                    Object value = model.getValueAt(row, col);
                    pw.print("\"" + (value != null ? value.toString() : "") + "\"");
                    if (col < model.getColumnCount() - 1) pw.print(",");
                }
                pw.println();
            }
            
            showGlassMessage(null, "Staff performance report exported successfully!", "Success", "success");
        } catch (IOException e) {
            showGlassMessage(null, "Error exporting: " + e.getMessage(), "Error", "error");
        }
    }
}

