private void generateProfitLossReport(String fromDate, String toDate, String clientId, JTextArea resultArea) {
    StringBuilder report = new StringBuilder();
    report.append("=".repeat(60)).append("\n");
    report.append("PROFIT & LOSS STATEMENT\n");
    report.append("=".repeat(60)).append("\n");
    report.append(String.format("Period: %s to %s\n", fromDate, toDate));
    report.append(String.format("Generated: %s\n\n", LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))));
    
    try (Connection conn = Database.getConnection()) {
        // Total Sales with client_id filter
        String salesSql = "SELECT COALESCE(SUM(si.total_price), 0) as total_sales, " +
                         "COALESCE(SUM(s.discount), 0) as total_discount " +
                         "FROM sales s JOIN sale_items si ON s.id = si.sale_id " +
                         "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ?";
        
        BigDecimal totalSales = BigDecimal.ZERO;
        BigDecimal totalDiscount = BigDecimal.ZERO;
        
        try (PreparedStatement stmt = conn.prepareStatement(salesSql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                totalSales = rs.getBigDecimal("total_sales");
                totalDiscount = rs.getBigDecimal("total_discount");
            }
        }
        
        // Cost of Goods Sold with client_id filter
        String cogsSql = "SELECT COALESCE(SUM(si.quantity * p.cost_price), 0) as cogs " +
                        "FROM sale_items si " +
                        "JOIN sales s ON si.sale_id = s.id " +
                        "JOIN products p ON si.product_id = p.id " +
                        "WHERE s.client_id = ? AND DATE(s.sale_date) BETWEEN ? AND ?";
        
        BigDecimal cogs = BigDecimal.ZERO;
        try (PreparedStatement stmt = conn.prepareStatement(cogsSql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                cogs = rs.getBigDecimal("cogs");
            }
        }
        
        // Expenses with client_id filter
        String expenseSql = "SELECT COALESCE(SUM(amount), 0) as expenses " +
                           "FROM daily_expenses " +
                           "WHERE client_id = ? AND DATE(expense_date) BETWEEN ? AND ?";
        
        BigDecimal expenses = BigDecimal.ZERO;
        try (PreparedStatement stmt = conn.prepareStatement(expenseSql)) {
            stmt.setString(1, clientId);
            stmt.setString(2, fromDate);
            stmt.setString(3, toDate);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                expenses = rs.getBigDecimal("expenses");
            }
        }
        
        BigDecimal netSales = totalSales.subtract(totalDiscount);
        BigDecimal grossProfit = netSales.subtract(cogs);
        BigDecimal netProfit = grossProfit.subtract(expenses);
        BigDecimal profitMargin = netSales.compareTo(BigDecimal.ZERO) > 0 ?
            netProfit.multiply(BigDecimal.valueOf(100)).divide(netSales, 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
        
        // Color-coded output
        String profitColor = netProfit.compareTo(BigDecimal.ZERO) >= 0 ? "✅" : "❌";
        
        report.append(String.format("%-30s %20s\n", "REVENUE", "Amount (TSh)"));
        report.append("-".repeat(55)).append("\n");
        report.append(String.format("%-30s %20s\n", "Gross Sales", formatNumber(totalSales)));
        report.append(String.format("%-30s %20s\n", "Less: Discounts", formatNumber(totalDiscount)));
        report.append(String.format("%-30s %20s\n", "Net Sales", formatNumber(netSales)));
        report.append("\n");
        report.append(String.format("%-30s %20s\n", "COST OF GOODS SOLD", ""));
        report.append("-".repeat(55)).append("\n");
        report.append(String.format("%-30s %20s\n", "Cost of Goods Sold", formatNumber(cogs)));
        report.append("\n");
        report.append(String.format("%-30s %20s\n", "GROSS PROFIT", formatNumber(grossProfit)));
        report.append("\n");
        report.append(String.format("%-30s %20s\n", "OPERATING EXPENSES", ""));
        report.append("-".repeat(55)).append("\n");
        report.append(String.format("%-30s %20s\n", "Total Expenses", formatNumber(expenses)));
        report.append("\n");
        report.append(String.format("%-30s %20s\n", "NET PROFIT " + profitColor, formatNumber(netProfit)));
        report.append("-".repeat(55)).append("\n");
        report.append(String.format("%-30s %20s\n", "Profit Margin", profitMargin + "%"));
        
        // Add recommendation
        double profitMarginValue = profitMargin.doubleValue();
        if (profitMarginValue > 20) {
            report.append("\n💡 Excellent profit margin! Keep up the good work!");
        } else if (profitMarginValue > 10) {
            report.append("\n💡 Good profit margin. Look for ways to reduce costs.");
        } else if (profitMarginValue > 0) {
            report.append("\n💡 Low profit margin. Consider increasing prices or reducing expenses.");
        } else {
            report.append("\n⚠️ Operating at a loss. Review expenses and pricing strategy immediately!");
        }
        
    } catch (SQLException e) {
        report.append("Error generating report: ").append(e.getMessage());
        LOGGER.log(Level.SEVERE, "Error generating profit/loss report", e);
    }
    
    resultArea.setText(report.toString());
    resultArea.setCaretPosition(0);
}

private void exportProfitLossToExcel(String reportText, String fromDate, String toDate) {
    JFileChooser fileChooser = new JFileChooser();
    fileChooser.setDialogTitle("Export Profit & Loss Report");
    fileChooser.setSelectedFile(new File("profit_loss_" + fromDate + "_to_" + toDate + ".txt"));
    
    if (fileChooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
        try (PrintWriter pw = new PrintWriter(fileChooser.getSelectedFile())) {
            pw.println(reportText);
            showGlassMessage(null, "Profit & Loss report exported successfully!", "Success", "success");
        } catch (IOException e) {
            showGlassMessage(null, "Error exporting: " + e.getMessage(), "Error", "error");
        }
    }
}
private JPanel createModernSummaryCard(String title, String value, Color color) {
    JPanel card = new JPanel() {
        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            // Dark glass background
            g2.setColor(new Color(18, 22, 32));
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), 12, 12);
            // Colored top border
            g2.setColor(color);
            g2.fillRoundRect(0, 0, getWidth(), 4, 12, 12);
            // Border
            g2.setColor(color);
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawRoundRect(1, 1, getWidth() - 3, getHeight() - 3, 12, 12);
            g2.dispose();
        }
    };
    card.setOpaque(false);
    card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
    card.setBorder(new EmptyBorder(12, 12, 12, 12));
    
    JLabel titleLabel = new JLabel(title);
    titleLabel.setFont(new Font("Segoe UI", Font.PLAIN, 11));
    titleLabel.setForeground(new Color(180, 180, 200));
    titleLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
    
    JLabel valueLabel = new JLabel(value);
    valueLabel.setFont(new Font("Segoe UI", Font.BOLD, 18));
    valueLabel.setForeground(color);
    valueLabel.setAlignmentX(Component.CENTER_ALIGNMENT);
    
    card.add(titleLabel);
    card.add(Box.createVerticalStrut(5));
    card.add(valueLabel);
    
    return card;
}

