private void loadTopProducts(String fromDate, String toDate, int limit, DefaultTableModel model) {
    model.setRowCount(0);
    
    try (Connection conn = Database.getConnection()) {
        String sql = 
            "SELECT p.name, c.name as category, SUM(si.quantity) as total_sold, " +
            "SUM(si.total_price) as revenue, " +
            "SUM(si.quantity * p.cost_price) as cost, " +
            "SUM(si.total_price) - SUM(si.quantity * p.cost_price) as profit " +
            "FROM sale_items si " +
            "JOIN sales s ON si.sale_id = s.id " +
            "JOIN products p ON si.product_id = p.id " +
            "LEFT JOIN categories c ON p.category_id = c.id " +
            "WHERE DATE(s.sale_date) BETWEEN ? AND ? " +
            "GROUP BY p.id " +
            "ORDER BY total_sold DESC LIMIT ?";
        
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, fromDate);
            stmt.setString(2, toDate);
            stmt.setInt(3, limit);
            ResultSet rs = stmt.executeQuery();
            
            int rank = 1;
            while (rs.next()) {
                BigDecimal revenue = rs.getBigDecimal("revenue");
                BigDecimal profit = rs.getBigDecimal("profit");
                BigDecimal margin = revenue.compareTo(BigDecimal.ZERO) > 0 ?
                    profit.multiply(BigDecimal.valueOf(100)).divide(revenue, 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
                
                model.addRow(new Object[]{
                    rank++,
                    rs.getString("name"),
                    rs.getString("category") != null ? rs.getString("category") : "Uncategorized",
                    rs.getInt("total_sold"),
                    "TSh " + formatNumber(revenue),
                    "TSh " + formatNumber(profit),
                    margin + "%"
                });
            }
        }
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading top products", e);
    }
}

