private void loadSlowMoversReport(String fromDate, String toDate, DefaultTableModel model) {
    model.setRowCount(0);
    
    try (Connection conn = Database.getConnection()) {
        String sql = 
            "SELECT p.name, c.name as category, COALESCE(SUM(si.quantity), 0) as total_sold, " +
            "p.stock_quantity as current_stock " +
            "FROM products p " +
            "LEFT JOIN categories c ON p.category_id = c.id " +
            "LEFT JOIN sale_items si ON p.id = si.product_id " +
            "LEFT JOIN sales s ON si.sale_id = s.id AND DATE(s.sale_date) BETWEEN ? AND ? " +
            "GROUP BY p.id " +
            "HAVING total_sold < 5 OR total_sold IS NULL " +
            "ORDER BY total_sold ASC";
        
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, fromDate);
            stmt.setString(2, toDate);
            ResultSet rs = stmt.executeQuery();
            
            int rank = 1;
            while (rs.next()) {
                int sold = rs.getInt("total_sold");
                String status = sold == 0 ? "⚠️ NO SALES" : "🐌 SLOW MOVER";
                
                model.addRow(new Object[]{
                    rank++,
                    rs.getString("name"),
                    rs.getString("category") != null ? rs.getString("category") : "Uncategorized",
                    sold,
                    "-",
                    "-",
                    status
                });
            }
        }
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading slow movers", e);
    }
}

