private void generateDailyReport(String date, JTextArea reportArea) {
    StringBuilder report = new StringBuilder();
    report.append("=".repeat(60)).append("\n");
    report.append(String.format("DAILY SALES REPORT - %s\n", date));
    report.append("=".repeat(60)).append("\n\n");
    
    try (Connection conn = Database.getConnection()) {
        // Sales summary
        String salesSql = 
            "SELECT COALESCE(SUM(si.total_price), 0) as total_sales, " +
            "COALESCE(SUM(s.discount), 0) as discounts, " +
            "COUNT(DISTINCT s.id) as transactions, " +
            "COALESCE(SUM(si.quantity), 0) as items_sold " +
            "FROM sales s " +
            "JOIN sale_items si ON s.id = si.sale_id " +
            "WHERE DATE(s.sale_date) = ?";
        
        try (PreparedStatement stmt = conn.prepareStatement(salesSql)) {
            stmt.setString(1, date);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                BigDecimal sales = rs.getBigDecimal("total_sales");
                BigDecimal discounts = rs.getBigDecimal("discounts");
                int transactions = rs.getInt("transactions");
                int items = rs.getInt("items_sold");
                BigDecimal netSales = sales.subtract(discounts);
                
                report.append("SALES SUMMARY\n");
                report.append("-".repeat(40)).append("\n");
                report.append(String.format("Total Sales (Gross): TSh %s\n", formatNumber(sales)));
                report.append(String.format("Discounts: TSh %s\n", formatNumber(discounts)));
                report.append(String.format("Net Sales: TSh %s\n", formatNumber(netSales)));
                report.append(String.format("Number of Transactions: %d\n", transactions));
                report.append(String.format("Items Sold: %d\n", items));
                report.append(String.format("Average Transaction: TSh %s\n", 
                    transactions > 0 ? formatNumber(netSales.divide(BigDecimal.valueOf(transactions), 2, RoundingMode.HALF_UP)) : "0"));
            }
        }
        
        // Top products for the day
        String topSql = 
            "SELECT p.name, SUM(si.quantity) as qty_sold, SUM(si.total_price) as revenue " +
            "FROM sale_items si " +
            "JOIN sales s ON si.sale_id = s.id " +
            "JOIN products p ON si.product_id = p.id " +
            "WHERE DATE(s.sale_date) = ? " +
            "GROUP BY p.id " +
            "ORDER BY qty_sold DESC LIMIT 5";
        
        report.append("\nTOP 5 PRODUCTS\n");
        report.append("-".repeat(40)).append("\n");
        
        try (PreparedStatement stmt = conn.prepareStatement(topSql)) {
            stmt.setString(1, date);
            ResultSet rs = stmt.executeQuery();
            int rank = 1;
            while (rs.next()) {
                report.append(String.format("%d. %s - %d units (TSh %s)\n", 
                    rank++, rs.getString("name"), rs.getInt("qty_sold"), 
                    formatNumber(rs.getBigDecimal("revenue"))));
            }
        }
        
        // Staff performance for the day
        String staffSql = 
            "SELECT s.user, COUNT(DISTINCT s.id) as sales_count, SUM(si.total_price) as revenue " +
            "FROM sales s " +
            "JOIN sale_items si ON s.id = si.sale_id " +
            "WHERE DATE(s.sale_date) = ? " +
            "GROUP BY s.user " +
            "ORDER BY revenue DESC";
        
        report.append("\nSTAFF PERFORMANCE\n");
        report.append("-".repeat(40)).append("\n");
        
        try (PreparedStatement stmt = conn.prepareStatement(staffSql)) {
            stmt.setString(1, date);
            ResultSet rs = stmt.executeQuery();
            while (rs.next()) {
                report.append(String.format("%s: %d sales | TSh %s\n", 
                    rs.getString("user"), rs.getInt("sales_count"), 
                    formatNumber(rs.getBigDecimal("revenue"))));
            }
        }
        
    } catch (SQLException e) {
        report.append("Error: ").append(e.getMessage());
    }
    
    reportArea.setText(report.toString());
    reportArea.setCaretPosition(0);
}

private void compareDailyReports(String date1, String date2, JTextArea reportArea) {
    StringBuilder report = new StringBuilder();
    report.append("=".repeat(60)).append("\n");
    report.append("DAILY SALES COMPARISON\n");
    report.append("=".repeat(60)).append("\n");
    report.append(String.format("Day 1: %s\n", date1));
    report.append(String.format("Day 2: %s\n\n", date2));
    
    try (Connection conn = Database.getConnection()) {
        String sql = 
            "SELECT DATE(s.sale_date) as sale_date, " +
            "COALESCE(SUM(si.total_price), 0) as total_sales, " +
            "COALESCE(SUM(s.discount), 0) as discounts, " +
            "COUNT(DISTINCT s.id) as transactions " +
            "FROM sales s " +
            "JOIN sale_items si ON s.id = si.sale_id " +
            "WHERE DATE(s.sale_date) IN (?, ?) " +
            "GROUP BY DATE(s.sale_date)";
        
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, date1);
            stmt.setString(2, date2);
            ResultSet rs = stmt.executeQuery();
            
            Map<String, DailyComparison> data = new HashMap<>();
            while (rs.next()) {
                DailyComparison dc = new DailyComparison();
                dc.date = rs.getString("sale_date");
                dc.sales = rs.getBigDecimal("total_sales");
                dc.discounts = rs.getBigDecimal("discounts");
                dc.transactions = rs.getInt("transactions");
                data.put(dc.date, dc);
            }
            
            DailyComparison day1 = data.get(date1);
            DailyComparison day2 = data.get(date2);
            
            if (day1 != null && day2 != null) {
                report.append(String.format("%-20s %20s %20s %20s\n", "Metric", date1, date2, "Difference"));
                report.append("-".repeat(80)).append("\n");
                
                BigDecimal diffSales = day1.sales.subtract(day2.sales);
                int diffTrans = day1.transactions - day2.transactions;
                
                report.append(String.format("%-20s %20s %20s %20s\n", 
                    "Total Sales", 
                    "TSh " + formatNumber(day1.sales),
                    "TSh " + formatNumber(day2.sales),
                    "TSh " + formatNumber(diffSales)));
                report.append(String.format("%-20s %20d %20d %20d\n", 
                    "Transactions", day1.transactions, day2.transactions, diffTrans));
                report.append(String.format("%-20s %20s %20s\n", 
                    "Avg Transaction", 
                    formatNumber(day1.sales.divide(BigDecimal.valueOf(day1.transactions), 2, RoundingMode.HALF_UP)),
                    formatNumber(day2.sales.divide(BigDecimal.valueOf(day2.transactions), 2, RoundingMode.HALF_UP))));
            }
        }
        
    } catch (SQLException e) {
        report.append("Error: ").append(e.getMessage());
    }
    
    reportArea.setText(report.toString());
    reportArea.setCaretPosition(0);
}

