private void generateMonthlyReport(String month, JTextArea reportArea) {
    StringBuilder report = new StringBuilder();
    report.append("=".repeat(60)).append("\n");
    report.append(String.format("MONTHLY SALES REPORT - %s\n", month));
    report.append("=".repeat(60)).append("\n\n");
    
    try (Connection conn = Database.getConnection()) {
        String sql = 
            "SELECT strftime('%Y-%m', s.sale_date) as month, " +
            "SUM(si.total_price) as total_sales, " +
            "SUM(s.discount) as discounts, " +
            "COUNT(DISTINCT s.id) as transactions, " +
            "SUM(si.quantity) as items_sold " +
            "FROM sales s " +
            "JOIN sale_items si ON s.id = si.sale_id " +
            "WHERE strftime('%Y-%m', s.sale_date) = ? " +
            "GROUP BY month";
        
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, month);
            ResultSet rs = stmt.executeQuery();
            
            if (rs.next()) {
                BigDecimal sales = rs.getBigDecimal("total_sales");
                BigDecimal discounts = rs.getBigDecimal("discounts");
                int transactions = rs.getInt("transactions");
                int items = rs.getInt("items_sold");
                BigDecimal netSales = sales.subtract(discounts);
                
                report.append("MONTHLY SUMMARY\n");
                report.append("-".repeat(40)).append("\n");
                report.append(String.format("Total Sales: TSh %s\n", formatNumber(sales)));
                report.append(String.format("Discounts: TSh %s\n", formatNumber(discounts)));
                report.append(String.format("Net Sales: TSh %s\n", formatNumber(netSales)));
                report.append(String.format("Transactions: %d\n", transactions));
                report.append(String.format("Items Sold: %d\n", items));
                report.append(String.format("Average Daily Sales: TSh %s\n", 
                    formatNumber(netSales.divide(BigDecimal.valueOf(30), 2, RoundingMode.HALF_UP))));
                report.append(String.format("Best Day: To be calculated\n"));
                report.append(String.format("Worst Day: To be calculated\n"));
            } else {
                report.append("No data found for " + month);
            }
        }
        
        // Category breakdown for the month
        String catSql = 
            "SELECT c.name, SUM(si.quantity) as qty_sold, SUM(si.total_price) as revenue " +
            "FROM categories c " +
            "JOIN products p ON c.id = p.category_id " +
            "JOIN sale_items si ON p.id = si.product_id " +
            "JOIN sales s ON si.sale_id = s.id " +
            "WHERE strftime('%Y-%m', s.sale_date) = ? " +
            "GROUP BY c.id " +
            "ORDER BY revenue DESC";
        
        report.append("\nSALES BY CATEGORY\n");
        report.append("-".repeat(40)).append("\n");
        
        try (PreparedStatement stmt = conn.prepareStatement(catSql)) {
            stmt.setString(1, month);
            ResultSet rs = stmt.executeQuery();
            while (rs.next()) {
                report.append(String.format("%s: %d units | TSh %s\n", 
                    rs.getString("name"), rs.getInt("qty_sold"), 
                    formatNumber(rs.getBigDecimal("revenue"))));
            }
        }
        
    } catch (SQLException e) {
        report.append("Error: ").append(e.getMessage());
    }
    
    reportArea.setText(report.toString());
    reportArea.setCaretPosition(0);
}

