private void generateYearlyReport(String year, JTextArea reportArea) {
    StringBuilder report = new StringBuilder();
    report.append("=".repeat(60)).append("\n");
    report.append(String.format("YEARLY SALES REPORT - %s\n", year));
    report.append("=".repeat(60)).append("\n\n");
    
    try (Connection conn = Database.getConnection()) {
        String sql = 
            "SELECT strftime('%Y', s.sale_date) as year, " +
            "SUM(si.total_price) as total_sales, " +
            "SUM(s.discount) as discounts, " +
            "COUNT(DISTINCT s.id) as transactions, " +
            "SUM(si.quantity) as items_sold " +
            "FROM sales s " +
            "JOIN sale_items si ON s.id = si.sale_id " +
            "WHERE strftime('%Y', s.sale_date) = ? " +
            "GROUP BY year";
        
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, year);
            ResultSet rs = stmt.executeQuery();
            
            if (rs.next()) {
                BigDecimal sales = rs.getBigDecimal("total_sales");
                BigDecimal discounts = rs.getBigDecimal("discounts");
                int transactions = rs.getInt("transactions");
                int items = rs.getInt("items_sold");
                                BigDecimal netSales = sales.subtract(discounts);
                
                report.append("YEARLY SUMMARY\n");
                report.append("-".repeat(40)).append("\n");
                report.append(String.format("Total Sales: TSh %s\n", formatNumber(sales)));
                report.append(String.format("Discounts: TSh %s\n", formatNumber(discounts)));
                report.append(String.format("Net Sales: TSh %s\n", formatNumber(netSales)));
                report.append(String.format("Transactions: %d\n", transactions));
                report.append(String.format("Items Sold: %d\n", items));
                report.append(String.format("Average Monthly Sales: TSh %s\n", 
                    formatNumber(netSales.divide(BigDecimal.valueOf(12), 2, RoundingMode.HALF_UP))));
                report.append(String.format("Best Month: To be calculated\n"));
            } else {
                report.append("No data found for year " + year);
            }
        }
        
        // Monthly breakdown for the year
        String monthlySql = 
            "SELECT strftime('%m', s.sale_date) as month, " +
            "SUM(si.total_price) as monthly_sales, " +
            "COUNT(DISTINCT s.id) as transactions " +
            "FROM sales s " +
            "JOIN sale_items si ON s.id = si.sale_id " +
            "WHERE strftime('%Y', s.sale_date) = ? " +
            "GROUP BY strftime('%m', s.sale_date) " +
            "ORDER BY month";
        
        report.append("\nMONTHLY BREAKDOWN\n");
        report.append("-".repeat(40)).append("\n");
        
        String[] monthNames = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};
        
        try (PreparedStatement stmt = conn.prepareStatement(monthlySql)) {
            stmt.setString(1, year);
            ResultSet rs = stmt.executeQuery();
            
            Map<String, Object[]> monthData = new HashMap<>();
            while (rs.next()) {
                String month = rs.getString("month");
                monthData.put(month, new Object[]{
                    rs.getBigDecimal("monthly_sales"),
                    rs.getInt("transactions")
                });
            }
            
            for (int i = 1; i <= 12; i++) {
                String monthKey = String.format("%02d", i);
                Object[] data = monthData.get(monthKey);
                if (data != null) {
                    report.append(String.format("%s: TSh %s (%d transactions)\n", 
                        monthNames[i-1], formatNumber((BigDecimal) data[0]), (int) data[1]));
                } else {
                    report.append(String.format("%s: No data\n", monthNames[i-1]));
                }
            }
        }
        
    } catch (SQLException e) {
        report.append("Error: ").append(e.getMessage());
    }
    
    reportArea.setText(report.toString());
    reportArea.setCaretPosition(0);
}
private int getActiveUserCount() {
    try (Connection conn = Database.getConnection()) {
        // Check if login_history table exists
        DatabaseMetaData meta = conn.getMetaData();
        ResultSet tables = meta.getTables(null, null, "login_history", null);
        if (tables.next()) {
            String clientId = Database.getCurrentClientId();
            if (clientId == null) clientId = this.currentClientId;
            try (PreparedStatement stmt = conn.prepareStatement(
                    "SELECT COUNT(DISTINCT username) FROM login_history WHERE timestamp > datetime('now', '-7 days') AND success = 1 AND client_id = ?")) {
                stmt.setString(1, clientId);
                ResultSet rs = stmt.executeQuery();
                if (rs.next()) {
                    return rs.getInt(1);
                }
            }
        }
    } catch (SQLException e) {
        LOGGER.log(Level.WARNING, "Error getting active user count", e);
    }
    return getTotalUserCountFromDB();
}

private int getRoleCountFromDB(String role) {
    try (Connection conn = Database.getLocalConnection()) {
        String clientId = Database.getCurrentClientId();
        if (clientId == null) clientId = this.currentClientId;
        try (PreparedStatement stmt = conn.prepareStatement(
                "SELECT COUNT(*) FROM users " +
                "WHERE (privileges = ? OR privileges LIKE ?) " +
                "AND client_id = ? " +
                "AND (user_email = ? OR email = ?)")) {
            stmt.setString(1, role);
            stmt.setString(2, role + ":%");
            stmt.setString(3, clientId);
            stmt.setString(4, Database.getCurrentUserEmail());
            stmt.setString(5, Database.getCurrentUserEmail());
            ResultSet rs = stmt.executeQuery();
            return rs.next() ? rs.getInt(1) : 0;
        }
    } catch (SQLException e) {
        LOGGER.log(Level.WARNING, "Error getting role count for " + role, e);
        return 0;
    }
}

private int getTotalUserCountFromDB() {
    try (Connection conn = Database.getLocalConnection()) {
        String clientId = Database.getCurrentClientId();
        if (clientId == null) clientId = this.currentClientId;
        try (PreparedStatement stmt = conn.prepareStatement(
                "SELECT COUNT(*) FROM users WHERE client_id = ? AND (user_email = ? OR email = ?)")) {
            stmt.setString(1, clientId);
            stmt.setString(2, Database.getCurrentUserEmail());
            stmt.setString(3, Database.getCurrentUserEmail());
            ResultSet rs = stmt.executeQuery();
            return rs.next() ? rs.getInt(1) : 0;
        }
    } catch (SQLException e) {
        LOGGER.log(Level.WARNING, "Error getting total user count", e);
        return 0;
    }
}

private String getUsersByRole(String role) {
    StringBuilder users = new StringBuilder();
    try (Connection conn = Database.getLocalConnection()) {
        String clientId = Database.getCurrentClientId();
        if (clientId == null) clientId = this.currentClientId;
        try (PreparedStatement stmt = conn.prepareStatement(
                "SELECT username FROM users " +
                "WHERE (privileges = ? OR privileges LIKE ?) " +
                "AND client_id = ? " +
                "AND (user_email = ? OR email = ?) LIMIT 5")) {
            stmt.setString(1, role);
            stmt.setString(2, role + ":%");
            stmt.setString(3, clientId);
            stmt.setString(4, Database.getCurrentUserEmail());
            stmt.setString(5, Database.getCurrentUserEmail());
            ResultSet rs = stmt.executeQuery();
            boolean first = true;
            while (rs.next()) {
                if (!first) users.append(", ");
                users.append(rs.getString("username"));
                first = false;
            }
            if (users.length() == 0) return "-";
            if (users.toString().split(",").length >= 5) users.append("...");
            return users.toString();
        }
    } catch (SQLException e) {
        LOGGER.log(Level.WARNING, "Error getting users for role " + role, e);
        return "-";
    }
}

