private void exportReportToCSV(String reportType, String fromDate, String toDate) {
    JFileChooser fileChooser = new JFileChooser();
    fileChooser.setDialogTitle("Export " + reportType);
    String filename = reportType.replace(" ", "_") + "_" + LocalDate.now() + ".csv";
    fileChooser.setSelectedFile(new File(filename));
    
    if (fileChooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
        try (PrintWriter pw = new PrintWriter(fileChooser.getSelectedFile())) {
            generateReportData(reportType, fromDate, toDate, pw);
            showGlassMessage(null, "Report exported successfully!", "Success", "success");
        } catch (IOException | SQLException ex) {
            showGlassMessage(null, "Error exporting report: " + ex.getMessage(), "Error", "error");
        }
    }
}

private void exportReportToPDF(String reportType, String fromDate, String toDate) {
    // For now, save as text file (PDF generation would require iText or similar library)
    JFileChooser fileChooser = new JFileChooser();
    fileChooser.setDialogTitle("Export " + reportType + " as PDF");
    String filename = reportType.replace(" ", "_") + "_" + LocalDate.now() + ".txt";
    fileChooser.setSelectedFile(new File(filename));
    
    if (fileChooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
        try (PrintWriter pw = new PrintWriter(fileChooser.getSelectedFile())) {
            generateReportData(reportType, fromDate, toDate, pw);
            showGlassMessage(null, "Report saved successfully!", "Success", "success");
        } catch (IOException | SQLException ex) {
            showGlassMessage(null, "Error saving report: " + ex.getMessage(), "Error", "error");
        }
    }
}

private void printReport(String reportType, String fromDate, String toDate) {
    StringBuilder report = new StringBuilder();
    try {
        generateReportData(reportType, fromDate, toDate, new PrintWriter(System.out) {
            public void println(String x) { report.append(x).append("\n"); }
        });
        
        String finalReport = report.toString();
        java.awt.print.PrinterJob job = java.awt.print.PrinterJob.getPrinterJob();
        job.setPrintable(new java.awt.print.Printable() {
            @Override
            public int print(java.awt.Graphics graphics, java.awt.print.PageFormat pf, int page) throws java.awt.print.PrinterException {
                if (page > 0) return java.awt.print.Printable.NO_SUCH_PAGE;
                
                Graphics2D g2d = (Graphics2D) graphics;
                g2d.translate(pf.getImageableX(), pf.getImageableY());
                
                String[] lines = finalReport.split("\n");
                int y = 15;
                Font font = new Font("Monospaced", Font.PLAIN, 8);
                g2d.setFont(font);
                FontMetrics fm = g2d.getFontMetrics();
                
                for (String line : lines) {
                    g2d.drawString(line, 10, y);
                    y += fm.getHeight();
                }
                
                return java.awt.print.Printable.PAGE_EXISTS;
            }
        });
        
        if (job.printDialog()) {
            job.print();
            showGlassMessage(null, "Report sent to printer!", "Success", "success");
        }
    } catch (Exception ex) {
        showGlassMessage(null, "Error printing: " + ex.getMessage(), "Error", "error");
    }
}
private void loadUserRestrictions() {
    userRestrictions.clear();
    String currentClientId = Database.getCurrentClientId();
    String currentEmail = Database.getCurrentUserEmail();
    try (Connection conn = Database.getLocalConnection();
         PreparedStatement stmt = conn.prepareStatement(
             "SELECT username, privileges FROM users " +
             "WHERE client_id = ? AND (user_email = ? OR email = ?)")) {
        stmt.setString(1, currentClientId);
        stmt.setString(2, currentEmail);
        stmt.setString(3, currentEmail);
        ResultSet rs = stmt.executeQuery();
        while (rs.next()) {
            String username = rs.getString("username");
            String privileges = rs.getString("privileges");
            if (privileges != null && privileges.contains(":")) {
                String[] parts = privileges.split(":", 2);
                if (parts.length == 2) {
                    Set<String> restrictions = new HashSet<>();
                    for (String r : parts[1].split(",")) {
                        restrictions.add(r.trim());
                    }
                    userRestrictions.put(username, restrictions);
                }
            }
        }
    } catch (SQLException e) {
        LOGGER.log(Level.WARNING, "Failed to load user restrictions", e);
    }
}
private void generateReportData(String reportType, String fromDate, String toDate, PrintWriter pw) throws SQLException {
    pw.println(reportType);
    pw.println("Generated: " + LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
    pw.println("Period: " + fromDate + " to " + toDate);
    pw.println("=".repeat(80));
    pw.println();
    
    switch (reportType) {
        case "Sales Summary Report":
            generateSalesReportCSV(fromDate, toDate, pw);
            break;
        case "Staff Performance Report":
            generateStaffReportCSV(fromDate, toDate, pw);
            break;
        case "Category Sales Report":
            generateCategoryReportCSV(fromDate, toDate, pw);
            break;
        case "Profit & Loss Report":
            generateProfitLossReportCSV(fromDate, toDate, pw);
            break;
        case "Top Products Report":
            generateTopProductsCSV(fromDate, toDate, pw);
            break;
        case "Inventory Report":
            generateInventoryReportCSV(pw);
            break;
        case "Complete Business Report":
            generateCompleteBusinessReport(fromDate, toDate, pw);
            break;
    }
}

private void generateSalesReportCSV(String fromDate, String toDate, PrintWriter pw) throws SQLException {
    pw.println("Date,Sales,Discount,Net Sales,Transactions,Items Sold");
    String sql = 
        "SELECT DATE(s.sale_date) as date, " +
        "COALESCE(SUM(si.total_price), 0) as sales, " +
        "COALESCE(SUM(s.discount), 0) as discount, " +
        "COUNT(DISTINCT s.id) as transactions, " +
        "COALESCE(SUM(si.quantity), 0) as items " +
        "FROM sales s " +
        "JOIN sale_items si ON s.id = si.sale_id " +
        "WHERE DATE(s.sale_date) BETWEEN ? AND ? " +
        "GROUP BY DATE(s.sale_date) " +
        "ORDER BY date";
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        while (rs.next()) {
            BigDecimal netSales = rs.getBigDecimal("sales").subtract(rs.getBigDecimal("discount"));
            pw.printf("%s,%s,%s,%s,%d,%d\n",
                rs.getString("date"),
                formatNumber(rs.getBigDecimal("sales")),
                formatNumber(rs.getBigDecimal("discount")),
                formatNumber(netSales),
                rs.getInt("transactions"),
                rs.getInt("items"));
        }
    }
}

private void generateStaffReportCSV(String fromDate, String toDate, PrintWriter pw) throws SQLException {
    pw.println("Staff,Sales Count,Items Sold,Total Revenue,Avg Transaction");
    String sql = 
        "SELECT s.user, COUNT(DISTINCT s.id) as sales_count, " +
        "SUM(si.quantity) as items_sold, " +
        "COALESCE(SUM(si.total_price), 0) as revenue, " +
        "AVG(si.total_price) as avg_transaction " +
        "FROM sales s " +
        "JOIN sale_items si ON s.id = si.sale_id " +
        "WHERE DATE(s.sale_date) BETWEEN ? AND ? " +
        "GROUP BY s.user " +
        "ORDER BY revenue DESC";
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        while (rs.next()) {
            pw.printf("%s,%d,%d,%s,%s\n",
                rs.getString("user"),
                rs.getInt("sales_count"),
                rs.getInt("items_sold"),
                formatNumber(rs.getBigDecimal("revenue")),
                formatNumber(rs.getBigDecimal("avg_transaction")));
        }
    }
}

private void generateCategoryReportCSV(String fromDate, String toDate, PrintWriter pw) throws SQLException {
    pw.println("Category,Items Sold,Total Revenue,Percentage");
    
    String sql = 
        "SELECT c.name as category, COALESCE(SUM(si.quantity), 0) as items_sold, " +
        "COALESCE(SUM(si.total_price), 0) as revenue " +
        "FROM categories c " +
        "LEFT JOIN products p ON c.id = p.category_id " +
        "LEFT JOIN sale_items si ON p.id = si.product_id " +
        "LEFT JOIN sales s ON si.sale_id = s.id AND DATE(s.sale_date) BETWEEN ? AND ? " +
        "GROUP BY c.id " +
        "ORDER BY revenue DESC";
    
    BigDecimal totalRevenue = BigDecimal.ZERO;
    List<Object[]> data = new ArrayList<>();
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        while (rs.next()) {
            BigDecimal revenue = rs.getBigDecimal("revenue");
            totalRevenue = totalRevenue.add(revenue);
            data.add(new Object[]{
                rs.getString("category"),
                rs.getInt("items_sold"),
                revenue
            });
        }
    }
    
    for (Object[] row : data) {
        BigDecimal revenue = (BigDecimal) row[2];
        double percentage = totalRevenue.compareTo(BigDecimal.ZERO) > 0 ?
            revenue.doubleValue() / totalRevenue.doubleValue() * 100 : 0;
        pw.printf("%s,%d,%s,%.1f%%\n",
            row[0], row[1], formatNumber(revenue), percentage);
    }
}

private void generateProfitLossReportCSV(String fromDate, String toDate, PrintWriter pw) throws SQLException {
    // Total Sales
    String salesSql = "SELECT COALESCE(SUM(si.total_price), 0) as total_sales, " +
                     "COALESCE(SUM(s.discount), 0) as discounts " +
                     "FROM sales s JOIN sale_items si ON s.id = si.sale_id " +
                     "WHERE DATE(s.sale_date) BETWEEN ? AND ?";
    
    BigDecimal totalSales = BigDecimal.ZERO;
    BigDecimal totalDiscount = BigDecimal.ZERO;
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(salesSql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) {
            totalSales = rs.getBigDecimal("total_sales");
            totalDiscount = rs.getBigDecimal("discounts");
        }
    }
    
    // COGS
    String cogsSql = "SELECT COALESCE(SUM(si.quantity * p.cost_price), 0) as cogs " +
                    "FROM sale_items si " +
                    "JOIN sales s ON si.sale_id = s.id " +
                    "JOIN products p ON si.product_id = p.id " +
                    "WHERE DATE(s.sale_date) BETWEEN ? AND ?";
    
    BigDecimal cogs = BigDecimal.ZERO;
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(cogsSql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) cogs = rs.getBigDecimal("cogs");
    }
    
    // Expenses
    String expenseSql = "SELECT COALESCE(SUM(amount), 0) as expenses " +
                       "FROM daily_expenses " +
                       "WHERE DATE(expense_date) BETWEEN ? AND ?";
    
    BigDecimal expenses = BigDecimal.ZERO;
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(expenseSql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) expenses = rs.getBigDecimal("expenses");
    }
    
    BigDecimal netSales = totalSales.subtract(totalDiscount);
    BigDecimal grossProfit = netSales.subtract(cogs);
    BigDecimal netProfit = grossProfit.subtract(expenses);
    
        pw.println("Metric,Amount (TSh)");
    pw.println("Total Sales," + formatNumber(totalSales));
    pw.println("Less: Discounts," + formatNumber(totalDiscount));
    pw.println("Net Sales," + formatNumber(netSales));
    pw.println("Less: COGS," + formatNumber(cogs));
    pw.println("Gross Profit," + formatNumber(grossProfit));
    pw.println("Less: Expenses," + formatNumber(expenses));
    pw.println("Net Profit," + formatNumber(netProfit));
}

private void generateTopProductsCSV(String fromDate, String toDate, PrintWriter pw) throws SQLException {
    pw.println("Rank,Product Name,Category,Quantity Sold,Revenue,Profit,Margin %");
    
    String sql = 
        "SELECT p.name, c.name as category, SUM(si.quantity) as total_sold, " +
        "SUM(si.total_price) as revenue, " +
        "SUM(si.quantity * p.cost_price) as cost, " +
        "SUM(si.total_price) - SUM(si.quantity * p.cost_price) as profit " +
        "FROM sale_items si " +
        "JOIN sales s ON si.sale_id = s.id " +
        "JOIN products p ON si.product_id = p.id " +
        "LEFT JOIN categories c ON p.category_id = c.id " +
        "WHERE DATE(s.sale_date) BETWEEN ? AND ? " +
        "GROUP BY p.id " +
        "ORDER BY total_sold DESC LIMIT 50";
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        
        int rank = 1;
        while (rs.next()) {
            BigDecimal revenue = rs.getBigDecimal("revenue");
            BigDecimal profit = rs.getBigDecimal("profit");
            BigDecimal margin = revenue.compareTo(BigDecimal.ZERO) > 0 ?
                profit.multiply(BigDecimal.valueOf(100)).divide(revenue, 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
            
            pw.printf("%d,%s,%s,%d,%s,%s,%s%%\n",
                rank++,
                rs.getString("name"),
                rs.getString("category") != null ? rs.getString("category") : "Uncategorized",
                rs.getInt("total_sold"),
                formatNumber(revenue),
                formatNumber(profit),
                margin);
        }
    }
}

private void generateInventoryReportCSV(PrintWriter pw) throws SQLException {
    pw.println("Product,Category,Current Stock,Min Stock Level,Cost Price,Selling Price,Stock Value,Status");
    
    String sql = 
        "SELECT p.name, c.name as category, p.stock_quantity, p.min_stock_level, " +
        "p.cost_price, p.selling_price, " +
        "(p.stock_quantity * p.cost_price) as stock_value " +
        "FROM products p " +
        "LEFT JOIN categories c ON p.category_id = c.id " +
        "ORDER BY p.name";
    
    try (Statement stmt = Database.getConnection().createStatement();
         ResultSet rs = stmt.executeQuery(sql)) {
        
        while (rs.next()) {
            int stock = rs.getInt("stock_quantity");
            int minStock = rs.getInt("min_stock_level");
            String status = stock <= minStock ? "LOW STOCK" : "OK";
            
            pw.printf("%s,%s,%d,%d,%s,%s,%s,%s\n",
                rs.getString("name"),
                rs.getString("category") != null ? rs.getString("category") : "Uncategorized",
                stock,
                minStock,
                formatNumber(rs.getBigDecimal("cost_price")),
                formatNumber(rs.getBigDecimal("selling_price")),
                formatNumber(rs.getBigDecimal("stock_value")),
                status);
        }
    }
}

private void generateCompleteBusinessReport(String fromDate, String toDate, PrintWriter pw) throws SQLException {
    pw.println("COMPLETE BUSINESS REPORT");
    pw.println("=".repeat(60));
    pw.println();
    
    // Executive Summary
    pw.println("EXECUTIVE SUMMARY");
    pw.println("-".repeat(40));
    
    String summarySql = 
        "SELECT " +
        "COALESCE((SELECT SUM(si.total_price) FROM sales s JOIN sale_items si ON s.id = si.sale_id WHERE DATE(s.sale_date) BETWEEN ? AND ?), 0) as total_sales, " +
        "COALESCE((SELECT SUM(s.discount) FROM sales s WHERE DATE(s.sale_date) BETWEEN ? AND ?), 0) as total_discounts, " +
        "COALESCE((SELECT COUNT(DISTINCT s.id) FROM sales s WHERE DATE(s.sale_date) BETWEEN ? AND ?), 0) as transactions, " +
        "COALESCE((SELECT SUM(si.quantity) FROM sales s JOIN sale_items si ON s.id = si.sale_id WHERE DATE(s.sale_date) BETWEEN ? AND ?), 0) as items_sold, " +
        "COALESCE((SELECT COUNT(DISTINCT s.user) FROM sales s WHERE DATE(s.sale_date) BETWEEN ? AND ?), 0) as active_staff";
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(summarySql)) {
        for (int i = 1; i <= 12; i++) stmt.setString(i, fromDate);
        for (int i = 1; i <= 12; i++) stmt.setString(i, toDate);
        ResultSet rs = stmt.executeQuery();
        if (rs.next()) {
            BigDecimal sales = rs.getBigDecimal("total_sales");
            BigDecimal discounts = rs.getBigDecimal("total_discounts");
            BigDecimal netSales = sales.subtract(discounts);
            
            pw.printf("Total Sales (Gross): TSh %s\n", formatNumber(sales));
            pw.printf("Total Discounts: TSh %s\n", formatNumber(discounts));
            pw.printf("Net Sales: TSh %s\n", formatNumber(netSales));
            pw.printf("Number of Transactions: %d\n", rs.getInt("transactions"));
            pw.printf("Items Sold: %d\n", rs.getInt("items_sold"));
            pw.printf("Active Staff Members: %d\n", rs.getInt("active_staff"));
            pw.printf("Average Transaction Value: TSh %s\n", 
                rs.getInt("transactions") > 0 ? 
                formatNumber(netSales.divide(BigDecimal.valueOf(rs.getInt("transactions")), 2, RoundingMode.HALF_UP)) : "0");
        }
    }
    
    pw.println();
    
    // Staff Performance Summary
    pw.println("STAFF PERFORMANCE SUMMARY");
    pw.println("-".repeat(40));
    
    String staffSql = 
        "SELECT s.user, COUNT(DISTINCT s.id) as sales_count, " +
        "SUM(si.total_price) as revenue " +
        "FROM sales s " +
        "JOIN sale_items si ON s.id = si.sale_id " +
        "WHERE DATE(s.sale_date) BETWEEN ? AND ? " +
        "GROUP BY s.user " +
        "ORDER BY revenue DESC";
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(staffSql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        pw.printf("%-20s %12s %15s\n", "Staff", "Sales Count", "Revenue");
        while (rs.next()) {
            pw.printf("%-20s %12d %15s\n",
                rs.getString("user"),
                rs.getInt("sales_count"),
                formatNumber(rs.getBigDecimal("revenue")));
        }
    }
    
    pw.println();
    
    // Top 10 Products
    pw.println("TOP 10 PRODUCTS");
    pw.println("-".repeat(40));
    
    String topSql = 
        "SELECT p.name, SUM(si.quantity) as qty_sold, SUM(si.total_price) as revenue " +
        "FROM sale_items si " +
        "JOIN sales s ON si.sale_id = s.id " +
        "JOIN products p ON si.product_id = p.id " +
        "WHERE DATE(s.sale_date) BETWEEN ? AND ? " +
        "GROUP BY p.id " +
        "ORDER BY qty_sold DESC LIMIT 10";
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(topSql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        pw.printf("%-30s %10s %15s\n", "Product", "Qty Sold", "Revenue");
        while (rs.next()) {
            pw.printf("%-30s %10d %15s\n",
                rs.getString("name"),
                rs.getInt("qty_sold"),
                formatNumber(rs.getBigDecimal("revenue")));
        }
    }
    
    pw.println();
    
    // Category Breakdown
    pw.println("SALES BY CATEGORY");
    pw.println("-".repeat(40));
    
    String catSql = 
        "SELECT c.name, COALESCE(SUM(si.quantity), 0) as qty_sold, " +
        "COALESCE(SUM(si.total_price), 0) as revenue " +
        "FROM categories c " +
        "LEFT JOIN products p ON c.id = p.category_id " +
        "LEFT JOIN sale_items si ON p.id = si.product_id " +
        "LEFT JOIN sales s ON si.sale_id = s.id AND DATE(s.sale_date) BETWEEN ? AND ? " +
        "GROUP BY c.id " +
        "ORDER BY revenue DESC";
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(catSql)) {
        stmt.setString(1, fromDate);
        stmt.setString(2, toDate);
        ResultSet rs = stmt.executeQuery();
        pw.printf("%-20s %10s %15s\n", "Category", "Qty Sold", "Revenue");
        while (rs.next()) {
            pw.printf("%-20s %10d %15s\n",
                rs.getString("name"),
                rs.getInt("qty_sold"),
                formatNumber(rs.getBigDecimal("revenue")));
        }
    }
    
    pw.println();
    
    // Inventory Status
    pw.println("INVENTORY STATUS");
    pw.println("-".repeat(40));
    
    String invSql = 
        "SELECT COUNT(*) as total_products, " +
        "SUM(stock_quantity) as total_stock, " +
        "SUM(stock_quantity * cost_price) as total_value, " +
        "COUNT(CASE WHEN stock_quantity <= min_stock_level THEN 1 END) as low_stock_count " +
        "FROM products";
    
    try (Statement stmt = Database.getConnection().createStatement();
         ResultSet rs = stmt.executeQuery(invSql)) {
        if (rs.next()) {
            pw.printf("Total Products: %d\n", rs.getInt("total_products"));
            pw.printf("Total Stock Value: TSh %s\n", formatNumber(rs.getBigDecimal("total_value")));
            pw.printf("Low Stock Items: %d\n", rs.getInt("low_stock_count"));
        }
    }
    
    pw.println();
    pw.println("End of Report");
    pw.println("Generated on: " + LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
}

