private void showCategoryChart(String fromDate, String toDate) {
    // Simple chart dialog - would integrate with JFreeChart if available
    JDialog chartDialog = new JDialog((Frame) SwingUtilities.getWindowAncestor(this), "Category Sales Chart", true);
    chartDialog.setSize(600, 400);
    chartDialog.setLocationRelativeTo(this);
    chartDialog.setUndecorated(true);
    chartDialog.setBackground(new Color(0, 0, 0, 0));
    
    JPanel glass = new JPanel() {
        @Override protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(new Color(10, 12, 18));
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), 20, 20);
            g2.setColor(new Color(155, 89, 182, 160));
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawRoundRect(1, 1, getWidth()-3, getHeight()-3, 20, 20);
            g2.dispose();
        }
    };
    glass.setLayout(new BorderLayout());
    glass.setBorder(new EmptyBorder(20, 20, 20, 20));
    
    JLabel title = new JLabel("Category Sales Distribution");
    title.setFont(new Font("Segoe UI", Font.BOLD, 18));
    title.setForeground(new Color(155, 89, 182));
    title.setHorizontalAlignment(SwingConstants.CENTER);
    
    JTextArea chartArea = new JTextArea();
    chartArea.setEditable(false);
    chartArea.setFont(new Font("Monospaced", Font.PLAIN, 12));
    chartArea.setBackground(new Color(22, 28, 38));
    chartArea.setForeground(Color.WHITE);
    chartArea.setMargin(new Insets(15, 15, 15, 15));
    
    JScrollPane scrollPane = new JScrollPane(chartArea);
    scrollPane.setBorder(BorderFactory.createLineBorder(new Color(60, 80, 100), 1));
    
    // Generate ASCII bar chart
    StringBuilder chart = new StringBuilder();
    chart.append("CATEGORY SALES DISTRIBUTION\n");
    chart.append("=".repeat(50)).append("\n\n");
    
    try (Connection conn = Database.getConnection()) {
        String sql = 
            "SELECT c.name as category, COALESCE(SUM(si.total_price), 0) as revenue " +
            "FROM categories c " +
            "LEFT JOIN products p ON c.id = p.category_id " +
            "LEFT JOIN sale_items si ON p.id = si.product_id " +
            "LEFT JOIN sales s ON si.sale_id = s.id AND DATE(s.sale_date) BETWEEN ? AND ? " +
            "GROUP BY c.id " +
            "ORDER BY revenue DESC";
        
        try (PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, fromDate);
            stmt.setString(2, toDate);
            ResultSet rs = stmt.executeQuery();
            
            BigDecimal maxRevenue = BigDecimal.ZERO;
            List<Object[]> data = new ArrayList<>();
            
            while (rs.next()) {
                BigDecimal revenue = rs.getBigDecimal("revenue");
                if (revenue.compareTo(maxRevenue) > 0) maxRevenue = revenue;
                data.add(new Object[]{rs.getString("category"), revenue});
            }
            
            int barMaxWidth = 40;
            for (Object[] row : data) {
                String category = (String) row[0];
                BigDecimal revenue = (BigDecimal) row[1];
                int barLength = maxRevenue.compareTo(BigDecimal.ZERO) > 0 ?
                    (int) (revenue.doubleValue() / maxRevenue.doubleValue() * barMaxWidth) : 0;
                
                chart.append(String.format("%-20s | %s (%s)\n", 
                    category.length() > 20 ? category.substring(0, 17) + "..." : category,
                    "█".repeat(Math.max(1, barLength)),
                    formatNumber(revenue)));
            }
        }
    } catch (SQLException e) {
        chart.append("Error loading chart data: ").append(e.getMessage());
    }
    
    chartArea.setText(chart.toString());
    
    JButton closeBtn = createSmallButton("Close", new Color(149, 165, 166));
    closeBtn.addActionListener(e -> chartDialog.dispose());
    
    JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
    btnPanel.setOpaque(false);
    btnPanel.add(closeBtn);
    
    glass.add(title, BorderLayout.NORTH);
    glass.add(scrollPane, BorderLayout.CENTER);
    glass.add(btnPanel, BorderLayout.SOUTH);
    
    chartDialog.setContentPane(glass);
    chartDialog.setVisible(true);
}

// ==================== HELPER METHODS FOR STYLING ====================


private JButton createSmallButton(String text, Color color) {
    JButton btn = new JButton(text);
    btn.setFont(new Font("Segoe UI", Font.BOLD, 11));
    btn.setBackground(color);
    btn.setForeground(Color.WHITE);
    btn.setFocusPainted(false);
    btn.setBorder(BorderFactory.createEmptyBorder(6, 12, 6, 12));
    btn.setCursor(new Cursor(Cursor.HAND_CURSOR));
    btn.addMouseListener(new MouseAdapter() {
        @Override
        public void mouseEntered(MouseEvent e) {
            btn.setBackground(color.brighter());
        }
        @Override
        public void mouseExited(MouseEvent e) {
            btn.setBackground(color);
        }
    });
    return btn;
}


private void exportTableToExcel(DefaultTableModel model, String filename) {
    JFileChooser fileChooser = new JFileChooser();
    fileChooser.setDialogTitle("Export Data");
    fileChooser.setSelectedFile(new File(filename + "_" + LocalDate.now() + ".csv"));
    
    if (fileChooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
        try (PrintWriter pw = new PrintWriter(fileChooser.getSelectedFile())) {
            for (int i = 0; i < model.getColumnCount(); i++) {
                pw.print("\"" + model.getColumnName(i) + "\"");
                if (i < model.getColumnCount() - 1) pw.print(",");
            }
            pw.println();
            
            for (int row = 0; row < model.getRowCount(); row++) {
                for (int col = 0; col < model.getColumnCount(); col++) {
                    Object value = model.getValueAt(row, col);
                    pw.print("\"" + (value != null ? value.toString() : "") + "\"");
                    if (col < model.getColumnCount() - 1) pw.print(",");
                }
                pw.println();
            }
            
            showGlassMessage(null, "Data exported successfully!", "Success", "success");
        } catch (IOException e) {
            showGlassMessage(null, "Error exporting: " + e.getMessage(), "Error", "error");
        }
    }
}



