private JPanel createStockMovementPanel() {
    JPanel panel = new JPanel(new BorderLayout(10, 10));
    panel.setOpaque(false);
    panel.setBorder(new EmptyBorder(10, 10, 10, 10));
    
    // Product Selection Panel
    JPanel selectionPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 15, 10));
    selectionPanel.setOpaque(false);
    
    JLabel selectLabel = new JLabel("Select Product:");
    selectLabel.setForeground(Color.WHITE);
    selectLabel.setFont(new Font("Segoe UI", Font.BOLD, 13));
    
    JComboBox<String> productCombo = new JComboBox<>();
    productCombo.setBackground(new Color(45, 50, 60));
    productCombo.setForeground(Color.WHITE);
    productCombo.setPreferredSize(new Dimension(300, 35));
    
    JButton loadBtn = new JButton("🔍 Load Product History");
    loadBtn.setBackground(new Color(52, 152, 219));
    loadBtn.setForeground(Color.WHITE);
    loadBtn.setFocusPainted(false);
    
    selectionPanel.add(selectLabel);
    selectionPanel.add(productCombo);
    selectionPanel.add(loadBtn);
    
    panel.add(selectionPanel, BorderLayout.NORTH);
    
    // Tabbed pane for different product history views
    JTabbedPane tabbedPane = new JTabbedPane();
    tabbedPane.setBackground(new Color(18, 22, 32));
    tabbedPane.setForeground(Color.WHITE);
    
    // Tab 1: Complete Lifecycle
    JPanel lifecyclePanel = createLifecyclePanel();
    tabbedPane.addTab("📋 Complete Lifecycle", lifecyclePanel);
    
    // Tab 2: Sales History
    JPanel salesPanel = createSalesHistoryPanel();
    tabbedPane.addTab("💰 Sales History", salesPanel);
    
    // Tab 3: Receive History
    JPanel receivePanel = createReceiveHistoryPanel();
    tabbedPane.addTab("📦 Receive History", receivePanel);
    
    // Tab 4: Inventory Flow
    JPanel flowPanel = createFlowPanel();
    tabbedPane.addTab("🔄 Inventory Flow", flowPanel);
    
    panel.add(tabbedPane, BorderLayout.CENTER);
    
    // Load products into combo
    loadProductsIntoCombo(productCombo);
    
    // Load data when product is selected
    loadBtn.addActionListener(e -> {
        String productName = (String) productCombo.getSelectedItem();
        if (productName != null && !productName.isEmpty()) {
            loadFullProductTraceability(productName, lifecyclePanel, salesPanel, receivePanel, flowPanel);
        }
    });
    
    return panel;
}

private void loadFullProductTraceability(String productName, JPanel lifecyclePanel,
        JPanel salesPanel, JPanel receivePanel, JPanel flowPanel) {

    try {
        Database.Product product = null;
        List<Database.Product> products = Database.getAllProducts();
        for (Database.Product p : products) {
            if (p.getName().equals(productName)) { product = p; break; }
        }
        if (product == null) return;

        final int productId = product.getId();
        final String clientId = Database.getCurrentClientId();

        // LIFECYCLE
        DefaultTableModel lifecycleModel = (DefaultTableModel) lifecyclePanel.getClientProperty("lifecycleModel");
        lifecycleModel.setRowCount(0);
        try (PreparedStatement ps = Database.getConnection().prepareStatement(
                "SELECT flow_date, action, quantity, user, vendor FROM item_flows WHERE product_id = ? AND client_id = ? ORDER BY flow_date ASC")) {
            ps.setInt(1, productId);
            ps.setString(2, clientId);
            ResultSet rs = ps.executeQuery();
            while (rs.next()) {
                lifecycleModel.addRow(new Object[]{
                    formatDate(rs.getString("flow_date")),
                    getActionIcon(rs.getString("action")) + " " + rs.getString("action"),
                    rs.getInt("quantity"),
                    rs.getString("user") != null ? rs.getString("user") : "SYSTEM",
                    rs.getString("vendor") != null ? rs.getString("vendor") : "-",
                    "-"
                });
            }
        }

        // SALES
        DefaultTableModel salesModel = (DefaultTableModel) salesPanel.getClientProperty("salesModel");
        JLabel salesTotalLabel = (JLabel) salesPanel.getClientProperty("salesTotalLabel");
        salesModel.setRowCount(0);
        BigDecimal totalSales = BigDecimal.ZERO;
        try (PreparedStatement ps = Database.getConnection().prepareStatement(
                "SELECT s.sale_date, si.quantity, si.unit_price, (si.quantity * si.unit_price) as total, s.user " +
                "FROM sale_items si JOIN sales s ON si.sale_id = s.id " +
                "WHERE si.product_id = ? AND s.client_id = ? ORDER BY s.sale_date DESC")) {
            ps.setInt(1, productId);
            ps.setString(2, clientId);
            ResultSet rs = ps.executeQuery();
            while (rs.next()) {
                BigDecimal total = rs.getBigDecimal("total");
                if (total == null) total = BigDecimal.ZERO;
                totalSales = totalSales.add(total);
                salesModel.addRow(new Object[]{
                    formatDate(rs.getString("sale_date")),
                    rs.getInt("quantity"),
                    "TSh " + rs.getInt("unit_price"),
                    "TSh " + total.intValue(),
                    rs.getString("user") != null ? rs.getString("user") : "SYSTEM"
                });
            }
        }
        if (salesTotalLabel != null) salesTotalLabel.setText("Total Sales: TSh " + totalSales.intValue());

        // RECEIVE
        DefaultTableModel receiveModel = (DefaultTableModel) receivePanel.getClientProperty("receiveModel");
        JLabel receiveTotalLabel = (JLabel) receivePanel.getClientProperty("receiveTotalLabel");
        receiveModel.setRowCount(0);
        BigDecimal totalReceived = BigDecimal.ZERO;
        try (PreparedStatement ps = Database.getConnection().prepareStatement(
                "SELECT flow_date, quantity, vendor, user FROM item_flows " +
                "WHERE product_id = ? AND client_id = ? AND UPPER(TRIM(action)) IN ('RECEIVED','RECEIVE','NEW ITEM') " +
                "ORDER BY flow_date DESC")) {
            ps.setInt(1, productId);
            ps.setString(2, clientId);
            ResultSet rs = ps.executeQuery();
            BigDecimal costPrice = product.getCostPrice() != null ? product.getCostPrice() : BigDecimal.ZERO;
            while (rs.next()) {
                int qty = rs.getInt("quantity");
                totalReceived = totalReceived.add(costPrice.multiply(BigDecimal.valueOf(qty)));
                receiveModel.addRow(new Object[]{
                    formatDate(rs.getString("flow_date")),
                    qty,
                    "TSh " + costPrice.intValue(),
                    rs.getString("vendor") != null ? rs.getString("vendor") : "-",
                    rs.getString("user") != null ? rs.getString("user") : "SYSTEM"
                });
            }
        }
        if (receiveTotalLabel != null) receiveTotalLabel.setText("Total Received: TSh " + totalReceived.intValue());

        // FLOW
        DefaultTableModel flowModel = (DefaultTableModel) flowPanel.getClientProperty("flowModel");
        flowModel.setRowCount(0);
        try (PreparedStatement ps = Database.getConnection().prepareStatement(
                "SELECT flow_date, action, quantity, user, vendor FROM item_flows " +
                "WHERE product_id = ? AND client_id = ? ORDER BY flow_date DESC")) {
            ps.setInt(1, productId);
            ps.setString(2, clientId);
            ResultSet rs = ps.executeQuery();
            while (rs.next()) {
                int qty = rs.getInt("quantity");
                String action = rs.getString("action");
                boolean isOut = action != null && (action.toUpperCase().contains("SOLD") || action.toUpperCase().contains("SALE"));
                flowModel.addRow(new Object[]{
                    formatDate(rs.getString("flow_date")),
                    action,
                    isOut ? "-" + qty : "+" + qty,
                    rs.getString("user") != null ? rs.getString("user") : "SYSTEM",
                    rs.getString("vendor") != null ? rs.getString("vendor") : "-"
                });
            }
        }

    } catch (Exception e) {
        LOGGER.log(Level.FINE, "Product traceability load skipped", e);
    }
}

// ==================== STOCK LEVEL MANAGEMENT PANEL ====================

private JPanel createStockLevelPanel() {
    JPanel panel = new JPanel(new BorderLayout(10, 10));
    panel.setOpaque(false);
    panel.setBorder(new EmptyBorder(10, 10, 10, 10));
    
    // Search panel
    JPanel searchPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 10, 5));
    searchPanel.setOpaque(false);
    
    JLabel searchLabel = new JLabel("Search Product:");
    searchLabel.setForeground(Color.WHITE);
    JTextField searchField = new JTextField(20);
    styleTextField(searchField);
    
    JButton refreshBtn = createSmallButton("🔄 Refresh", new Color(52, 152, 219));
    JButton updateStockBtn = createSmallButton("✏️ Update Stock", new Color(46, 204, 113));
    JButton setMinStockBtn = createSmallButton("📝 Set Min Stock", new Color(255, 193, 7));
    
    searchPanel.add(searchLabel);
    searchPanel.add(searchField);
    searchPanel.add(refreshBtn);
    searchPanel.add(updateStockBtn);
    searchPanel.add(setMinStockBtn);
    
    // Stock table
    String[] columns = {"ID", "Product Name", "Category", "Current Stock", "Min Stock", "Status", "Vendor", "Last Updated"};
    DefaultTableModel model = new DefaultTableModel(columns, 0) {
        @Override public boolean isCellEditable(int r, int c) { return false; }
    };
    
    JTable stockTable = new JTable(model);
    styleTable(stockTable);
    
    // Status renderer
    stockTable.getColumnModel().getColumn(5).setCellRenderer(new DefaultTableCellRenderer() {
        @Override
        public Component getTableCellRendererComponent(JTable table, Object value,
                boolean isSelected, boolean hasFocus, int row, int column) {
            Component c = super.getTableCellRendererComponent(table, value, isSelected, hasFocus, row, column);
            if (!isSelected && value != null) {
                String status = value.toString();
                if (status.contains("CRITICAL")) {
                    c.setForeground(new Color(231, 76, 60));
                    c.setFont(c.getFont().deriveFont(Font.BOLD));
                } else if (status.contains("LOW")) {
                    c.setForeground(new Color(255, 193, 7));
                } else {
                    c.setForeground(new Color(46, 204, 113));
                }
            }
            return c;
        }
    });
    
    JScrollPane scrollPane = new JScrollPane(stockTable);
    scrollPane.setOpaque(false);
    scrollPane.getViewport().setOpaque(false);
    scrollPane.setBorder(BorderFactory.createLineBorder(new Color(60, 80, 100), 1));
    
    // Load stock data
    refreshBtn.addActionListener(e -> loadStockData(searchField.getText().trim(), model));
    
    updateStockBtn.addActionListener(e -> {
        int row = stockTable.getSelectedRow();
        if (row < 0) {
            showGlassMessage(null, "Please select a product first", "No Selection", "warning");
            return;
        }
        int productId = (int) model.getValueAt(row, 0);
        String productName = (String) model.getValueAt(row, 1);
        int currentStock = (int) model.getValueAt(row, 3);
        showUpdateStockDialog(productId, productName, currentStock, model, row);
    });
    
    setMinStockBtn.addActionListener(e -> {
        int row = stockTable.getSelectedRow();
        if (row < 0) {
            showGlassMessage(null, "Please select a product first", "No Selection", "warning");
            return;
        }
        int productId = (int) model.getValueAt(row, 0);
        String productName = (String) model.getValueAt(row, 1);
        int currentMinStock = (int) model.getValueAt(row, 4);
        showSetMinStockDialog(productId, productName, currentMinStock, model, row);
    });
    
    // Search as you type
    searchField.getDocument().addDocumentListener(new DocumentListener() {
        private Timer timer;
        @Override public void insertUpdate(DocumentEvent e) { search(); }
        @Override public void removeUpdate(DocumentEvent e) { search(); }
        @Override public void changedUpdate(DocumentEvent e) { search(); }
        private void search() {
            if (timer != null && timer.isRunning()) timer.stop();
            timer = new Timer(300, ev -> loadStockData(searchField.getText().trim(), model));
            timer.setRepeats(false);
            timer.start();
        }
    });
    
    panel.add(searchPanel, BorderLayout.NORTH);
    panel.add(scrollPane, BorderLayout.CENTER);
    
    // Initial load
    SwingUtilities.invokeLater(() -> loadStockData("", model));
    
    return panel;
}

private void loadStockData(String searchText, DefaultTableModel model) {
    model.setRowCount(0);
    
    String sql = "SELECT p.id, p.name, c.name as category, p.stock_quantity, p.min_stock_level, " +
                "p.vendor, p.updated_at FROM products p " +
                "LEFT JOIN categories c ON p.category_id = c.id " +
                "WHERE 1=1";
    
    List<Object> params = new ArrayList<>();
    if (!searchText.isEmpty()) {
        sql += " AND (LOWER(p.name) LIKE ? OR LOWER(c.name) LIKE ?)";
        String searchPattern = "%" + searchText.toLowerCase() + "%";
        params.add(searchPattern);
        params.add(searchPattern);
    }
    sql += " ORDER BY p.name";
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        for (int i = 0; i < params.size(); i++) {
            stmt.setString(i + 1, params.get(i).toString());
        }
        ResultSet rs = stmt.executeQuery();
        
        while (rs.next()) {
            int stock = rs.getInt("stock_quantity");
            int minStock = rs.getInt("min_stock_level");
            String status;
            if (stock == 0) {
                status = "🔴 CRITICAL - OUT OF STOCK";
            } else if (stock <= minStock) {
                status = "🟡 LOW STOCK";
            } else {
                status = "🟢 OK";
            }
            
            model.addRow(new Object[]{
                rs.getInt("id"),
                rs.getString("name"),
                rs.getString("category") != null ? rs.getString("category") : "Uncategorized",
                stock,
                minStock,
                status,
                rs.getString("vendor") != null ? rs.getString("vendor") : "N/A",
                rs.getString("updated_at") != null ? rs.getString("updated_at") : "N/A"
            });
        }
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading stock data", e);
        showGlassMessage(null, "Error loading stock data: " + e.getMessage(), "Error", "error");
    }
}

private void showUpdateStockDialog(int productId, String productName, int currentStock, DefaultTableModel model, int row) {
    JDialog dialog = new JDialog((Frame) SwingUtilities.getWindowAncestor(this), "Update Stock - " + productName, true);
    dialog.setSize(400, 350);
    dialog.setLocationRelativeTo(this);
    dialog.setUndecorated(true);
    dialog.setBackground(new Color(0, 0, 0, 0));
    
    JPanel glass = new JPanel() {
        @Override protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(new Color(10, 12, 18));
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), 20, 20);
            g2.setColor(new Color(52, 152, 219, 160));
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawRoundRect(1, 1, getWidth()-3, getHeight()-3, 20, 20);
            g2.dispose();
        }
    };
    glass.setLayout(new BorderLayout());
    glass.setBorder(new EmptyBorder(20, 20, 20, 20));
    
    JLabel title = new JLabel("Update Stock Level");
    title.setFont(new Font("Segoe UI", Font.BOLD, 18));
    title.setForeground(new Color(52, 152, 219));
    title.setHorizontalAlignment(SwingConstants.CENTER);
    
    JPanel formPanel = new JPanel(new GridBagLayout());
    formPanel.setOpaque(false);
    GridBagConstraints gbc = new GridBagConstraints();
    gbc.insets = new Insets(10, 10, 10, 10);
    gbc.fill = GridBagConstraints.HORIZONTAL;
    
    // Current stock display
    gbc.gridx = 0; gbc.gridy = 0;
    formPanel.add(new JLabel("Current Stock:") {{ setForeground(Color.WHITE); }}, gbc);
    JLabel currentStockLabel = new JLabel(String.valueOf(currentStock));
    currentStockLabel.setForeground(new Color(46, 204, 113));
    currentStockLabel.setFont(new Font("Segoe UI", Font.BOLD, 14));
    gbc.gridx = 1;
    formPanel.add(currentStockLabel, gbc);
    
    // New stock
    gbc.gridx = 0; gbc.gridy = 1;
    formPanel.add(new JLabel("New Stock Level:") {{ setForeground(Color.WHITE); }}, gbc);
    JSpinner stockSpinner = new JSpinner(new SpinnerNumberModel(currentStock, 0, 100000, 1));
    styleSpinner(stockSpinner);
    gbc.gridx = 1;
    formPanel.add(stockSpinner, gbc);
    
    // Operation type
    gbc.gridx = 0; gbc.gridy = 2;
    formPanel.add(new JLabel("Operation:") {{ setForeground(Color.WHITE); }}, gbc);
    JComboBox<String> operationCombo = new JComboBox<>(new String[]{"Set Absolute Value", "Add", "Subtract"});
    styleComboBox(operationCombo);
    gbc.gridx = 1;
    formPanel.add(operationCombo, gbc);
    
    // Reason
    gbc.gridx = 0; gbc.gridy = 3;
    formPanel.add(new JLabel("Reason:") {{ setForeground(Color.WHITE); }}, gbc);
    JTextField reasonField = new JTextField();
    styleTextField(reasonField);
    gbc.gridx = 1;
    formPanel.add(reasonField, gbc);
    
    JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.CENTER, 15, 10));
    buttonPanel.setOpaque(false);
    
    JButton saveBtn = createSmallButton("Save", new Color(46, 204, 113));
    JButton cancelBtn = createSmallButton("Cancel", new Color(149, 165, 166));
    
    saveBtn.addActionListener(e -> {
        int newStockValue = (Integer) stockSpinner.getValue();
        String operation = (String) operationCombo.getSelectedItem();
        String reason = reasonField.getText().trim();
        int finalStock;
        
        switch (operation) {
            case "Add":
                finalStock = currentStock + newStockValue;
                break;
            case "Subtract":
                finalStock = currentStock - newStockValue;
                if (finalStock < 0) finalStock = 0;
                break;
            default:
                finalStock = newStockValue;
        }
        
        int change = finalStock - currentStock;
        
        try (Connection conn = Database.getConnection()) {
            conn.setAutoCommit(false);
            
            // Update product stock
            String updateSql = "UPDATE products SET stock_quantity = ?, updated_at = datetime('now') WHERE id = ?";
            try (PreparedStatement stmt = conn.prepareStatement(updateSql)) {
                stmt.setInt(1, finalStock);
                stmt.setInt(2, productId);
                stmt.executeUpdate();
            }
            
            // Log to inventory_log
            String logSql = "INSERT INTO inventory_log (product_id, action, quantity, previous_quantity, date, user) " +
                           "VALUES (?, ?, ?, ?, datetime('now'), ?)";
            try (PreparedStatement stmt = conn.prepareStatement(logSql)) {
                stmt.setInt(1, productId);
                stmt.setString(2, "MANUAL_ADJUSTMENT - " + reason);
                stmt.setInt(3, Math.abs(change));
                stmt.setInt(4, currentStock);
                stmt.setString(5, loggedInUser);
                stmt.executeUpdate();
            }
            
            // Log to item_flows
            String flowSql = "INSERT INTO item_flows (product_id, action, quantity, flow_date, user, vendor) " +
                            "VALUES (?, 'STOCK ADJUSTED', ?, datetime('now'), ?, 'MANUAL')";
            try (PreparedStatement stmt = conn.prepareStatement(flowSql)) {
                stmt.setInt(1, productId);
                stmt.setInt(2, Math.abs(change));
                stmt.setString(3, loggedInUser);
                stmt.executeUpdate();
            }
            
            conn.commit();
            
            logActivity("Stock updated for " + productName + ": " + currentStock + " -> " + finalStock + ". Reason: " + reason);
            showGlassMessage(dialog, "Stock updated successfully!", "Success", "success");
            
            model.setValueAt(finalStock, row, 3);
            String newStatus = finalStock == 0 ? "🔴 CRITICAL - OUT OF STOCK" : 
                              (finalStock <= (int) model.getValueAt(row, 4) ? "🟡 LOW STOCK" : "🟢 OK");
            model.setValueAt(newStatus, row, 5);
            
            dialog.dispose();
            
        } catch (SQLException ex) {
            showGlassMessage(dialog, "Error updating stock: " + ex.getMessage(), "Error", "error");
        }
    });
    
    cancelBtn.addActionListener(e -> dialog.dispose());
    
    buttonPanel.add(saveBtn);
    buttonPanel.add(cancelBtn);
    
    glass.add(title, BorderLayout.NORTH);
    glass.add(formPanel, BorderLayout.CENTER);
    glass.add(buttonPanel, BorderLayout.SOUTH);
    
    dialog.setContentPane(glass);
    dialog.setVisible(true);
}

