private JPanel createLowStockAlertPanel() {
    JPanel panel = new JPanel(new BorderLayout(10, 10));
    panel.setOpaque(false);
    panel.setBorder(new EmptyBorder(10, 10, 10, 10));
    
    String[] columns = {"Product Name", "Category", "Current Stock", "Min Stock", "Vendor", "Status", "Recommended Order"};
    DefaultTableModel model = new DefaultTableModel(columns, 0) {
        @Override public boolean isCellEditable(int r, int c) { return false; }
    };
    
    JTable alertTable = new JTable(model);
    styleTable(alertTable);
    
    JScrollPane scrollPane = new JScrollPane(alertTable);
    scrollPane.setOpaque(false);
    scrollPane.getViewport().setOpaque(false);
    scrollPane.setBorder(BorderFactory.createLineBorder(new Color(60, 80, 100), 1));
    
    JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 10, 5));
    btnPanel.setOpaque(false);
    
    JButton refreshBtn = createSmallButton("🔄 Refresh", new Color(52, 152, 219));
    JButton reorderBtn = createSmallButton("📦 Generate Reorder List", new Color(46, 204, 113));
    JButton exportBtn = createSmallButton("📎 Export", new Color(155, 89, 182));
    
    btnPanel.add(refreshBtn);
    btnPanel.add(reorderBtn);
    btnPanel.add(exportBtn);
    
    refreshBtn.addActionListener(e -> loadLowStockAlerts(model));
    reorderBtn.addActionListener(e -> generateReorderList(model));
    exportBtn.addActionListener(e -> exportLowStockToExcel(model));
    
    panel.add(btnPanel, BorderLayout.NORTH);
    panel.add(scrollPane, BorderLayout.CENTER);
    
    SwingUtilities.invokeLater(() -> loadLowStockAlerts(model));
    
    return panel;
}

private void loadLowStockAlerts(DefaultTableModel model) {
    model.setRowCount(0);
    
    String sql = "SELECT p.name, c.name as category, p.stock_quantity, p.min_stock_level, " +
                "p.vendor FROM products p " +
                "LEFT JOIN categories c ON p.category_id = c.id " +
                "WHERE p.stock_quantity <= p.min_stock_level " +
                "ORDER BY p.stock_quantity ASC";
    
    try (Statement stmt = Database.getConnection().createStatement();
         ResultSet rs = stmt.executeQuery(sql)) {
        
        while (rs.next()) {
            int stock = rs.getInt("stock_quantity");
            int minStock = rs.getInt("min_stock_level");
            String status = stock == 0 ? "🔴 OUT OF STOCK" : "🟡 LOW STOCK";
            int recommended = (minStock * 2) - stock;
            if (recommended < 0) recommended = minStock;
            
            model.addRow(new Object[]{
                rs.getString("name"),
                rs.getString("category") != null ? rs.getString("category") : "Uncategorized",
                stock,
                minStock,
                rs.getString("vendor") != null ? rs.getString("vendor") : "N/A",
                status,
                recommended
            });
        }
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading low stock alerts", e);
        showGlassMessage(null, "Error loading alerts: " + e.getMessage(), "Error", "error");
    }
}

private void generateReorderList(DefaultTableModel model) {
    StringBuilder report = new StringBuilder();
    report.append("=".repeat(60)).append("\n");
    report.append("REORDER RECOMMENDATION LIST\n");
    report.append("=".repeat(60)).append("\n");
    report.append("Generated: ").append(LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss"))).append("\n\n");
    report.append(String.format("%-30s %-10s %-12s %-12s %-15s\n", "Product", "Current", "Min Stock", "Recommended", "Vendor"));
    report.append("-".repeat(80)).append("\n");
    
    for (int i = 0; i < model.getRowCount(); i++) {
        String product = (String) model.getValueAt(i, 0);
        int current = (int) model.getValueAt(i, 2);
        int minStock = (int) model.getValueAt(i, 3);
        int recommended = (int) model.getValueAt(i, 6);
        String vendor = (String) model.getValueAt(i, 4);
        
        report.append(String.format("%-30s %-10d %-12d %-12d %-15s\n", 
            truncate(product, 30), current, minStock, recommended, vendor));
    }
    
    JTextArea textArea = new JTextArea(report.toString());
    textArea.setEditable(false);
    textArea.setFont(new Font("Monospaced", Font.PLAIN, 12));
    textArea.setBackground(new Color(22, 28, 38));
    textArea.setForeground(Color.WHITE);
    
    JScrollPane scrollPane = new JScrollPane(textArea);
    scrollPane.setPreferredSize(new Dimension(700, 500));
    
    JOptionPane.showMessageDialog(this, scrollPane, "Reorder List", JOptionPane.INFORMATION_MESSAGE);
}

private void exportLowStockToExcel(DefaultTableModel model) {
    JFileChooser fileChooser = new JFileChooser();
    fileChooser.setDialogTitle("Export Low Stock Report");
    fileChooser.setSelectedFile(new File("low_stock_report_" + LocalDate.now() + ".csv"));
    
    if (fileChooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
        try (PrintWriter pw = new PrintWriter(fileChooser.getSelectedFile())) {
            for (int i = 0; i < model.getColumnCount(); i++) {
                pw.print("\"" + model.getColumnName(i) + "\"");
                if (i < model.getColumnCount() - 1) pw.print(",");
            }
            pw.println();
            
            for (int row = 0; row < model.getRowCount(); row++) {
                for (int col = 0; col < model.getColumnCount(); col++) {
                    Object value = model.getValueAt(row, col);
                    pw.print("\"" + (value != null ? value.toString() : "") + "\"");
                    if (col < model.getColumnCount() - 1) pw.print(",");
                }
                pw.println();
            }
            showGlassMessage(null, "Low stock report exported successfully!", "Success", "success");
        } catch (IOException e) {
            showGlassMessage(null, "Error exporting: " + e.getMessage(), "Error", "error");
        }
    }
}

