private void loadExpiryData(DefaultTableModel model) {
    model.setRowCount(0);
    LocalDate today = LocalDate.now();
    
    String sql = "SELECT p.name, c.name as category, p.expire_date, p.stock_quantity " +
                "FROM products p LEFT JOIN categories c ON p.category_id = c.id " +
                "WHERE p.expire_date IS NOT NULL AND p.expire_date != ''";
    
    try (Statement stmt = Database.getConnection().createStatement();
         ResultSet rs = stmt.executeQuery(sql)) {
        
        while (rs.next()) {
            String expireStr = rs.getString("expire_date");
            try {
                LocalDate expireDate = LocalDate.parse(expireStr);
                long daysLeft = java.time.temporal.ChronoUnit.DAYS.between(today, expireDate);
                
                String status;
                String action;
                if (daysLeft < 0) {
                    status = "❌ EXPIRED";
                    action = "Dispose";
                } else if (daysLeft <= 30) {
                    status = "⚠️ Expiring Soon (" + daysLeft + " days)";
                    action = "Review";
                } else {
                    status = "✅ OK";
                    action = "-";
                }
                
                if (daysLeft <= 30) { // Show only products expiring in 30 days or less
                    model.addRow(new Object[]{
                        rs.getString("name"),
                        rs.getString("category") != null ? rs.getString("category") : "Uncategorized",
                        expireStr,
                        daysLeft < 0 ? 0 : daysLeft,
                        rs.getInt("stock_quantity"),
                        status,
                        action
                    });
                }
            } catch (DateTimeParseException ignored) {}
        }
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading expiry data", e);
        showGlassMessage(null, "Error loading expiry data: " + e.getMessage(), "Error", "error");
    }
}

private void disposeExpiredProduct(JTable table, DefaultTableModel model) {
    int selectedRow = table.getSelectedRow();
    if (selectedRow < 0) {
        showGlassMessage(null, "Please select a product to dispose", "No Selection", "warning");
        return;
    }
    
    String productName = (String) model.getValueAt(selectedRow, 0);
    int stock = (int) model.getValueAt(selectedRow, 4);
    
    int confirm = JOptionPane.showConfirmDialog(this,
        "Dispose of product: " + productName + "\nQuantity: " + stock + "\n\nThis will set stock to 0.",
        "Confirm Disposal", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
    
    if (confirm == JOptionPane.YES_OPTION) {
        try (Connection conn = Database.getConnection()) {
            String updateSql = "UPDATE products SET stock_quantity = 0 WHERE name = ?";
            try (PreparedStatement stmt = conn.prepareStatement(updateSql)) {
                stmt.setString(1, productName);
                stmt.executeUpdate();
            }
            
            String logSql = "INSERT INTO inventory_log (product_id, action, quantity, date, user) " +
                           "VALUES ((SELECT id FROM products WHERE name = ?), 'DISPOSED_EXPIRED', ?, datetime('now'), ?)";
            try (PreparedStatement stmt = conn.prepareStatement(logSql)) {
                stmt.setString(1, productName);
                stmt.setInt(2, stock);
                stmt.setString(3, loggedInUser);
                stmt.executeUpdate();
            }
        } catch (SQLException e) {
            showGlassMessage(null, "Error disposing product: " + e.getMessage(), "Error", "error");
            return;
        }
        
        logActivity("Expired product disposed: " + productName + " by " + loggedInUser);
        showGlassMessage(null, "Product disposed successfully!", "Success", "success");
        loadExpiryData(model);
    }
}

