private JLabel findValueLabel(JPanel card) {
    for (Component comp : card.getComponents()) {
        if (comp instanceof JLabel) {
            JLabel lbl = (JLabel) comp;
            if (lbl.getFont() != null && lbl.getFont().getSize() >= 18) {
                return lbl;
            }
        }
    }
    // fallback: return any JLabel
    for (Component comp : card.getComponents()) {
        if (comp instanceof JLabel) return (JLabel) comp;
    }
    return new JLabel();
}
