private void loadFastMoversData(String clientId, String selectedCategory) {
    JTextArea area = null;
    Component[] tabs = ((JTabbedPane) ((JPanel) ((BorderLayout) ((JPanel) getContentPane().getComponent(0)).getLayout()).getLayoutComponent(BorderLayout.CENTER)).getComponent(1)).getComponents();
    // Simplified: create dialog for now
    StringBuilder report = new StringBuilder();
    report.append("⚡ FAST MOVING PRODUCTS\n");
    report.append("=".repeat(60)).append("\n");
    report.append(String.format("%-5s %-30s %-15s %-12s %-10s\n", "Rank", "Product", "Monthly Sales", "Velocity", "Status"));
    report.append("-".repeat(80)).append("\n");
    
    String sql = """
        SELECT p.name, c.name as category, 
               COALESCE(SUM(si.quantity), 0) as monthly_sales,
               p.stock_quantity,
               CASE WHEN COALESCE(SUM(si.quantity), 0) > 0 
                    THEN (SELECT COALESCE(SUM(si2.quantity), 0) / 30.0 
                          FROM sale_items si2 
                          JOIN sales s2 ON si2.sale_id = s2.id 
                          WHERE si2.product_id = p.id AND DATE(s2.sale_date) >= DATE('now', '-30 days'))
                    ELSE 0 END as velocity
        FROM products p
        LEFT JOIN categories c ON p.category_id = c.id
        LEFT JOIN sale_items si ON p.id = si.product_id
        LEFT JOIN sales s ON si.sale_id = s.id AND DATE(s.sale_date) >= DATE('now', '-30 days')
        WHERE p.client_id = ?
        GROUP BY p.id
        HAVING monthly_sales > 0
        ORDER BY monthly_sales DESC
        LIMIT 20
    """;
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, clientId);
        ResultSet rs = stmt.executeQuery();
        
        int rank = 1;
        while (rs.next()) {
            int monthlySales = rs.getInt("monthly_sales");
            double velocity = rs.getDouble("velocity");
            String status = monthlySales >= 100 ? "🏆 Top Performer" : (monthlySales >= 50 ? "⭐ High Volume" : "📈 Moderate");
            
            report.append(String.format("%-5d %-30s %-15d %-12.1f %-10s\n",
                rank++, truncate(rs.getString("name"), 30),
                monthlySales, velocity, status));
        }
        
        showReportDialog("Fast Moving Products", report.toString());
        
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading fast movers", e);
        showGlassMessage(null, "Error: " + e.getMessage(), "Error", "error");
    }
}

private void loadSlowMoversData(String clientId, String selectedCategory) {
    StringBuilder report = new StringBuilder();
    report.append("🐌 SLOW MOVING PRODUCTS\n");
    report.append("=".repeat(60)).append("\n");
    report.append(String.format("%-5s %-30s %-15s %-10s %-12s %-15s\n", "Rank", "Product", "Monthly Sales", "Stock", "Days to Sell", "Recommendation"));
    report.append("-".repeat(90)).append("\n");
    
    String sql = """
        SELECT p.name, c.name as category, 
               COALESCE(SUM(si.quantity), 0) as monthly_sales,
               p.stock_quantity,
               CASE 
                   WHEN COALESCE(SUM(si.quantity), 0) > 0 
                   THEN p.stock_quantity * 30.0 / COALESCE(SUM(si.quantity), 1)
                   ELSE 999
               END as days_to_sell
        FROM products p
        LEFT JOIN categories c ON p.category_id = c.id
        LEFT JOIN sale_items si ON p.id = si.product_id
        LEFT JOIN sales s ON si.sale_id = s.id AND DATE(s.sale_date) >= DATE('now', '-30 days')
        WHERE p.client_id = ?
        GROUP BY p.id
        HAVING monthly_sales < 10 OR monthly_sales IS NULL
        ORDER BY monthly_sales ASC
        LIMIT 30
    """;
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, clientId);
        ResultSet rs = stmt.executeQuery();
        
        int rank = 1;
        while (rs.next()) {
            int monthlySales = rs.getInt("monthly_sales");
            int stock = rs.getInt("stock_quantity");
            double daysToSell = rs.getDouble("days_to_sell");
            String recommendation;
            
            if (monthlySales == 0) {
                recommendation = "⚠️ No sales - Consider discount or return to vendor";
            } else if (daysToSell > 180) {
                recommendation = "🔴 Very slow - Markdown recommended";
            } else if (daysToSell > 90) {
                recommendation = "🟡 Slow moving - Bundle with fast movers";
            } else {
                recommendation = "🟢 Acceptable - Monitor regularly";
            }
            
            report.append(String.format("%-5d %-30s %-15d %-10d %-12.0f %-15s\n",
                rank++, truncate(rs.getString("name"), 30),
                monthlySales, stock, daysToSell, recommendation));
        }
        
        showReportDialog("Slow Moving Products", report.toString());
        
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading slow movers", e);
        showGlassMessage(null, "Error: " + e.getMessage(), "Error", "error");
    }
}

private void loadSuggestedPurchaseData(String clientId) {
    StringBuilder report = new StringBuilder();
    report.append("🛒 SUGGESTED PURCHASE LIST (High Priority)\n");
    report.append("=".repeat(70)).append("\n");
    report.append(String.format("%-8s %-30s %-10s %-10s %-12s %-12s %-15s\n", 
        "Priority", "Product", "Stock", "Min Stock", "Monthly Sales", "Suggested Qty", "Urgency"));
    report.append("-".repeat(90)).append("\n");
    
    String sql = """
        SELECT p.id, p.name, c.name as category, p.stock_quantity, p.min_stock_level, p.vendor,
               COALESCE((SELECT SUM(si.quantity) FROM sale_items si 
                         JOIN sales s ON si.sale_id = s.id 
                         WHERE si.product_id = p.id AND DATE(s.sale_date) >= DATE('now', '-30 days')), 0) as monthly_sales,
               ROUND(COALESCE((SELECT SUM(si.quantity) FROM sale_items si 
                         JOIN sales s ON si.sale_id = s.id 
                         WHERE si.product_id = p.id AND DATE(s.sale_date) >= DATE('now', '-30 days')), 0) / 30.0, 2) as velocity
        FROM products p
        LEFT JOIN categories c ON p.category_id = c.id
        WHERE p.client_id = ?
        AND (p.stock_quantity <= p.min_stock_level OR 
             (p.stock_quantity < (SELECT COALESCE(SUM(si.quantity), 0) FROM sale_items si 
                                  JOIN sales s ON si.sale_id = s.id 
                                  WHERE si.product_id = p.id AND DATE(s.sale_date) >= DATE('now', '-30 days'))))
        ORDER BY (p.stock_quantity / NULLIF(
            (SELECT COALESCE(SUM(si.quantity), 1) FROM sale_items si 
             JOIN sales s ON si.sale_id = s.id 
             WHERE si.product_id = p.id AND DATE(s.sale_date) >= DATE('now', '-30 days')), 0)) ASC
    """;
    
    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
        stmt.setString(1, clientId);
        ResultSet rs = stmt.executeQuery();
        
        while (rs.next()) {
            int stock = rs.getInt("stock_quantity");
            int minStock = rs.getInt("min_stock_level");
            int monthlySales = rs.getInt("monthly_sales");
            double velocity = rs.getDouble("velocity");
            
            int suggestedQty;
            String priority;
            String urgency;
            
            if (stock <= 0) {
                suggestedQty = Math.max(minStock * 2, (int)(monthlySales * 1.5));
                priority = "🔴 CRITICAL";
                urgency = "ORDER IMMEDIATELY";
            } else if (stock <= minStock) {
                suggestedQty = Math.max(minStock * 2 - stock, (int)(monthlySales * 0.5));
                priority = "🟠 HIGH";
                urgency = "ORDER THIS WEEK";
            } else if (velocity > 0 && stock / velocity < 14) {
                suggestedQty = (int)(monthlySales * 0.3);
                priority = "🟡 MEDIUM";
                urgency = "ORDER SOON";
            } else {
                suggestedQty = 0;
                priority = "🟢 LOW";
                urgency = "Monitor Only";
            }
            
            if (suggestedQty > 0) {
                report.append(String.format("%-8s %-30s %-10d %-10d %-12d %-12d %-15s\n",
                    priority, truncate(rs.getString("name"), 30),
                    stock, minStock, monthlySales, suggestedQty, urgency));
            }
        }
        
        showReportDialog("Suggested Purchase List", report.toString());
        
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading suggested purchases", e);
        showGlassMessage(null, "Error: " + e.getMessage(), "Error", "error");
    }
}

