private void loadBusinessPerformanceData(String clientId, JTextArea area) {
    StringBuilder report = new StringBuilder();
    report.append("📊 BUSINESS PERFORMANCE ANALYSIS\n");
    report.append("=".repeat(60)).append("\n");
    
    BigDecimal totalSales = BigDecimal.ZERO;
    BigDecimal totalCOGS = BigDecimal.ZERO;
    BigDecimal totalGrossProfit = BigDecimal.ZERO;
    
    try {
        String sql = """
            SELECT c.name as category,
                   COALESCE(SUM(si.total_price), 0) as total_sales,
                   COALESCE(SUM(si.quantity * p.cost_price), 0) as cogs,
                   COALESCE(SUM(si.total_price - (si.quantity * p.cost_price)), 0) as gross_profit
            FROM categories c
            LEFT JOIN products p ON c.id = p.category_id
            LEFT JOIN sale_items si ON p.id = si.product_id
            LEFT JOIN sales s ON si.sale_id = s.id AND DATE(s.sale_date) >= DATE('now', '-90 days')
            WHERE c.client_id = ?
            GROUP BY c.id
            ORDER BY gross_profit DESC
        """;
        
        try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
            stmt.setString(1, clientId);
            ResultSet rs = stmt.executeQuery();
            
            report.append(String.format("\n%-25s %-15s %-15s %-15s %-10s\n", 
                "Category", "Total Sales", "COGS", "Gross Profit", "Margin %"));
            report.append("-".repeat(85)).append("\n");
            
            while (rs.next()) {
                BigDecimal sales = rs.getBigDecimal("total_sales");
                BigDecimal cogs = rs.getBigDecimal("cogs");
                BigDecimal profit = rs.getBigDecimal("gross_profit");
                BigDecimal margin = sales.compareTo(BigDecimal.ZERO) > 0 ?
                    profit.multiply(BigDecimal.valueOf(100)).divide(sales, 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
                
                totalSales = totalSales.add(sales);
                totalCOGS = totalCOGS.add(cogs);
                totalGrossProfit = totalGrossProfit.add(profit);
                
                report.append(String.format("%-25s TSh %-12s TSh %-12s TSh %-12s %-9.1f%%\n",
                    truncate(rs.getString("category") != null ? rs.getString("category") : "Uncategorized", 25),
                    formatNumber(sales), formatNumber(cogs), formatNumber(profit), margin));
            }
        }
        
        // Calculate overall metrics
        BigDecimal turnoverRatio = totalCOGS.compareTo(BigDecimal.ZERO) > 0 ?
            totalSales.divide(totalCOGS, 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
        
        BigDecimal roi = totalCOGS.compareTo(BigDecimal.ZERO) > 0 ?
            totalGrossProfit.multiply(BigDecimal.valueOf(100)).divide(totalCOGS, 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
        
        BigDecimal grossMargin = totalSales.compareTo(BigDecimal.ZERO) > 0 ?
            totalGrossProfit.multiply(BigDecimal.valueOf(100)).divide(totalSales, 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
        
        report.append("\n").append("=".repeat(60)).append("\n");
        report.append("📈 SUMMARY METRICS\n");
        report.append("-".repeat(40)).append("\n");
        report.append(String.format("Total Sales: TSh %s\n", formatNumber(totalSales)));
        report.append(String.format("Total COGS: TSh %s\n", formatNumber(totalCOGS)));
        report.append(String.format("Total Gross Profit: TSh %s\n", formatNumber(totalGrossProfit)));
        report.append(String.format("Stock Turnover Ratio: %.2fx\n", turnoverRatio));
        report.append(String.format("ROI: %.2f%%\n", roi));
        report.append(String.format("Gross Margin: %.2f%%\n", grossMargin));
        
        // Analysis notes
        report.append("\n").append("💡 ANALYSIS & RECOMMENDATIONS\n");
        report.append("-".repeat(40)).append("\n");
        
        if (turnoverRatio.doubleValue() > 3) {
            report.append("✅ Stock Turnover: Excellent! Products are moving quickly.\n");
        } else if (turnoverRatio.doubleValue() > 1.5) {
            report.append("📊 Stock Turnover: Good. Healthy inventory movement.\n");
        } else {
            report.append("⚠️ Stock Turnover: Low. Consider reducing inventory or increasing marketing.\n");
        }
        
        if (roi.doubleValue() > 20) {
            report.append("✅ ROI: Strong return on investment!\n");
        } else if (roi.doubleValue() > 10) {
            report.append("📊 ROI: Acceptable return.\n");
        } else {
            report.append("⚠️ ROI: Low return. Review pricing or reduce costs.\n");
        }
        
        if (grossMargin.doubleValue() > 30) {
            report.append("✅ Gross Margin: Healthy profit margin.\n");
        } else if (grossMargin.doubleValue() > 15) {
            report.append("📊 Gross Margin: Moderate margin. Look for cost savings.\n");
        } else {
            report.append("⚠️ Gross Margin: Thin margin. Urgently review pricing strategy.\n");
        }
        
        area.setText(report.toString());
        
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading performance data", e);
        area.setText("Error loading performance data: " + e.getMessage());
        showGlassMessage(null, "Error: " + e.getMessage(), "Error", "error");
    }
}
private void loadStockValuationData(DefaultTableModel model, String clientId,
        String selectedCategory, String searchText, JLabel totalValueLabel,
        JLabel totalItemsLabel, JLabel uniqueProductsLabel, JLabel forecastLabel,
        JLabel turnoverLabel, JLabel roiLabel) {

    model.setRowCount(0);
    BigDecimal totalValue = BigDecimal.ZERO;
    int totalItems = 0;
    int uniqueProducts = 0;
    BigDecimal projectedTotal = BigDecimal.ZERO;
    BigDecimal totalSales = BigDecimal.ZERO;
    BigDecimal totalCOGS = BigDecimal.ZERO;

    try {
        StringBuilder sql = new StringBuilder(
            "SELECT p.id, p.name, c.name as category, p.stock_quantity, p.cost_price, " +
            "p.selling_price, " +
            "COALESCE((SELECT SUM(si.quantity) FROM sale_items si " +
            "JOIN sales s ON si.sale_id = s.id " +
            "WHERE si.product_id = p.id AND s.client_id = p.client_id " +
            "AND DATE(s.sale_date) >= DATE('now', '-30 days')), 0) as monthly_sales, " +
            "COALESCE((SELECT SUM(si.total_price) FROM sale_items si " +
            "JOIN sales s ON si.sale_id = s.id " +
            "WHERE si.product_id = p.id AND s.client_id = p.client_id " +
            "AND DATE(s.sale_date) >= DATE('now', '-30 days')), 0) as monthly_revenue " +
            "FROM products p LEFT JOIN categories c ON p.category_id = c.id " +
            "WHERE p.client_id = ?");

        List<Object> params = new ArrayList<>();
        params.add(clientId);

        if (selectedCategory != null && !selectedCategory.equals("All Categories")) {
            sql.append(" AND UPPER(c.name) = ?");
            params.add(selectedCategory.toUpperCase());
        }
        if (searchText != null && !searchText.isEmpty()) {
            sql.append(" AND LOWER(p.name) LIKE ?");
            params.add("%" + searchText.toLowerCase() + "%");
        }
        sql.append(" ORDER BY p.name");

        try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql.toString())) {
            for (int i = 0; i < params.size(); i++) stmt.setObject(i + 1, params.get(i));
            ResultSet rs = stmt.executeQuery();

            while (rs.next()) {
                int stock = rs.getInt("stock_quantity");
                BigDecimal cost = rs.getBigDecimal("cost_price");
                BigDecimal selling = rs.getBigDecimal("selling_price");
                if (cost == null) cost = BigDecimal.ZERO;
                BigDecimal value = cost.multiply(BigDecimal.valueOf(stock));
                int monthlySales = rs.getInt("monthly_sales");
                BigDecimal monthlyRevenue = rs.getBigDecimal("monthly_revenue");
                
                totalSales = totalSales.add(monthlyRevenue);
                totalCOGS = totalCOGS.add(cost.multiply(BigDecimal.valueOf(monthlySales)));
                
                double velocity = monthlySales / 30.0;
                String forecast;
                int daysLeft = velocity > 0 ? (int) (stock / velocity) : Integer.MAX_VALUE;
                if (stock == 0) forecast = "🔴 OUT OF STOCK";
                else if (daysLeft <= 7) forecast = "🔴 CRITICAL (" + daysLeft + " days left)";
                else if (daysLeft <= 30) forecast = "🟡 LOW STOCK (" + daysLeft + " days left)";
                else forecast = "🟢 GOOD (" + daysLeft + " days)";

                BigDecimal projectedRevenue = BigDecimal.ZERO;
                if (monthlySales > 0 && stock > 0) {
                    projectedRevenue = selling.multiply(BigDecimal.valueOf(Math.min(monthlySales, stock)));
                }
                projectedTotal = projectedTotal.add(projectedRevenue);
                totalValue = totalValue.add(value);
                totalItems += stock;
                uniqueProducts++;

                model.addRow(new Object[]{
                    rs.getString("name"),
                    rs.getString("category") != null ? rs.getString("category") : "Uncategorized",
                    stock,
                    "TSh " + formatNumber(cost),
                    "TSh " + formatNumber(value),
                    monthlySales,
                    String.format("%.1f units/day", velocity),
                    forecast
                });
            }
        }

        totalValueLabel.setText("TSh " + formatNumber(totalValue));
        totalItemsLabel.setText(formatNumber(BigDecimal.valueOf(totalItems)));
        uniqueProductsLabel.setText(String.valueOf(uniqueProducts));
        forecastLabel.setText("TSh " + formatNumber(projectedTotal));
        
        // Calculate turnover and ROI
        BigDecimal grossProfit = totalSales.subtract(totalCOGS);
        BigDecimal turnoverRatio = totalCOGS.compareTo(BigDecimal.ZERO) > 0 ?
            totalSales.divide(totalCOGS, 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
        BigDecimal roi = totalCOGS.compareTo(BigDecimal.ZERO) > 0 ?
            grossProfit.multiply(BigDecimal.valueOf(100)).divide(totalCOGS, 2, RoundingMode.HALF_UP) : BigDecimal.ZERO;
        
        turnoverLabel.setText(turnoverRatio + "x");
        roiLabel.setText(roi + "%");

    } catch (Exception e) {
        LOGGER.log(Level.FINE, "Stock valuation load skipped", e);
    }
}
