private void loadProductsIntoCombo(JComboBox<String> combo) {
 combo.removeAllItems();
 try {
     List<Database.Product> products = Database.getAllProducts();
     for (Database.Product p : products) {
         combo.addItem(p.getName());
     }
     if (products.size() > 0) {
         combo.setSelectedIndex(0);
     }
 } catch (SQLException e) {
     e.printStackTrace();
 }
}

private void filterProducts(JComboBox<String> combo, String searchText) {
 combo.removeAllItems();
 try {
     List<Database.Product> products = Database.getAllProducts();
     for (Database.Product p : products) {
         if (p.getName().toLowerCase().contains(searchText.toLowerCase())) {
             combo.addItem(p.getName());
         }
     }
     if (combo.getItemCount() > 0) {
         combo.setSelectedIndex(0);
     }
 } catch (SQLException e) {
     e.printStackTrace();
 }
}



private String formatDate(String dateStr) {
 if (dateStr == null) return "N/A";
 if (dateStr.length() >= 10) {
     return dateStr.substring(0, 10);
 }
 return dateStr;
}

private String getBatchNumberForReceive(int productId, String dateStr) {
 try {
     String sql = "SELECT batch_number FROM item_flows WHERE product_id = ? AND action = 'RECEIVED' AND date(flow_date) = date(?) LIMIT 1";
     try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
         stmt.setInt(1, productId);
         stmt.setString(2, dateStr);
         ResultSet rs = stmt.executeQuery();
         if (rs.next()) {
             return rs.getString("batch_number");
         }
     }
 } catch (SQLException e) {
     e.printStackTrace();
 }
 return "N/A";
}

private String getReceiptNumberBySale(int saleId) {
 try {
     String sql = "SELECT title FROM notebooks WHERE content LIKE ? ORDER BY created_date DESC LIMIT 1";
     try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
         stmt.setString(1, "%" + saleId + "%");
         ResultSet rs = stmt.executeQuery();
         if (rs.next()) {
             String title = rs.getString("title");
             return title != null ? title : "RCP-" + saleId;
         }
     }
 } catch (SQLException e) {
     e.printStackTrace();
 }
 return "RCP-" + saleId;
}

private void sortTableByDate(DefaultTableModel model, int dateColumn) {
 Vector<?> data = model.getDataVector();
 Collections.sort(data, (a, b) -> {
     String dateA = (String) ((Vector<?>) a).get(dateColumn);
     String dateB = (String) ((Vector<?>) b).get(dateColumn);
     if (dateA == null) return 1;
     if (dateB == null) return -1;
     return dateB.compareTo(dateA);
 });
 model.setRowCount(0);
 for (Object row : data) {
     model.addRow((Vector<?>) row);
 }
}

