private void loadProductSuggestions(String searchText, DefaultListModel<String> listModel, JScrollPane suggestionScroll) {
    listModel.clear();
    try {
        String sql = "SELECT name FROM products WHERE " + whereClient() + " AND LOWER(name) LIKE ? ORDER BY name LIMIT 15";
        try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
            setClientParam(stmt, 1);
            stmt.setString(2, "%" + searchText.toLowerCase() + "%");
            ResultSet rs = stmt.executeQuery();
            while (rs.next()) {
                listModel.addElement(rs.getString("name"));
            }
        }
        suggestionScroll.setVisible(listModel.size() > 0);
    } catch (SQLException e) {
        e.printStackTrace();
    }
}

private void loadProductFullHistory(String productName, JLabel[] summaryLabels, DefaultTableModel historyModel) {
    historyModel.setRowCount(0);
    
    try {
        // First get product details
        String productSql = "SELECT p.id, p.name, p.cost_price, p.selling_price, p.stock_quantity, p.vendor, c.name as category " +
                           "FROM products p LEFT JOIN categories c ON p.category_id = c.id " +
                           "WHERE p.name = ? AND " + whereClient();
        
        int productId = -1;
        BigDecimal costPrice = BigDecimal.ZERO;
        BigDecimal sellingPrice = BigDecimal.ZERO;
        int currentStock = 0;
        String vendor = "N/A";
        String category = "N/A";
        
        try (PreparedStatement stmt = Database.getConnection().prepareStatement(productSql)) {
            stmt.setString(1, productName);
            setClientParam(stmt, 2);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                productId = rs.getInt("id");
                costPrice = rs.getBigDecimal("cost_price");
                sellingPrice = rs.getBigDecimal("selling_price");
                currentStock = rs.getInt("stock_quantity");
                vendor = rs.getString("vendor") != null ? rs.getString("vendor") : "N/A";
                category = rs.getString("category") != null ? rs.getString("category") : "Uncategorized";
            }
        }
        
        // Update summary cards
        summaryLabels[0].setText("<html><div style='text-align: center;'>Product Name<br><b>" + productName + "</b></div></html>");
        summaryLabels[1].setText("<html><div style='text-align: center;'>Vendor<br><b>" + vendor + "</b></div></html>");
        summaryLabels[2].setText("<html><div style='text-align: center;'>Current Stock<br><b>" + currentStock + "</b></div></html>");
        summaryLabels[3].setText("<html><div style='text-align: center;'>Cost Price<br><b>TSh " + formatNumber(costPrice) + "</b></div></html>");
        summaryLabels[4].setText("<html><div style='text-align: center;'>Selling Price<br><b>TSh " + formatNumber(sellingPrice) + "</b></div></html>");
        summaryLabels[5].setText("<html><div style='text-align: center;'>Category<br><b>" + category + "</b></div></html>");
        
        if (productId == -1) return;
        
        // Query combined history from item_flows and sales
        String historySql = 
            "SELECT 'FLOW' as source, flow_date as event_date, action, quantity, user, vendor as reference, created_date " +
            "FROM item_flows WHERE product_id = ? AND " + whereClient() +
            " UNION ALL " +
            "SELECT 'SALE' as source, s.sale_date as event_date, 'SOLD' as action, si.quantity, s.user, " +
            "CAST(s.id AS VARCHAR) as reference, s.sale_date as created_date " +
            "FROM sale_items si JOIN sales s ON si.sale_id = s.id " +
            "WHERE si.product_id = ? AND s." + whereClient() +
            " ORDER BY event_date DESC";
        
        // Map to track running stock (from oldest to newest, then reverse display)
        List<Object[]> historyRows = new ArrayList<>();
        
        try (PreparedStatement stmt = Database.getConnection().prepareStatement(historySql)) {
            stmt.setInt(1, productId);
            setClientParam(stmt, 2);
            stmt.setInt(3, productId);
            setClientParam(stmt, 4);
            ResultSet rs = stmt.executeQuery();
            
            while (rs.next()) {
                String date = rs.getString("event_date");
                String action = rs.getString("action");
                int quantity = rs.getInt("quantity");
                String user = rs.getString("user") != null ? rs.getString("user") : "SYSTEM";
                String reference = rs.getString("reference") != null ? rs.getString("reference") : "-";
                
                historyRows.add(new Object[]{
                    formatDate(date),
                    getActionIcon(action) + " " + action,
                    action.equals("SOLD") ? "-" + quantity : "+" + quantity,
                    "—", // Stock after will be calculated
                    user,
                    reference
                });
            }
        }
        
        // Calculate running stock (oldest to newest)
        List<Object[]> reversedRows = new ArrayList<>(historyRows);
        Collections.reverse(reversedRows);
        
        int runningStock = 0;
        for (int i = reversedRows.size() - 1; i >= 0; i--) {
            Object[] row = reversedRows.get(i);
            String action = row[1].toString().replace(getActionIcon("") + " ", "");
            int qtyChange = 0;
            String qtyStr = row[2].toString();
            if (qtyStr.startsWith("+")) {
                qtyChange = Integer.parseInt(qtyStr.substring(1));
                runningStock += qtyChange;
            } else if (qtyStr.startsWith("-")) {
                qtyChange = Integer.parseInt(qtyStr.substring(1));
                runningStock -= qtyChange;
            }
            row[3] = runningStock;
        }
        
        // Add to table (newest first)
        for (Object[] row : historyRows) {
            historyModel.addRow(row);
        }
        
    } catch (SQLException e) {
        e.printStackTrace();
        JOptionPane.showMessageDialog(null, "Error loading product history: " + e.getMessage());
    }
}

private String getActionIcon(String action) {
    switch (action.toUpperCase()) {
        case "NEW ITEM": return "🟢";
        case "RECEIVED": return "📦";
        case "RECEIVE": return "📦";
        case "SOLD": return "🛒";
        case "SALE": return "🛒";
        case "RETURN": return "🔄";
        case "RETURNED": return "🔄";
        case "ADJUSTMENT": return "⚙️";
        default: return "📝";
    }
}



private String whereClient() {
    String currentClientId = Database.getCurrentClientId();
    if (currentClientId != null && !currentClientId.isEmpty()) {
        return "client_id = ?";
    }
    return "(client_id IS NULL OR client_id = '' OR client_id = 'null') AND user_email = ?";
}

private void setClientParam(PreparedStatement stmt, int idx) throws SQLException {
    String currentClientId = Database.getCurrentClientId();
    String currentUserEmail = Database.getCurrentUserEmail();
    if (currentClientId != null && !currentClientId.isEmpty()) {
        stmt.setString(idx, currentClientId);
    } else {
        stmt.setString(idx, currentUserEmail);
    }
}

// Export movement to Excel
private void exportMovementToExcel(DefaultTableModel model) {
    JFileChooser fileChooser = new JFileChooser();
    fileChooser.setDialogTitle("Export Stock Movement");
    fileChooser.setSelectedFile(new File("stock_movement_" + LocalDate.now() + ".csv"));
    
    if (fileChooser.showSaveDialog(this) == JFileChooser.APPROVE_OPTION) {
        try (PrintWriter pw = new PrintWriter(fileChooser.getSelectedFile())) {
            pw.println("Stock Movement Report");
            pw.println("Generated: " + LocalDateTime.now().format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));
            pw.println();
            
            // Write headers
            for (int i = 0; i < model.getColumnCount(); i++) {
                pw.print("\"" + model.getColumnName(i) + "\"");
                if (i < model.getColumnCount() - 1) pw.print(",");
            }
            pw.println();
            
            // Write data
            for (int row = 0; row < model.getRowCount(); row++) {
                for (int col = 0; col < model.getColumnCount(); col++) {
                    Object value = model.getValueAt(row, col);
                    pw.print("\"" + (value != null ? value.toString() : "") + "\"");
                    if (col < model.getColumnCount() - 1) pw.print(",");
                }
                pw.println();
            }
            
            showGlassMessage(null, "Stock movement exported successfully!", "Success", "success");
        } catch (IOException e) {
            showGlassMessage(null, "Error exporting: " + e.getMessage(), "Error", "error");
        }
    }
}

