private JPanel createStockAuditPanel() {
    JPanel panel = new JPanel(new BorderLayout(10, 10));
    panel.setOpaque(false);
    panel.setBorder(new EmptyBorder(10, 10, 10, 10));
    
    String[] columns = {"Product Name", "Current Stock", "Last Count", "Variance", "Last Audit Date", "Status"};
    DefaultTableModel model = new DefaultTableModel(columns, 0) {
        @Override public boolean isCellEditable(int r, int c) { return false; }
    };
    
    JTable auditTable = new JTable(model);
    styleTable(auditTable);
    
    JScrollPane scrollPane = new JScrollPane(auditTable);
    scrollPane.setOpaque(false);
    scrollPane.getViewport().setOpaque(false);
    scrollPane.setBorder(BorderFactory.createLineBorder(new Color(60, 80, 100), 1));
    
    JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.LEFT, 10, 5));
    btnPanel.setOpaque(false);
    
    JButton refreshBtn = createSmallButton("🔄 Refresh", new Color(52, 152, 219));
    JButton auditBtn = createSmallButton("📝 Start Audit", new Color(46, 204, 113));
    JButton correctBtn = createSmallButton("✓ Correct Stock", new Color(255, 193, 7));
    JButton historyBtn = createSmallButton("📊 Audit History", new Color(155, 89, 182));
    
    btnPanel.add(refreshBtn);
    btnPanel.add(auditBtn);
    btnPanel.add(correctBtn);
    btnPanel.add(historyBtn);
    
    refreshBtn.addActionListener(e -> loadStockAuditData(model));
    auditBtn.addActionListener(e -> performStockAudit(auditTable, model));
    correctBtn.addActionListener(e -> correctStockVariance(auditTable, model));
    historyBtn.addActionListener(e -> showAuditHistory());
    
    panel.add(btnPanel, BorderLayout.NORTH);
    panel.add(scrollPane, BorderLayout.CENTER);
    
    SwingUtilities.invokeLater(() -> loadStockAuditData(model));
    
    return panel;
}

private void loadStockAuditData(DefaultTableModel model) {
    model.setRowCount(0);
    
    String sql = "SELECT p.name, p.stock_quantity, " +
                "COALESCE((SELECT quantity FROM inventory_log WHERE product_id = p.id AND action = 'AUDIT' ORDER BY date DESC LIMIT 1), 0) as last_count, " +
                "COALESCE((SELECT date FROM inventory_log WHERE product_id = p.id AND action = 'AUDIT' ORDER BY date DESC LIMIT 1), 'Never') as last_audit " +
                "FROM products p ORDER BY p.name";
    
    try (Statement stmt = Database.getConnection().createStatement();
         ResultSet rs = stmt.executeQuery(sql)) {
        
        while (rs.next()) {
            int currentStock = rs.getInt("stock_quantity");
            int lastCount = rs.getInt("last_count");
            int variance = currentStock - lastCount;
            String status = Math.abs(variance) > 5 ? "⚠️ Variance Detected" : "✅ OK";
            
            model.addRow(new Object[]{
                rs.getString("name"),
                currentStock,
                lastCount,
                variance,
                rs.getString("last_audit"),
                status
            });
        }
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading stock audit data", e);
        showGlassMessage(null, "Error loading audit data: " + e.getMessage(), "Error", "error");
    }
}

private void performStockAudit(JTable table, DefaultTableModel model) {
    int selectedRow = table.getSelectedRow();
    if (selectedRow < 0) {
        showGlassMessage(null, "Please select a product to audit", "No Selection", "warning");
        return;
    }
    
    String productName = (String) model.getValueAt(selectedRow, 0);
    int currentStock = (int) model.getValueAt(selectedRow, 1);
    
    String newStockStr = JOptionPane.showInputDialog(this, 
        "Enter counted stock for:\n" + productName + "\nCurrent system stock: " + currentStock,
        "Stock Audit", JOptionPane.QUESTION_MESSAGE);
    
    if (newStockStr != null && !newStockStr.trim().isEmpty()) {
        try {
            int newStock = Integer.parseInt(newStockStr.trim());
            
            try (Connection conn = Database.getConnection()) {
                String updateSql = "UPDATE products SET stock_quantity = ? WHERE name = ?";
                try (PreparedStatement stmt = conn.prepareStatement(updateSql)) {
                    stmt.setInt(1, newStock);
                    stmt.setString(2, productName);
                    stmt.executeUpdate();
                }
                
                String logSql = "INSERT INTO inventory_log (product_id, action, quantity, previous_quantity, date, user) " +
                               "VALUES ((SELECT id FROM products WHERE name = ?), 'AUDIT', ?, ?, datetime('now'), ?)";
                try (PreparedStatement stmt = conn.prepareStatement(logSql)) {
                    stmt.setString(1, productName);
                    stmt.setInt(2, newStock);
                    stmt.setInt(3, currentStock);
                    stmt.setString(4, loggedInUser);
                    stmt.executeUpdate();
                }
            }
            
            logActivity("Stock audit completed for " + productName + ": " + currentStock + " -> " + newStock);
            showGlassMessage(null, "Stock audit completed successfully!", "Success", "success");
            loadStockAuditData(model);
            
        } catch (NumberFormatException ex) {
            showGlassMessage(null, "Invalid number entered", "Error", "error");
        } catch (SQLException ex) {
            showGlassMessage(null, "Error updating stock: " + ex.getMessage(), "Error", "error");
        }
    }
}

private void correctStockVariance(JTable table, DefaultTableModel model) {
    int selectedRow = table.getSelectedRow();
    if (selectedRow < 0) {
        showGlassMessage(null, "Please select a product to correct", "No Selection", "warning");
        return;
    }
    
    String productName = (String) model.getValueAt(selectedRow, 0);
    int currentStock = (int) model.getValueAt(selectedRow, 1);
    int lastCount = (int) model.getValueAt(selectedRow, 2);
    
    int confirm = JOptionPane.showConfirmDialog(this,
        "Correct stock for: " + productName + "\n" +
        "Current system stock: " + currentStock + "\n" +
        "Last audit count: " + lastCount + "\n" +
        "Variance: " + (currentStock - lastCount) + "\n\n" +
        "This will update system stock to match last audit count.",
        "Confirm Correction", JOptionPane.YES_NO_OPTION);
    
    if (confirm == JOptionPane.YES_OPTION) {
        try (Connection conn = Database.getConnection()) {
            String updateSql = "UPDATE products SET stock_quantity = ? WHERE name = ?";
            try (PreparedStatement stmt = conn.prepareStatement(updateSql)) {
                stmt.setInt(1, lastCount);
                stmt.setString(2, productName);
                                stmt.executeUpdate();
            }
            
            String logSql = "INSERT INTO inventory_log (product_id, action, quantity, previous_quantity, date, user) " +
                           "VALUES ((SELECT id FROM products WHERE name = ?), 'STOCK_CORRECTION', ?, ?, datetime('now'), ?)";
            try (PreparedStatement stmt = conn.prepareStatement(logSql)) {
                stmt.setString(1, productName);
                stmt.setInt(2, lastCount);
                stmt.setInt(3, currentStock);
                stmt.setString(4, loggedInUser);
                stmt.executeUpdate();
            }
        } catch (SQLException ex) {
            showGlassMessage(null, "Error correcting stock: " + ex.getMessage(), "Error", "error");
            return;
        }
        
        logActivity("Stock corrected for " + productName + ": " + currentStock + " -> " + lastCount);
        showGlassMessage(null, "Stock corrected successfully!", "Success", "success");
        loadStockAuditData(model);
    }
}

private void showAuditHistory() {
    JDialog historyDialog = new JDialog((Frame) SwingUtilities.getWindowAncestor(this), "Audit History", true);
    historyDialog.setSize(800, 500);
    historyDialog.setLocationRelativeTo(this);
    historyDialog.setUndecorated(true);
    historyDialog.setBackground(new Color(0, 0, 0, 0));
    
    JPanel glass = new JPanel() {
        @Override protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(new Color(10, 12, 18));
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), 20, 20);
            g2.setColor(new Color(52, 152, 219, 160));
            g2.setStroke(new BasicStroke(1.5f));
            g2.drawRoundRect(1, 1, getWidth()-3, getHeight()-3, 20, 20);
            g2.dispose();
        }
    };
    glass.setLayout(new BorderLayout());
    glass.setBorder(new EmptyBorder(15, 15, 15, 15));
    
    JLabel title = new JLabel("Audit History Log");
    title.setFont(new Font("Segoe UI", Font.BOLD, 18));
    title.setForeground(new Color(52, 152, 219));
    title.setHorizontalAlignment(SwingConstants.CENTER);
    
    String[] columns = {"Date", "Product", "Action", "Previous Qty", "New Qty", "User"};
    DefaultTableModel historyModel = new DefaultTableModel(columns, 0) {
        @Override public boolean isCellEditable(int r, int c) { return false; }
    };
    
    JTable historyTable = new JTable(historyModel);
    styleTable(historyTable);
    
    JScrollPane scrollPane = new JScrollPane(historyTable);
    scrollPane.setBorder(BorderFactory.createLineBorder(new Color(60, 80, 100), 1));
    
    // Load audit history
    String sql = "SELECT DATE(il.date) as audit_date, p.name as product_name, il.action, " +
                "il.previous_quantity, il.quantity as new_quantity, il.user " +
                "FROM inventory_log il " +
                "JOIN products p ON il.product_id = p.id " +
                "WHERE il.action LIKE '%AUDIT%' OR il.action LIKE '%CORRECTION%' " +
                "ORDER BY il.date DESC LIMIT 200";
    
    try (Statement stmt = Database.getConnection().createStatement();
         ResultSet rs = stmt.executeQuery(sql)) {
        
        while (rs.next()) {
            historyModel.addRow(new Object[]{
                rs.getString("audit_date"),
                rs.getString("product_name"),
                rs.getString("action"),
                rs.getInt("previous_quantity"),
                rs.getInt("new_quantity"),
                rs.getString("user") != null ? rs.getString("user") : "SYSTEM"
            });
        }
    } catch (SQLException e) {
        LOGGER.log(Level.SEVERE, "Error loading audit history", e);
    }
    
    JButton closeBtn = createSmallButton("Close", new Color(149, 165, 166));
    closeBtn.addActionListener(e -> historyDialog.dispose());
    
    JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
    btnPanel.setOpaque(false);
    btnPanel.add(closeBtn);
    
    glass.add(title, BorderLayout.NORTH);
    glass.add(scrollPane, BorderLayout.CENTER);
    glass.add(btnPanel, BorderLayout.SOUTH);
    
    historyDialog.setContentPane(glass);
    historyDialog.setVisible(true);
}
private String formatNumber(BigDecimal number) {
    if (number == null) return "0";
    return String.format("%,.2f", number);
}

