private void showMessage(Component parent, String msg, String title, String type) {
    int msgType = type.equals("error") ? JOptionPane.ERROR_MESSAGE :
                  type.equals("warning") ? JOptionPane.WARNING_MESSAGE :
                  JOptionPane.INFORMATION_MESSAGE;
    JOptionPane.showMessageDialog(parent, msg, title, msgType);
}

