    dailyTable.setDefaultRenderer(Object.class, new DefaultTableCellRenderer() {
        @Override public Component getTableCellRendererComponent(JTable t, Object v,
                boolean sel, boolean foc, int row, int col) {
            Component c = super.getTableCellRendererComponent(t,v,sel,foc,row,col);
            if (!sel) {
                c.setBackground(row%2==0 ? new Color(18,22,32) : new Color(22,28,40));
                c.setForeground(Color.WHITE);
                if (col == 8 && v != null) {
                    c.setForeground(v.toString().contains("PROFIT") ? new Color(46,204,113) : new Color(231,76,60));
                    c.setFont(c.getFont().deriveFont(Font.BOLD));
                }
                if (col >= 4) {
                    try {
                        double val = Double.parseDouble(v.toString().replace("TSh","").replace(",","").trim());
                        if (col == 4 || col == 6) c.setForeground(new Color(231,76,60));
                        else if (val < 0) c.setForeground(new Color(231,76,60));
                        else if (col >= 5) c.setForeground(new Color(46,204,113));
                    } catch (Exception ignored) {}
                }
            }
            return c;
        }
    });
