// ── Check if a user is active (signed in recently) ───────────────────────────
private boolean checkUserActiveStatus(String username) {
    try (Connection conn = Database.getConnection();
         PreparedStatement pst = conn.prepareStatement(
             "SELECT timestamp FROM activity_log WHERE username=? " +
             "ORDER BY timestamp DESC LIMIT 1")) {
        pst.setString(1, username);
        ResultSet rs = pst.executeQuery();
        if (rs.next()) {
            String ts = rs.getString("timestamp");
            if (ts != null && !ts.isEmpty()) {
                // Active if logged activity within last 30 minutes
                try {
                    java.time.LocalDateTime last = java.time.LocalDateTime.parse(
                        ts.replace(" ", "T"));
                    return java.time.LocalDateTime.now().isBefore(last.plusMinutes(30));
                } catch (Exception ignored) {}
            }
        }
    } catch (SQLException ignored) {}
    return false;
}

// ── Sign-in metric bar chart (last 30 days) ───────────────────────────────────
private JPanel buildSignInChart() {
    // Gather last 30 days sign-in counts
    java.time.LocalDate today = java.time.LocalDate.now();
    Map<String, Integer> dayCounts = new java.util.LinkedHashMap<>();
    for (int i = 29; i >= 0; i--) {
        dayCounts.put(today.minusDays(i).toString(), 0);
    }

    try (Connection conn = Database.getConnection();
         PreparedStatement pst = conn.prepareStatement(
             "SELECT DATE(timestamp) as d, COUNT(*) as cnt FROM login_history " +
             "WHERE success=1 AND DATE(timestamp) >= ? " +
             "GROUP BY DATE(timestamp)")) {
        pst.setString(1, today.minusDays(29).toString());
        ResultSet rs = pst.executeQuery();
        while (rs.next()) {
            String d = rs.getString("d");
            if (dayCounts.containsKey(d)) dayCounts.put(d, rs.getInt("cnt"));
        }
    } catch (SQLException ignored) {}

    // Also count from activity_log
    try (Connection conn = Database.getConnection();
         PreparedStatement pst = conn.prepareStatement(
             "SELECT DATE(timestamp) as d, COUNT(*) as cnt FROM activity_log " +
             "WHERE activity LIKE '%signed%' OR activity LIKE '%LOGIN%' " +
             "GROUP BY DATE(timestamp)")) {
        ResultSet rs = pst.executeQuery();
        while (rs.next()) {
            String d = rs.getString("d");
            if (dayCounts.containsKey(d)) {
                dayCounts.merge(d, rs.getInt("cnt"), Integer::sum);
            }
        }
    } catch (SQLException ignored) {}

    final int[] counts = dayCounts.values().stream().mapToInt(Integer::intValue).toArray();
    final String[] labels = dayCounts.keySet().toArray(new String[0]);
    final int maxCount = Math.max(1, java.util.Arrays.stream(counts).max().orElse(1));

    JPanel chart = new JPanel() {
        @Override protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

            int w = getWidth(), h = getHeight();
            int padL = 36, padR = 10, padT = 16, padB = 32;
            int chartW = w - padL - padR;
            int chartH = h - padT - padB;

            // Background
            g2.setColor(new Color(14, 18, 26));
            g2.fillRoundRect(0, 0, w, h, 10, 10);

            // Grid lines
            int gridLines = 4;
            g2.setStroke(new BasicStroke(0.5f));
            for (int i = 0; i <= gridLines; i++) {
                int y = padT + (chartH * i / gridLines);
                g2.setColor(new Color(50, 60, 80));
                g2.drawLine(padL, y, padL + chartW, y);
                int val = maxCount - (maxCount * i / gridLines);
                g2.setColor(new Color(120, 120, 140));
                g2.setFont(new Font("Segoe UI", Font.PLAIN, 9));
                g2.drawString(String.valueOf(val), 2, y + 4);
            }

            // Bars
            if (counts.length == 0) { g2.dispose(); return; }
            float barW = (float) chartW / counts.length;
            float gap = Math.max(1, barW * 0.18f);

            for (int i = 0; i < counts.length; i++) {
                float barH = counts[i] == 0 ? 2 : (float) chartH * counts[i] / maxCount;
                float x = padL + i * barW + gap / 2;
                float y = padT + chartH - barH;

                // Color gradient by height
                float ratio = (float) counts[i] / maxCount;
                Color barColor = new Color(
                    (int)(46 + (210 - 46) * (1 - ratio)),
                    (int)(180 + (70 - 180) * (1 - ratio)),
                    (int)(90 + (60 - 90) * (1 - ratio)),
                    220
                );
                g2.setColor(barColor);
                g2.fillRoundRect((int)x, (int)y, (int)(barW - gap), (int)barH, 3, 3);

                // Highlight top
                g2.setColor(new Color(255, 255, 255, 40));
                g2.fillRoundRect((int)x, (int)y, (int)(barW - gap), 3, 3, 3);

                // X labels (every 5 days)
                if (i % 5 == 0) {
                    g2.setColor(new Color(120, 120, 140));
                    g2.setFont(new Font("Segoe UI", Font.PLAIN, 8));
                    String dayLbl = labels[i].substring(5); // MM-DD
                    g2.drawString(dayLbl, (int)x, padT + chartH + 14);
                }

                // Value on top if > 0
                if (counts[i] > 0) {
                    g2.setColor(new Color(200, 220, 200));
                    g2.setFont(new Font("Segoe UI", Font.BOLD, 8));
                    g2.drawString(String.valueOf(counts[i]), (int)x + 1, (int)y - 2);
                }
            }

            // X axis line
            g2.setColor(new Color(60, 80, 100));
            g2.setStroke(new BasicStroke(1));
            g2.drawLine(padL, padT + chartH, padL + chartW, padT + chartH);

            g2.dispose();
        }
        @Override public Dimension getPreferredSize() { return new Dimension(0, 180); }
    };
    chart.setOpaque(false);
    chart.setMaximumSize(new Dimension(Integer.MAX_VALUE, 180));
    return chart;
}

// ── Password hash helper for security answers ────────────────────────────────
private String hashSecAnswer(String input) {
    if (input == null) return "";
    try {
        java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
        byte[] hash = md.digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) sb.append(String.format("%02x", b));
        return sb.toString();
    } catch (Exception e) { return input; }
}
