// Helper method to convert string role to LocalUserStore.Role enum
private LocalUserStore.Role convertRoleStringToEnum(String role) {
    if (role == null || role.isEmpty()) {
        return LocalUserStore.Role.USER;
    }
    
    // Remove anything after colon (e.g., "ADMIN:Sale,Inventory" -> "ADMIN")
    String cleanRole = role;
    if (role.contains(":")) {
        String[] parts = role.split(":");
        if (parts.length > 0) {
            cleanRole = parts[0];
        }
    }
    
    switch (cleanRole.toUpperCase()) {
        case "CEO": return LocalUserStore.Role.CEO;
        case "OWNER": return LocalUserStore.Role.OWNER;
        case "SUPERADMIN": return LocalUserStore.Role.SUPERADMIN;
        case "ADMIN": return LocalUserStore.Role.ADMIN;
        case "MANAGER": return LocalUserStore.Role.MANAGER;
        case "DIRECTOR": return LocalUserStore.Role.DIRECTOR;
        case "SUPERVISOR": return LocalUserStore.Role.SUPERVISOR;
        case "CASHIER": return LocalUserStore.Role.CASHIER;
        case "EMPLOYEE": return LocalUserStore.Role.EMPLOYEE;
        case "VIEWER": return LocalUserStore.Role.VIEWER;
        default: return LocalUserStore.Role.USER;
    }
}
private void addEmailToSavedList(String email) {
    try {
        File savedEmailsFile = new File(System.getProperty("user.home") + File.separator + ".gratispos" + File.separator + "saved_emails.txt");
        List<String> emails = new ArrayList<>();
        if (savedEmailsFile.exists()) {
            try (BufferedReader br = new BufferedReader(new FileReader(savedEmailsFile))) {
                String line;
                while ((line = br.readLine()) != null) {
                    if (!line.trim().isEmpty() && !line.equals(email)) {
                        emails.add(line.trim());
                    }
                }
            }
        }
        emails.add(0, email);
        savedEmailsFile.getParentFile().mkdirs();
        try (PrintWriter pw = new PrintWriter(new FileWriter(savedEmailsFile))) {
            for (String e : emails) {
                pw.println(e);
            }
        }
    } catch (Exception ex) {
        LOGGER.log(Level.WARNING, "Failed to add email to saved list", ex);
    }
}
