    private JButton createAdminButton(String text) {
    JButton button = new JButton(text);
    button.setFont(new Font("Segoe UI", Font.BOLD, 13));
    button.setAlignmentX(Component.LEFT_ALIGNMENT);
    button.setMaximumSize(new Dimension(Integer.MAX_VALUE, 40));
    button.setForeground(Color.WHITE);
    button.setFocusPainted(false);
    button.setBorder(BorderFactory.createEmptyBorder(10, 15, 10, 15));
    button.setCursor(new Cursor(Cursor.HAND_CURSOR));
    button.setOpaque(false);
    
    Color baseColor = new Color(52, 152, 219);
    Color hoverColor = new Color(41, 128, 185);
    Color pressColor = new Color(31, 97, 141);
    
    button.addMouseListener(new MouseAdapter() {
        @Override
        public void mouseEntered(MouseEvent e) {
            button.setBackground(hoverColor);
            button.repaint();
        }
        
        @Override
        public void mouseExited(MouseEvent e) {
            button.setBackground(null);
            button.repaint();
        }
        
        @Override
        public void mousePressed(MouseEvent e) {
            button.setBackground(pressColor);
            button.repaint();
        }
        
        @Override
        public void mouseReleased(MouseEvent e) {
            button.setBackground(hoverColor);
            button.repaint();
        }
    });
    
    button.addActionListener(e -> {
        button.setBackground(pressColor);
        Timer timer = new Timer(100, ev -> button.setBackground(hoverColor));
        timer.setRepeats(false);
        timer.start();
    });
    
    return button;
}

