        List<Integer> itemsToDelete = new ArrayList<>();
        for (int i = 0; i < model.getRowCount(); i++) {
            if ((Boolean) model.getValueAt(i, 0)) itemsToDelete.add(salesRecords.get(i).itemId);
        }
        if (itemsToDelete.isEmpty()) {
            showGlassMessage(managementDialog, "Please select at least one item to delete", "No Selection", "warning");
            return;
        }
