    SpinnerNumberModel priceModel = new SpinnerNumberModel(record.unitPrice.doubleValue(), 0.0, 999999.0, 1.0);
    JSpinner priceSpinner = new JSpinner(priceModel);
    priceSpinner.setFont(new Font("Segoe UI", Font.PLAIN, 13));
    ((JSpinner.DefaultEditor) priceSpinner.getEditor()).getTextField().setForeground(Color.WHITE);
    ((JSpinner.DefaultEditor) priceSpinner.getEditor()).getTextField().setBackground(new Color(60, 60, 60));
