    lblTotal.setFont(new Font("Segoe UI", Font.BOLD, 12));
    lblTotal.setForeground(Color.WHITE);
    gbc.gridx = 0; gbc.gridy = 2;
    formPanel.add(lblTotal, gbc);
    
