    private void showUserManagementDialog() {
        try {
            List<Map<String, String>> users = getAllUsersFromDatabase();
            
            if (users.isEmpty()) {
                JOptionPane.showMessageDialog(this, "No users found in the system.", "Information", JOptionPane.INFORMATION_MESSAGE);
                return;
            }
            
            // Create dialog
            JDialog manageDialog = new JDialog((Frame) SwingUtilities.getWindowAncestor(this), "Manage Users", true);
            manageDialog.setSize(700, 500);
            manageDialog.setLocationRelativeTo(this);
            manageDialog.setLayout(new BorderLayout());
            
            // Title panel
            JPanel titlePanel = new JPanel();
            titlePanel.setBackground(new Color(52, 152, 219));
            titlePanel.setPreferredSize(new Dimension(700, 50));
            JLabel titleLabel = new JLabel("Manage System Users (" + users.size() + " users)");
            titleLabel.setFont(new Font("Segoe UI", Font.BOLD, 18));
            titleLabel.setForeground(Color.WHITE);
            titlePanel.add(titleLabel);
            manageDialog.add(titlePanel, BorderLayout.NORTH);
            
            // Create table model
            String[] columns = {"Username", "Email", "Role", "Status"};
            DefaultTableModel model = new DefaultTableModel(columns, 0) {
                @Override
                public boolean isCellEditable(int row, int col) {
                    return false;
                }
            };
            
            // Load users into table
            for (Map<String, String> user : users) {
                model.addRow(new Object[]{
                    user.get("username"),
                    user.get("email") != null && !user.get("email").isEmpty() ? user.get("email") : "N/A",
                    user.get("role") != null ? user.get("role") : "USER",
                    user.get("status") != null ? user.get("status") : "ACTIVE"
                });
            }
            
            JTable userTable = new JTable(model);
            userTable.setRowHeight(35);
            userTable.setFont(new Font("Segoe UI", Font.PLAIN, 13));
            userTable.getTableHeader().setFont(new Font("Segoe UI", Font.BOLD, 13));
            userTable.getTableHeader().setBackground(new Color(52, 152, 219));
            userTable.getTableHeader().setForeground(Color.WHITE);
            
            JScrollPane scrollPane = new JScrollPane(userTable);
            manageDialog.add(scrollPane, BorderLayout.CENTER);
            
            // Button panel
            JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.CENTER, 15, 10));
            buttonPanel.setBackground(new Color(240, 240, 240));
            
            JButton editRoleBtn = new JButton("Change Role");
            JButton resetPassBtn = new JButton("Reset Password");
            JButton deleteBtn = new JButton("Delete User");
            JButton refreshBtn = new JButton("Refresh");
            JButton closeBtn = new JButton("Close");
            
            buttonPanel.add(editRoleBtn);
            buttonPanel.add(resetPassBtn);
            buttonPanel.add(deleteBtn);
            buttonPanel.add(refreshBtn);
            buttonPanel.add(closeBtn);
            manageDialog.add(buttonPanel, BorderLayout.SOUTH);
            
            // Delete User action
            deleteBtn.addActionListener(e -> {
                int rowIdx = userTable.getSelectedRow();  // Using rowIdx instead of selectedRow
                if (rowIdx == -1) {
                    JOptionPane.showMessageDialog(manageDialog, "Please select a user first.", "No Selection", JOptionPane.WARNING_MESSAGE);
                    return;
                }
                
                String username = (String) model.getValueAt(rowIdx, 0);
                String role = (String) model.getValueAt(rowIdx, 2);
                
                if (username.equals(loggedInUser)) {
                    JOptionPane.showMessageDialog(manageDialog, "Cannot delete your own account.", "Access Denied", JOptionPane.WARNING_MESSAGE);
                    return;
                }
                
                if (role != null && (role.contains("SUPERADMIN") || role.equals("CEO") || role.equals("OWNER"))) {
                    JOptionPane.showMessageDialog(manageDialog, "Cannot delete owner/SuperAdmin account.", "Access Denied", JOptionPane.WARNING_MESSAGE);
                    return;
                }
                
                int confirm = JOptionPane.showConfirmDialog(manageDialog,
                    "Are you sure you want to delete user: " + username + "?\nThis action cannot be undone.",
                    "Confirm Delete", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
                
                if (confirm == JOptionPane.YES_OPTION) {
                    try {
                        if (Database.deleteUser(username)) {
                            model.removeRow(rowIdx);
                            JOptionPane.showMessageDialog(manageDialog, "User deleted successfully!", "Success", JOptionPane.INFORMATION_MESSAGE);
                            logActivity("User deleted: " + username + " by " + loggedInUser);
                        } else {
                            JOptionPane.showMessageDialog(manageDialog, "Failed to delete user.", "Error", JOptionPane.ERROR_MESSAGE);
                        }
                    } catch (SQLException ex) {
                        JOptionPane.showMessageDialog(manageDialog, "Error deleting user: " + ex.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
                    }
                }
            });
            
            // Edit Role action
            editRoleBtn.addActionListener(e -> {
                int rowIdx = userTable.getSelectedRow();
                if (rowIdx == -1) {
                    JOptionPane.showMessageDialog(manageDialog, "Please select a user first.", "No Selection", JOptionPane.WARNING_MESSAGE);
                    return;
                }
                
                String username = (String) model.getValueAt(rowIdx, 0);
                if (username.equals(loggedInUser)) {
                    JOptionPane.showMessageDialog(manageDialog, "Cannot change your own role.", "Access Denied", JOptionPane.WARNING_MESSAGE);
                    return;
                }
                
                String[] roles = {"USER", "CASHIER", "EMPLOYEE", "SUPERVISOR", "MANAGER", "ADMIN", "SUPERADMIN"};
                String newRole = (String) JOptionPane.showInputDialog(manageDialog,
                    "Select new role for " + username + ":",
                    "Change Role",
                    JOptionPane.QUESTION_MESSAGE,
                    null,
                    roles,
                    model.getValueAt(rowIdx, 2));
                
                if (newRole != null && !newRole.equals(model.getValueAt(rowIdx, 2))) {
                    try {
                        if (Database.updateUserPrivileges(username, newRole)) {
                            model.setValueAt(newRole, rowIdx, 2);
                            JOptionPane.showMessageDialog(manageDialog, "Role updated successfully!", "Success", JOptionPane.INFORMATION_MESSAGE);
                            logActivity("Role changed for user " + username + " to " + newRole + " by " + loggedInUser);
                        } else {
                            JOptionPane.showMessageDialog(manageDialog, "Failed to update role.", "Error", JOptionPane.ERROR_MESSAGE);
                        }
                    } catch (SQLException ex) {
                        JOptionPane.showMessageDialog(manageDialog, "Error updating role: " + ex.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
                    }
                }
            });
            
            // Reset Password action
            resetPassBtn.addActionListener(e -> {
                int rowIdx = userTable.getSelectedRow();
                if (rowIdx == -1) {
                    JOptionPane.showMessageDialog(manageDialog, "Please select a user first.", "No Selection", JOptionPane.WARNING_MESSAGE);
                    return;
                }
                
                String username = (String) model.getValueAt(rowIdx, 0);
                
                JPasswordField passwordField = new JPasswordField();
                JPasswordField confirmField = new JPasswordField();
                
                JPanel panel = new JPanel(new GridLayout(2, 2, 10, 10));
                panel.add(new JLabel("New Password:"));
                panel.add(passwordField);
                panel.add(new JLabel("Confirm Password:"));
                panel.add(confirmField);
                
                int result = JOptionPane.showConfirmDialog(manageDialog, panel, "Reset Password for " + username, 
                    JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);
                
                if (result == JOptionPane.OK_OPTION) {
                    String password = new String(passwordField.getPassword());
                    String confirm = new String(confirmField.getPassword());
                    
                    if (password.isEmpty()) {
                        JOptionPane.showMessageDialog(manageDialog, "Password cannot be empty.", "Error", JOptionPane.ERROR_MESSAGE);
                        return;
                    }
                    if (!password.equals(confirm)) {
                        JOptionPane.showMessageDialog(manageDialog, "Passwords do not match.", "Error", JOptionPane.ERROR_MESSAGE);
                        return;
                    }
                    if (password.length() < 4) {
                        JOptionPane.showMessageDialog(manageDialog, "Password must be at least 4 characters.", "Error", JOptionPane.ERROR_MESSAGE);
                        return;
                    }
                    
                    try {
                        if (Database.updateUserPassword(username, password)) {
                            JOptionPane.showMessageDialog(manageDialog, "Password reset successfully!", "Success", JOptionPane.INFORMATION_MESSAGE);
                            logActivity("Password reset for user " + username + " by " + loggedInUser);
                        } else {
                            JOptionPane.showMessageDialog(manageDialog, "Failed to reset password.", "Error", JOptionPane.ERROR_MESSAGE);
                        }
                    } catch (SQLException ex) {
                        JOptionPane.showMessageDialog(manageDialog, "Error resetting password: " + ex.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
                    }
                }
            });
            
            // Refresh button
            refreshBtn.addActionListener(e -> {
                manageDialog.dispose();
                showUserManagementDialog();
            });
            
            // Close button
            closeBtn.addActionListener(e -> manageDialog.dispose());
            
            manageDialog.setVisible(true);
            
        } catch (SQLException e) {
            e.printStackTrace();
            JOptionPane.showMessageDialog(this, "Error loading users: " + e.getMessage(), "Error", JOptionPane.ERROR_MESSAGE);
        }
    }

    // Helper method to get all users from database (using your Database class)
    private List<Map<String, String>> getAllUsersFromDatabase() throws SQLException {
        List<Map<String, String>> users = new ArrayList<>();
        
        String sql = "SELECT username, email, privileges, account_status FROM users";
        String clientId = Database.getCurrentClientId();
        
        if (clientId != null && !clientId.isEmpty()) {
            sql += " WHERE client_id = ?";
        } else {
            sql += " WHERE (client_id IS NULL OR client_id = '' OR client_id = 'null')";
        }
        sql += " ORDER BY id ASC";
        
        try (Connection conn = Database.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            
            if (clientId != null && !clientId.isEmpty()) {
                stmt.setString(1, clientId);
            }
            
            ResultSet rs = stmt.executeQuery();
            
            while (rs.next()) {
                Map<String, String> user = new HashMap<>();
                user.put("username", rs.getString("username"));
                user.put("email", rs.getString("email"));
                
                String privileges = rs.getString("privileges");
                // Extract role (remove restrictions after colon if any)
                if (privileges != null && privileges.contains(":")) {
                    privileges = privileges.split(":")[0];
                }
                user.put("role", privileges != null ? privileges : "USER");
                user.put("status", rs.getString("account_status") != null ? rs.getString("account_status") : "ACTIVE");
                users.add(user);
            }
        }
        
        return users;
    }


