    // Load users to table
    private void loadUsersToTable(DefaultTableModel model) {
        model.setRowCount(0);
        String clientId = Database.getCurrentClientId();
        if (clientId == null) clientId = this.currentClientId;
        
        try (Connection conn = Database.getLocalConnection();
        	     PreparedStatement stmt = conn.prepareStatement(
        	         "SELECT username, email, privileges, account_status FROM users " +
        	         "WHERE client_id = ? AND (user_email = ? OR email = ?) ORDER BY id")) {
        	    stmt.setString(1, clientId);
        	    stmt.setString(2, Database.getCurrentUserEmail());
        	    stmt.setString(3, Database.getCurrentUserEmail());
        	    ResultSet rs = stmt.executeQuery();
            while (rs.next()) {
                String role = rs.getString("privileges");
                if (role != null && role.contains(":")) {
                    role = role.split(":")[0];
                }
                model.addRow(new Object[]{
                    rs.getString("username"),
                    rs.getString("email") != null ? rs.getString("email") : "N/A",
                    role != null ? role : "USER",
                    rs.getString("account_status") != null ? rs.getString("account_status") : "ACTIVE"
                });
            }
        } catch (SQLException e) {
            LOGGER.log(Level.WARNING, "Error loading users", e);
        }
    }

