    // Change username
    private void changeUsername(String username, DefaultTableModel model, int row) {
        String newUsername = JOptionPane.showInputDialog(this, "Enter new username for " + username + ":", username);
        if (newUsername == null || newUsername.trim().isEmpty()) return;
        newUsername = newUsername.trim();
        
        try (Connection conn = Database.getConnection();
             PreparedStatement stmt = conn.prepareStatement("UPDATE users SET username = ? WHERE username = ?")) {
            stmt.setString(1, newUsername);
            stmt.setString(2, username);
            stmt.executeUpdate();
            
            if (Database.checkTursoConnection()) {
                SQLiteCloudClient.executeUpdate("UPDATE users SET username = ? WHERE username = ?", newUsername, username);
            }
            
            model.setValueAt(newUsername, row, 0);
            showGlassMessage(null, "Username changed successfully!", "Success", "success");
            logActivity("Username changed from " + username + " to " + newUsername + " by " + loggedInUser);
            
        } catch (SQLException | IOException e) {
            showGlassMessage(null, "Error: " + e.getMessage(), "Error", "error");
        }
    }

