    // Check if database is locked
    private boolean isDatabaseLocked() {
        File lockFile = new File(System.getProperty("user.home") + File.separator + ".gratispos" + File.separator + "database.lock");
        return lockFile.exists();
    }

    // Lock database
 // Lock database
    private void lockDatabase(JDialog parent, JLabel statusLabel, JButton toggleBtn) {
        int confirm = JOptionPane.showConfirmDialog(parent,
            "Locking the database will prevent any modifications.\nAre you sure?",
            "Confirm Lock", 
            JOptionPane.YES_NO_OPTION, 
            JOptionPane.WARNING_MESSAGE);
        
        if (confirm != JOptionPane.YES_OPTION) return;
        
        try {
            // Create lock file
            File lockFile = new File(System.getProperty("user.home") + 
                File.separator + ".gratispos" + File.separator + "database.lock");
            File dir = lockFile.getParentFile();
            if (!dir.exists()) {
                dir.mkdirs();
            }
            
            try (PrintWriter pw = new PrintWriter(lockFile)) {
                pw.println("LOCKED");
                pw.println("Locked by: " + loggedInUser);
                pw.println("Locked at: " + LocalDateTime.now());
            }
            
            // Update database setting
            try (Connection conn = Database.getConnection();
                 PreparedStatement stmt = conn.prepareStatement(
                     "INSERT OR REPLACE INTO app_settings (key, value) VALUES ('database_locked', 'true')")) {
                stmt.executeUpdate();
            }
            
            // Update UI
            statusLabel.setText("🔒 LOCKED");
            statusLabel.setForeground(new Color(231, 76, 60));
            toggleBtn.setText("🔓 Unlock Database");
            toggleBtn.setBackground(new Color(46, 204, 113));
            
            // Log activity
            logActivity("Database locked by: " + loggedInUser);
            
            // Show success message
            JOptionPane.showMessageDialog(parent, 
                "Database locked successfully!", 
                "Success", 
                JOptionPane.INFORMATION_MESSAGE);
            
        } catch (Exception e) {
            JOptionPane.showMessageDialog(parent, 
                "Error locking database: " + e.getMessage(), 
                "Error", 
                JOptionPane.ERROR_MESSAGE);
        }
    }

    // Unlock database
    private void unlockDatabase(JDialog parent, JLabel statusLabel, JButton toggleBtn) {
        String password = JOptionPane.showInputDialog(parent, 
            "Enter master password to unlock:", 
            "Unlock Database", 
            JOptionPane.PLAIN_MESSAGE);
        
        if (password == null || password.trim().isEmpty()) {
            return;
        }
        
        if (password.equals("gratispos2024")) {
            try {
                // Delete lock file
                File lockFile = new File(System.getProperty("user.home") + 
                    File.separator + ".gratispos" + File.separator + "database.lock");
                if (lockFile.exists()) {
                    lockFile.delete();
                }
                
                // Update database setting
                try (Connection conn = Database.getConnection();
                     PreparedStatement stmt = conn.prepareStatement(
                         "INSERT OR REPLACE INTO app_settings (key, value) VALUES ('database_locked', 'false')")) {
                    stmt.executeUpdate();
                }
                
                // Update UI
                statusLabel.setText("🔓 UNLOCKED");
                statusLabel.setForeground(new Color(46, 204, 113));
                toggleBtn.setText("🔒 Lock Database");
                toggleBtn.setBackground(new Color(231, 76, 60));
                
                // Log activity
                logActivity("Database unlocked by: " + loggedInUser);
                
                // Show success message
                JOptionPane.showMessageDialog(parent, 
                    "Database unlocked successfully!", 
                    "Success", 
                    JOptionPane.INFORMATION_MESSAGE);
                    
            } catch (Exception e) {
                JOptionPane.showMessageDialog(parent, 
                    "Error unlocking database: " + e.getMessage(), 
                    "Error", 
                    JOptionPane.ERROR_MESSAGE);
            }
        } else {
            JOptionPane.showMessageDialog(parent, 
                "Incorrect master password!\nAccess denied.", 
                "Access Denied", 
                JOptionPane.ERROR_MESSAGE);
        }
    }

    // Encrypt database
    private void encryptDatabase(JDialog parent) {
        int confirm = JOptionPane.showConfirmDialog(parent,
            "Encrypting the database will add an extra layer of security.\nThis may take a few moments.\nContinue?",
            "Confirm Encryption", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        
        if (confirm != JOptionPane.YES_OPTION) return;
        
        try {
            // Set encryption flag
            try (Connection conn = Database.getConnection();
                 PreparedStatement stmt = conn.prepareStatement(
                     "INSERT OR REPLACE INTO app_settings (key, value) VALUES ('encrypted', 'true')")) {
                stmt.executeUpdate();
            }
            
            logActivity("Database encrypted by: " + loggedInUser);
            showGlassMessage(parent, "Database encrypted successfully!\nRestart the application for changes to take full effect.", "Success", "success");
            
        } catch (SQLException e) {
            showGlassMessage(parent, "Error encrypting database: " + e.getMessage(), "Error", "error");
        }
    }

    // Make database invalid to other apps
    private void makeDatabaseInvalid(JDialog parent) {
        int confirm = JOptionPane.showConfirmDialog(parent,
            "This will add a proprietary header to the database file,\nmaking it unreadable by other applications.\nContinue?",
            "Confirm", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        
        if (confirm != JOptionPane.YES_OPTION) return;
        
        try {
            String dbPath = Database.getDatabaseFile();
            File dbFile = new File(dbPath);
            
            if (dbFile.exists()) {
                // Add a custom header to the database
                try (RandomAccessFile raf = new RandomAccessFile(dbFile, "rw")) {
                    byte[] header = "GRATISPOS_ENCRYPTED_DB".getBytes();
                    raf.seek(0);
                    raf.write(header);
                }
            }
            
            // Set flag in database
            try (Connection conn = Database.getConnection();
                 PreparedStatement stmt = conn.prepareStatement(
                     "INSERT OR REPLACE INTO app_settings (key, value) VALUES ('custom_header', 'GRATISPOS_ENCRYPTED_DB')")) {
                stmt.executeUpdate();
            }
            
            logActivity("Database made invalid to other apps by: " + loggedInUser);
            showGlassMessage(parent, "Database now has custom protection!\nOther applications cannot read this database.", "Success", "success");
            
        } catch (Exception e) {
            showGlassMessage(parent, "Error: " + e.getMessage(), "Error", "error");
        }
    }

    // Create database backup
    private void createDatabaseBackup(JDialog parent) {
        JFileChooser fileChooser = new JFileChooser();
        fileChooser.setDialogTitle("Create Database Backup");
        fileChooser.setSelectedFile(new File("backup_" + LocalDate.now() + ".db"));
        
        if (fileChooser.showSaveDialog(parent) == JFileChooser.APPROVE_OPTION) {
            try {
                String sourcePath = Database.getDatabaseFile();
                File source = new File(sourcePath);
                File dest = fileChooser.getSelectedFile();
                
                try (FileInputStream fis = new FileInputStream(source);
                     FileOutputStream fos = new FileOutputStream(dest)) {
                    byte[] buffer = new byte[8192];
                    int bytesRead;
                    while ((bytesRead = fis.read(buffer)) != -1) {
                        fos.write(buffer, 0, bytesRead);
                    }
                }
                
                logActivity("Database backup created by: " + loggedInUser);
                showGlassMessage(parent, "Backup created successfully!\nLocation: " + dest.getAbsolutePath(), "Success", "success");
                
            } catch (IOException e) {
                showGlassMessage(parent, "Error creating backup: " + e.getMessage(), "Error", "error");
            }
        }
    }

    // Restore from backup
    private void restoreFromBackup(JDialog parent) {
        int confirm = JOptionPane.showConfirmDialog(parent,
            "⚠️ WARNING: Restoring from backup will OVERWRITE current data!\nThis action cannot be undone.\nContinue?",
            "Confirm Restore", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        
        if (confirm != JOptionPane.YES_OPTION) return;
        
        JFileChooser fileChooser = new JFileChooser();
        fileChooser.setDialogTitle("Select Backup File");
        
        if (fileChooser.showOpenDialog(parent) == JFileChooser.APPROVE_OPTION) {
            try {
                File backup = fileChooser.getSelectedFile();
                String targetPath = Database.getDatabaseFile();
                File target = new File(targetPath);
                
                // Close existing connections
                Database.shutdownConnection();
                
                // Copy backup to target
                try (FileInputStream fis = new FileInputStream(backup);
                     FileOutputStream fos = new FileOutputStream(target)) {
                    byte[] buffer = new byte[8192];
                    int bytesRead;
                    while ((bytesRead = fis.read(buffer)) != -1) {
                        fos.write(buffer, 0, bytesRead);
                    }
                }
                
                logActivity("Database restored from backup by: " + loggedInUser);
                showGlassMessage(parent, "Database restored successfully!\nPlease restart the application.", "Success", "success");
                
                System.exit(0);
                
            } catch (IOException e) {
                showGlassMessage(parent, "Error restoring backup: " + e.getMessage(), "Error", "error");
            }
        }
    }

    // View security logs
    private void viewSecurityLogs(JDialog parent) {
        JDialog logDialog = new JDialog(parent, "Security Logs", true);
        logDialog.setSize(800, 500);
        logDialog.setLocationRelativeTo(parent);
        logDialog.setUndecorated(true);
        logDialog.setBackground(new Color(0, 0, 0, 0));
        
        JPanel glass = new JPanel() {
            @Override protected void paintComponent(Graphics g) {
                Graphics2D g2 = (Graphics2D) g.create();
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setColor(new Color(10, 12, 18));
                g2.fillRoundRect(0, 0, getWidth(), getHeight(), 20, 20);
                g2.setColor(new Color(52, 152, 219, 160));
                g2.setStroke(new BasicStroke(1.5f));
                g2.drawRoundRect(1, 1, getWidth()-3, getHeight()-3, 20, 20);
                g2.dispose();
            }
        };
        glass.setLayout(new BorderLayout());
        glass.setBorder(new EmptyBorder(15, 15, 15, 15));
        
        JLabel title = new JLabel("Security Audit Log");
        title.setFont(new Font("Segoe UI", Font.BOLD, 18));
        title.setForeground(new Color(52, 152, 219));
        title.setHorizontalAlignment(SwingConstants.CENTER);
        
        JTextArea logArea = new JTextArea();
        logArea.setEditable(false);
        logArea.setFont(new Font("Monospaced", Font.PLAIN, 12));
        logArea.setBackground(new Color(22, 28, 38));
        logArea.setForeground(Color.WHITE);
        logArea.setMargin(new Insets(15, 15, 15, 15));
        
        // Load logs from database
        StringBuilder logs = new StringBuilder();
        logs.append("SECURITY AUDIT LOG\n");
        logs.append("=".repeat(60)).append("\n\n");
        
        try (Connection conn = Database.getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(
                 "SELECT timestamp, username, action FROM activity_log WHERE action LIKE '%Security%' OR action LIKE '%Password%' OR action LIKE '%Lock%' ORDER BY timestamp DESC LIMIT 100")) {
            
            while (rs.next()) {
                logs.append(String.format("%s | %-20s | %s\n", 
                    rs.getString("timestamp"), 
                    rs.getString("username"),
                    rs.getString("action")));
            }
        } catch (SQLException e) {
            logs.append("Error loading logs: ").append(e.getMessage());
        }
        
        logArea.setText(logs.toString());
        
        JButton closeBtn = createSmallButton("Close", new Color(149, 165, 166));
        closeBtn.addActionListener(e -> logDialog.dispose());
        
        JPanel btnPanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
        btnPanel.setOpaque(false);
        btnPanel.add(closeBtn);
        
        glass.add(title, BorderLayout.NORTH);
        glass.add(new JScrollPane(logArea), BorderLayout.CENTER);
        glass.add(btnPanel, BorderLayout.SOUTH);
        
        logDialog.setContentPane(glass);
        logDialog.setVisible(true);
    }

    // Clear security logs
    private void clearSecurityLogs(JDialog parent) {
        int confirm = JOptionPane.showConfirmDialog(parent,
            "Clear all security logs?\nThis action cannot be undone!",
            "Confirm Clear", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE);
        
        if (confirm != JOptionPane.YES_OPTION) return;
        
        try (Connection conn = Database.getConnection();
             Statement stmt = conn.createStatement()) {
            stmt.executeUpdate("DELETE FROM activity_log WHERE action LIKE '%Security%' OR action LIKE '%Password%' OR action LIKE '%Lock%'");
            
            logActivity("Security logs cleared by: " + loggedInUser);
            showGlassMessage(parent, "Security logs cleared successfully!", "Success", "success");
            
        } catch (SQLException e) {
            showGlassMessage(parent, "Error clearing logs: " + e.getMessage(), "Error", "error");
        }
    }

