    // Load security settings
    private Properties loadSecuritySettings() {
        Properties props = new Properties();
        File configDir = new File(System.getProperty("user.home"), ".gratispos");
        File configFile = new File(configDir, "security.properties");
        
        if (configFile.exists()) {
            try (FileInputStream fis = new FileInputStream(configFile)) {
                props.load(fis);
            } catch (IOException e) {
                // Use defaults
            }
        }
        return props;
    }

    // Save password settings
    private void savePasswordSettings(int minLen, boolean requireUpper, boolean requireLower, 
                                       boolean requireNumber, boolean requireSpecial, int expiryDays) {
        Properties props = loadSecuritySettings();
        props.setProperty("password.minLength", String.valueOf(minLen));
        props.setProperty("password.requireUpper", String.valueOf(requireUpper));
        props.setProperty("password.requireLower", String.valueOf(requireLower));
        props.setProperty("password.requireNumber", String.valueOf(requireNumber));
        props.setProperty("password.requireSpecial", String.valueOf(requireSpecial));
        props.setProperty("password.expiryDays", String.valueOf(expiryDays));
        
        File configDir = new File(System.getProperty("user.home"), ".gratispos");
        if (!configDir.exists()) configDir.mkdirs();
        
        try (FileOutputStream fos = new FileOutputStream(new File(configDir, "security.properties"))) {
            props.store(fos, "Security Settings");
        } catch (IOException e) {
            LOGGER.log(Level.WARNING, "Failed to save password settings", e);
        }
    }

    // Save session settings
    private void saveSessionSettings(int sessionTimeout, int maxAttempts, int lockoutMins) {
        Properties props = loadSecuritySettings();
        props.setProperty("session.timeout", String.valueOf(sessionTimeout));
        props.setProperty("login.maxAttempts", String.valueOf(maxAttempts));
        props.setProperty("login.lockoutMinutes", String.valueOf(lockoutMins));
        
        File configDir = new File(System.getProperty("user.home"), ".gratispos");
        if (!configDir.exists()) configDir.mkdirs();
        
        try (FileOutputStream fos = new FileOutputStream(new File(configDir, "security.properties"))) {
            props.store(fos, "Security Settings");
        } catch (IOException e) {
            LOGGER.log(Level.WARNING, "Failed to save session settings", e);
        }
    }

