        JLabel roleValueLabel = new JLabel("-");
        roleValueLabel.setFont(new Font("Segoe UI", Font.PLAIN, 12));
        
        selectPanel.add(new JLabel("User:"));
        selectPanel.add(userCombo);
        selectPanel.add(Box.createHorizontalStrut(20));
        selectPanel.add(roleLabel);
        selectPanel.add(roleValueLabel);
        
        mainPanel.add(selectPanel, BorderLayout.NORTH);
        
        // Restrictions panel
        JPanel restrictionsPanel = new JPanel();
        restrictionsPanel.setLayout(new BoxLayout(restrictionsPanel, BoxLayout.Y_AXIS));
        restrictionsPanel.setBorder(BorderFactory.createTitledBorder("Restricted Features (Checked = User CANNOT access)"));
        
        // Feature categories
        JPanel navPanel = new JPanel(new GridLayout(0, 2, 10, 5));
        navPanel.setBorder(BorderFactory.createTitledBorder("Navigation Menu"));
        JCheckBox adminRestrict = new JCheckBox("Admin Panel");
        JCheckBox securityRestrict = new JCheckBox("Security");
        JCheckBox backupRestrict = new JCheckBox("Backup");
        JCheckBox logsRestrict = new JCheckBox("Logs");
        JCheckBox manualFixRestrict = new JCheckBox("Manual-Fix");
        navPanel.add(adminRestrict);
        navPanel.add(securityRestrict);
        navPanel.add(backupRestrict);
        navPanel.add(logsRestrict);
        navPanel.add(manualFixRestrict);
        
        JPanel productPanel = new JPanel(new GridLayout(0, 2, 10, 5));
        productPanel.setBorder(BorderFactory.createTitledBorder("Product Management"));
        JCheckBox createCategoryRestrict = new JCheckBox("Create Category");
        JCheckBox createProductRestrict = new JCheckBox("Create Product");
        JCheckBox receiveProductRestrict = new JCheckBox("Receive Product");
