        JCheckBox inventoryRestrict = new JCheckBox("Inventory");
        JCheckBox ledgerRestrict = new JCheckBox("Ledger");
        JCheckBox belowStockRestrict = new JCheckBox("Below Stock");
        JCheckBox medicineInfoRestrict = new JCheckBox("Wholesale Panel");
        inventoryPanel.add(stockValueRestrict);
        inventoryPanel.add(expiredItemRestrict);
        inventoryPanel.add(inventoryRestrict);
        inventoryPanel.add(ledgerRestrict);
        inventoryPanel.add(belowStockRestrict);
        inventoryPanel.add(medicineInfoRestrict);
        
        JPanel extraPanel = new JPanel(new GridLayout(0, 2, 10, 5));
        extraPanel.setBorder(BorderFactory.createTitledBorder("Additional Features"));
        JCheckBox notificationRestrict = new JCheckBox("Notification");
