private boolean checkIfUserBlocked(String username) {
    try {
        String sql = "SELECT account_status FROM users WHERE username = ?";
        try (Connection conn = Database.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, username);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                String status = rs.getString("account_status");
                return "BLOCKED".equals(status);
            }
        }
        // Also check cloud
        if (Database.checkTursoConnection()) {
            List<JsonObject> result = SQLiteCloudClient.execute(
                "SELECT account_status FROM users WHERE username = ?", username);
            if (!result.isEmpty() && result.get(0).has("account_status")) {
                return "BLOCKED".equals(result.get(0).get("account_status").getAsString());
            }
        }
    } catch (Exception e) {
        LOGGER.log(Level.WARNING, "Error checking block status", e);
    }
    return false;
}

private void blockUser(String username, JDialog parentDialog) {
    try {
        // Update local database
        String sql = "UPDATE users SET account_status = 'BLOCKED', locked = 1, lock_reason = 'Blocked by admin' WHERE username = ?";
        try (Connection conn = Database.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, username);
            stmt.executeUpdate();
        }
        
        // Update cloud if online
        if (Database.checkTursoConnection()) {
            SQLiteCloudClient.execute(
                "UPDATE users SET account_status = 'BLOCKED', locked = 1, lock_reason = 'Blocked by admin' WHERE username = ?",
                username);
        }
        
        // Log the action
        logActivity("User blocked: " + username + " by " + loggedInUser);
        
        showGlassMessage(parentDialog, "User '" + username + "' has been BLOCKED successfully!", "Success", "success");
        parentDialog.dispose();
        
    } catch (Exception e) {
        LOGGER.log(Level.SEVERE, "Error blocking user", e);
        showGlassMessage(parentDialog, "Error blocking user: " + e.getMessage(), "Error", "error");
    }
}

private void unblockUser(String username, JDialog parentDialog) {
    try {
        // Update local database
        String sql = "UPDATE users SET account_status = 'ACTIVE', locked = 0, lock_reason = NULL WHERE username = ?";
        try (Connection conn = Database.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, username);
            stmt.executeUpdate();
        }
        
        // Update cloud if online
        if (Database.checkTursoConnection()) {
            SQLiteCloudClient.execute(
                "UPDATE users SET account_status = 'ACTIVE', locked = 0, lock_reason = NULL WHERE username = ?",
                username);
        }
        
        // Log the action
        logActivity("User unblocked: " + username + " by " + loggedInUser);
        
        showGlassMessage(parentDialog, "User '" + username + "' has been UNBLOCKED successfully!", "Success", "success");
        parentDialog.dispose();
        
    } catch (Exception e) {
        LOGGER.log(Level.SEVERE, "Error unblocking user", e);
        showGlassMessage(parentDialog, "Error unblocking user: " + e.getMessage(), "Error", "error");
    }
}

private void performCompleteUserDeletion(String username, JDialog parentDialog) {
    new Thread(() -> {
        try {
            // 1. Get the email before deleting
            String userEmail = null;
            try (Connection conn = Database.getConnection();
                 PreparedStatement ps = conn.prepareStatement(
                     "SELECT email FROM users WHERE username = ?")) {
                ps.setString(1, username);
                ResultSet rs = ps.executeQuery();
                if (rs.next()) userEmail = rs.getString("email");
            } catch (SQLException ignored) {}

            // 2. Delete from local DB (cascade-style: related records first)
            try (Connection conn = Database.getConnection()) {
                conn.setAutoCommit(false);
                // Remove from users table only — we keep their sales history intact
                try (PreparedStatement ps = conn.prepareStatement(
                        "DELETE FROM users WHERE username = ?")) {
                    ps.setString(1, username);
                    ps.executeUpdate();
                }
                conn.commit();
            } catch (SQLException e) {
                LOGGER.severe("Local user deletion failed: " + e.getMessage());
                SwingUtilities.invokeLater(() ->
                    showGlassMessage(parentDialog, "Error: " + e.getMessage(), "Error", "error"));
                return;
            }

            // 3. Delete from LocalUserStore
            try {
                LocalUserStore store = LocalUserStore.getInstance();
                store.removeUser(username);
                if (userEmail != null) store.removeUser(userEmail);
                store.saveUsers();
            } catch (Exception e) {
                LOGGER.warning("LocalUserStore removal: " + e.getMessage());
            }

            // 4. Delete from cloud
            if (SQLiteCloudClient.checkConnection()) {
                try {
                    SQLiteCloudClient.executeUpdate(
                        "DELETE FROM users WHERE username = ? AND client_id = ?",
                        username, SQLiteCloudClient.getCurrentClientId());
                    if (userEmail != null) {
                        SQLiteCloudClient.executeUpdate(
                            "DELETE FROM users WHERE email = ? AND client_id = ?",
                            userEmail, SQLiteCloudClient.getCurrentClientId());
                    }
                    LOGGER.info("User deleted from cloud: " + username);
                } catch (Exception e) {
                    LOGGER.warning("Cloud deletion failed: " + e.getMessage());
                }
            }

            // 5. Remove saved email
            if (userEmail != null) removeSavedEmail(userEmail);

            logActivity("User permanently deleted: " + username + " by " + loggedInUser);

            SwingUtilities.invokeLater(() -> {
                showGlassMessage(parentDialog,
                    "User '" + username + "' deleted from all sources.",
                    "Deletion Successful", "success");
                parentDialog.dispose();
            });

        } catch (Exception e) {
            LOGGER.severe("performCompleteUserDeletion failed: " + e.getMessage());
            SwingUtilities.invokeLater(() ->
                showGlassMessage(parentDialog, "Error: " + e.getMessage(), "Error", "error"));
        }
    }, "delete-user-" + username).start();
}

private void removeSavedEmail(String username) {
    try {
        // Get email for this username
        String email = null;
        try (Connection conn = Database.getConnection();
             PreparedStatement stmt = conn.prepareStatement("SELECT email FROM users WHERE username = ?")) {
            stmt.setString(1, username);
            ResultSet rs = stmt.executeQuery();
            if (rs.next()) {
                email = rs.getString("email");
            }
        }
        
        if (email != null) {
            String savedEmailsFile = System.getProperty("user.home") + File.separator + ".gratispos" + File.separator + "saved_emails.txt";
            File file = new File(savedEmailsFile);
            if (file.exists()) {
                List<String> emails = new ArrayList<>();
                try (BufferedReader br = new BufferedReader(new FileReader(file))) {
                    String line;
                    while ((line = br.readLine()) != null) {
                        if (!line.trim().equals(email)) {
                            emails.add(line.trim());
                        }
                    }
                }
                try (PrintWriter pw = new PrintWriter(new FileWriter(file))) {
                    for (String e : emails) {
                        pw.println(e);
                    }
                }
            }
        }
    } catch (Exception e) {
        LOGGER.log(Level.WARNING, "Error removing saved email", e);
    }
}

