private JPanel createDataCategoryPanel(String title, String description, Map<String, JCheckBox> checkboxMap, String tableName) {
    JPanel panel = new JPanel(new BorderLayout(10, 5));
    panel.setOpaque(false);
    panel.setBorder(BorderFactory.createCompoundBorder(
        BorderFactory.createLineBorder(new Color(100, 100, 100), 1),
        BorderFactory.createEmptyBorder(12, 15, 12, 15)
    ));
    
    JCheckBox checkbox = new JCheckBox(title);
    checkbox.setFont(new Font("Segoe UI", Font.BOLD, 14));
    checkbox.setForeground(Color.WHITE);
    checkbox.setOpaque(false);
    
    JLabel countLabel = new JLabel();
    countLabel.setForeground(new Color(180, 180, 180));
    try {
        int count = getRecordCount(tableName);
        countLabel.setText(count + " records");
        if (count == 0) checkbox.setEnabled(false);
    } catch (SQLException ex) {
        countLabel.setText("Error");
    }
    
    panel.add(checkbox, BorderLayout.WEST);
    panel.add(countLabel, BorderLayout.EAST);
    checkboxMap.put(tableName, checkbox);
    
    return panel;
}

    private int getRecordCount(String tableName) throws SQLException {
    String sql = "users".equals(tableName) 
        ? "SELECT COUNT(*) FROM users WHERE username != ?" 
        : "SELECT COUNT(*) FROM " + tableName;
    
    try (Connection conn = Database.getConnection();
         PreparedStatement stmt = conn.prepareStatement(sql)) {
        if ("users".equals(tableName)) stmt.setString(1, loggedInUser);
        ResultSet rs = stmt.executeQuery();
        return rs.next() ? rs.getInt(1) : 0;
    }
}
    private void performDataErase(List<String> tablesToErase, JDialog parentDialog) {
        JDialog confirmDialog = new JDialog(parentDialog, "Confirm Data Deletion", true);
        confirmDialog.setSize(450, 280);
        confirmDialog.setLocationRelativeTo(parentDialog);
        confirmDialog.setUndecorated(true);
        confirmDialog.setBackground(new Color(0, 0, 0, 0));
        
        JPanel glassPanel = new JPanel() {
            @Override
            protected void paintComponent(Graphics g) {
                Graphics2D g2d = (Graphics2D) g.create();
                g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2d.setColor(new Color(33, 37, 41, 240));
                g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 20, 20);
                g2d.setColor(new Color(231, 76, 60, 100));
                g2d.setStroke(new BasicStroke(2));
                g2d.drawRoundRect(1, 1, getWidth() - 3, getHeight() - 3, 20, 20);
                g2d.dispose();
            }
        };
        glassPanel.setLayout(new GridBagLayout());
        glassPanel.setBorder(new EmptyBorder(20, 20, 20, 20));
        
        GridBagConstraints gbc = new GridBagConstraints();
        gbc.insets = new Insets(10, 10, 10, 10);
        
        JLabel iconLabel = new JLabel("⚠️");
        iconLabel.setFont(new Font("Segoe UI Emoji", Font.PLAIN, 48));
        gbc.gridx = 0; gbc.gridy = 0;
        glassPanel.add(iconLabel, gbc);
        
        JLabel warningLabel = new JLabel("<html><center><b style='color:#e74c3c'>WARNING!</b><br/>" +
            "This will permanently delete selected data!<br/>" +
            "This action CANNOT be undone!</center></html>");
        warningLabel.setFont(new Font("Segoe UI", Font.PLAIN, 13));
        warningLabel.setForeground(Color.WHITE);
        gbc.gridy = 1;
        glassPanel.add(warningLabel, gbc);
        
        JPanel buttonPanel = new JPanel(new FlowLayout(FlowLayout.CENTER, 15, 5));
        buttonPanel.setOpaque(false);
        
        JButton confirmBtn = createGlassButton("Yes, Delete", new Color(231, 76, 60));
        JButton cancelBtn = createGlassButton("Cancel", new Color(149, 165, 166));
        
        confirmBtn.addActionListener(e -> {
            confirmDialog.dispose();
            performDataErase(tablesToErase, parentDialog);
        });
        cancelBtn.addActionListener(e -> confirmDialog.dispose());
        
        buttonPanel.add(confirmBtn);
        buttonPanel.add(cancelBtn);
        gbc.gridy = 2;
        glassPanel.add(buttonPanel, gbc);
        
        confirmDialog.setContentPane(glassPanel);
        confirmDialog.setVisible(true);
    }

