    private void showHistoricalAuditReport(String date) {
    JDialog dialog = new JDialog(this, "📊 Audit Report - " + date, false);
    dialog.setSize(900, 600);
    dialog.setLocationRelativeTo(this);
    dialog.setUndecorated(true);
    dialog.setBackground(new Color(0, 0, 0, 0));
    dialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);

    JPanel glassPanel = new JPanel() {
        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2d = (Graphics2D) g.create();
            g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2d.setColor(new Color(18, 20, 24, 245));
            g2d.fillRoundRect(0, 0, getWidth(), getHeight(), 24, 24);
            g2d.setColor(new Color(255, 255, 255, 22));
            g2d.setStroke(new BasicStroke(1.2f));
            g2d.drawRoundRect(1, 1, getWidth() - 3, getHeight() - 3, 24, 24);
            g2d.dispose();
        }
    };

    glassPanel.setLayout(new BorderLayout(10, 10));
    glassPanel.setBorder(new EmptyBorder(12, 12, 12, 12));

    JPanel header = new JPanel(new BorderLayout());
    header.setOpaque(false);
    header.setBorder(new EmptyBorder(8, 10, 8, 10));

    JLabel titleLabel = new JLabel("📊 Audit Report - " + date);
    titleLabel.setFont(new Font("Segoe UI", Font.BOLD, 18));
    titleLabel.setForeground(new Color(52, 144, 220));

    JButton closeTopBtn = new JButton("✕");
    closeTopBtn.setFont(new Font("Segoe UI", Font.BOLD, 14));
    closeTopBtn.setForeground(Color.WHITE);
    closeTopBtn.setBackground(new Color(40, 40, 40));
    closeTopBtn.setFocusPainted(false);
    closeTopBtn.setBorder(BorderFactory.createEmptyBorder(5, 10, 5, 10));
    closeTopBtn.setCursor(new Cursor(Cursor.HAND_CURSOR));
    closeTopBtn.addActionListener(e -> dialog.dispose());

    JPanel right = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
    right.setOpaque(false);
    right.add(closeTopBtn);

    header.add(titleLabel, BorderLayout.WEST);
    header.add(right, BorderLayout.EAST);

    glassPanel.add(header, BorderLayout.NORTH);

    String[] columns = {"SN", "Product", "Selling Price", "Audit", "Quantity", "Subtotal", "Audited By"};
    DefaultTableModel reportModel = new DefaultTableModel(columns, 0) {
        @Override public boolean isCellEditable(int r, int c) { return false; }
    };

    double totalLoss = 0;

    try (Connection conn = Database.getConnection();
         PreparedStatement ps = conn.prepareStatement(
             "SELECT product_name, selling_price, audit_status, quantity, subtotal, audited_by " +
             "FROM audit_log WHERE audit_date = ? ORDER BY id"
         )) {

        ps.setString(1, date);
        ResultSet rs = ps.executeQuery();

        int sn = 1;
        while (rs.next()) {
            String status = rs.getString("audit_status");
            double subtotal = rs.getDouble("subtotal");

            if ("Loss".equals(status)) totalLoss += subtotal;

            reportModel.addRow(new Object[]{
                sn++,
                rs.getString("product_name"),
                rs.getDouble("selling_price"),
                status,
                rs.getInt("quantity"),
                subtotal,
                rs.getString("audited_by")
            });
        }

    } catch (SQLException e) {
        showGlassErrorDialog(dialog, "Error loading audit data: " + e.getMessage());
        return;
    }

    if (reportModel.getRowCount() == 0) {
        showGlassMessage(dialog, "No audit data found for " + date, "No Data", "warning");
        dialog.dispose();
        return;
    }

    JTable table = new JTable(reportModel) {
        @Override
        public Component prepareRenderer(TableCellRenderer r, int row, int col) {
            Component c = super.prepareRenderer(r, row, col);

            if (!isRowSelected(row)) {
                c.setBackground(row % 2 == 0 ? new Color(42, 46, 52) : new Color(50, 54, 60));
                c.setForeground(Color.WHITE);
            } else {
                c.setBackground(new Color(52, 152, 219, 80));
                c.setForeground(Color.WHITE);
            }

            if (col == 3) {
                String status = (String) getValueAt(row, col);
                if ("Loss".equals(status)) c.setForeground(new Color(231, 76, 60));
                else if ("Balanced".equals(status) || "Re-Stocked".equals(status))
                    c.setForeground(new Color(46, 204, 113));
            }

            return c;
        }
    };

    table.setRowHeight(28);
    table.setFont(new Font("Segoe UI", Font.PLAIN, 13));
    table.setForeground(Color.WHITE);
    table.setBackground(new Color(45, 50, 55));
    table.setGridColor(new Color(80, 80, 80));

    JScrollPane scroll = new JScrollPane(table);
    scroll.setOpaque(false);
    scroll.getViewport().setOpaque(false);
    scroll.setBorder(BorderFactory.createLineBorder(new Color(90, 90, 90)));

    glassPanel.add(scroll, BorderLayout.CENTER);

    JLabel totalLabel = new JLabel("Total Loss: TSh " + String.format("%,.2f", totalLoss));
    totalLabel.setFont(new Font("Segoe UI", Font.BOLD, 15));
    totalLabel.setForeground(new Color(231, 76, 60));

    JButton closeBtn = createGlassButton("✕ Close", new Color(120, 120, 120));
    closeBtn.addActionListener(e -> dialog.dispose());

    JPanel bottom = new JPanel(new BorderLayout());
    bottom.setOpaque(false);
    bottom.setBorder(new EmptyBorder(10, 10, 10, 10));

    JPanel actions = new JPanel(new FlowLayout(FlowLayout.CENTER));
    actions.setOpaque(false);
    actions.add(closeBtn);

    bottom.add(totalLabel, BorderLayout.NORTH);
    bottom.add(actions, BorderLayout.CENTER);

    glassPanel.add(bottom, BorderLayout.SOUTH);

    dialog.setContentPane(glassPanel);
    dialog.setVisible(true);
}

