    private void logInventoryAction(Connection conn, int productId, String action, int quantityChange) throws SQLException {
    try (PreparedStatement stmt = conn.prepareStatement(
        "INSERT INTO inventory_log (product_id, action, quantity, date, previous_quantity, user) " +
        "VALUES (?, ?, ?, datetime('now'), ?, ?)")) {

        int previousQty = 0;

        try (PreparedStatement pStmt = conn.prepareStatement(
            "SELECT quantity FROM products WHERE id = ?")) {
            pStmt.setInt(1, productId);
            try (ResultSet rs = pStmt.executeQuery()) {
                if (rs.next()) {
                    previousQty = rs.getInt(1);
                }
            }
        }

        stmt.setInt(1, productId);
        stmt.setString(2, action);
        stmt.setInt(3, quantityChange);
        stmt.setInt(4, previousQty);
        stmt.setString(5, loggedInUser);

        stmt.executeUpdate();
    }
}

