// Message class
private static class Message {
    String id;
    String fromUser;
    String toUser;
    String toHierarchy;
    String subject;
    String content;
    String timestamp;
    boolean isRead;
    String parentMessageId;
    
    Message(String id, String fromUser, String toUser, String toHierarchy, 
            String subject, String content, String timestamp, boolean isRead, String parentMessageId) {
        this.id = id;
        this.fromUser = fromUser;
        this.toUser = toUser;
        this.toHierarchy = toHierarchy;
        this.subject = subject;
        this.content = content;
        this.timestamp = timestamp;
        this.isRead = isRead;
        this.parentMessageId = parentMessageId;
    }
}

// Hierarchy levels
private enum HierarchyLevel {
    TOP(0, "Top (CEO/Owner/SuperAdmin)"),
    HIGH(1, "High (Admin/Manager/Director)"),
    MID(2, "Mid (Supervisor/Cashier/Employee)"),
    LOW(3, "Low (User/Viewer)");
    
    int level;
    String display;
    HierarchyLevel(int level, String display) { this.level = level; this.display = display; }
}

// Get user's hierarchy level
private HierarchyLevel getUserHierarchyLevel(String role) {
    if (role == null) return HierarchyLevel.LOW;
    switch (role.toUpperCase()) {
        case "CEO": case "OWNER": case "SUPERADMIN":
            return HierarchyLevel.TOP;
        case "ADMIN": case "MANAGER": case "DIRECTOR":
            return HierarchyLevel.HIGH;
        case "SUPERVISOR": case "CASHIER": case "EMPLOYEE":
            return HierarchyLevel.MID;
        default:
            return HierarchyLevel.LOW;
    }
}

// Get all users in a hierarchy level
private List<String> getUsersByHierarchy(HierarchyLevel level) {
    List<String> users = new ArrayList<>();
    try (Connection conn = Database.getConnection();
         PreparedStatement pst = conn.prepareStatement("SELECT username, privileges FROM users WHERE username != ?")) {
        pst.setString(1, loggedInUser);
        ResultSet rs = pst.executeQuery();
        while (rs.next()) {
            String user = rs.getString("username");
            String role = rs.getString("privileges");
            if (getUserHierarchyLevel(role) == level) {
                users.add(user);
            }
        }
    } catch (SQLException e) {
        LOGGER.log(Level.WARNING, "Failed to get users by hierarchy", e);
    }
    return users;
}
