// Helper method to get username from email
private String getUsernameFromEmail(String email) {
    if (email == null) return "Unknown";
    try (Connection conn = Database.getConnection();
         PreparedStatement ps = conn.prepareStatement("SELECT username FROM users WHERE email = ?")) {
        ps.setString(1, email);
        ResultSet rs = ps.executeQuery();
        if (rs.next()) {
            return rs.getString("username");
        }
    } catch (SQLException e) {
        LOGGER.log(Level.WARNING, "getUsernameFromEmail", e);
    }
    return email.split("@")[0];
}

// Helper method to get email from username
private String getEmailFromUsername(String username) {
    if (username == null) return null;
    try (Connection conn = Database.getConnection();
         PreparedStatement ps = conn.prepareStatement("SELECT email FROM users WHERE username = ?")) {
        ps.setString(1, username);
        ResultSet rs = ps.executeQuery();
        if (rs.next()) {
            return rs.getString("email");
        }
    } catch (SQLException e) {
        LOGGER.log(Level.WARNING, "getEmailFromUsername", e);
    }
    return null;
}
