private JPanel buildMsgBubble2(boolean mine, String sender, String body, String time) {
    JPanel wrapper = new JPanel(new FlowLayout(mine ? FlowLayout.RIGHT : FlowLayout.LEFT, 0, 0));
    wrapper.setOpaque(false);
    wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);
    wrapper.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

    Color bg = mine ? new Color(30, 80, 140, 220) : new Color(38, 44, 56, 230);
    JPanel bubble = new JPanel() {
        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(bg);
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), 14, 14);
            g2.dispose();
        }
    };
    bubble.setLayout(new BoxLayout(bubble, BoxLayout.Y_AXIS));
    bubble.setOpaque(false);
    bubble.setBorder(new EmptyBorder(7, 12, 7, 12));

    if (!mine) {
        JLabel sl = new JLabel(sender);
        sl.setFont(new Font("Segoe UI", Font.BOLD, 11));
        sl.setForeground(new Color(100, 180, 255));
        bubble.add(sl);
        bubble.add(Box.createVerticalStrut(2));
    }

    JLabel bodyLabel = new JLabel("<html><div style='max-width:280px;word-wrap:break-word'>"
        + body.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\n", "<br>")
        + "</div></html>");
    bodyLabel.setFont(new Font("Segoe UI", Font.PLAIN, 13));
    bodyLabel.setForeground(Color.WHITE);
    bubble.add(bodyLabel);

    if (time != null && !time.isEmpty()) {
        bubble.add(Box.createVerticalStrut(3));
        String timeDisplay = time.length() >= 16 ? time.substring(11, 16) : time;
        JLabel tl = new JLabel(timeDisplay);
        tl.setFont(new Font("Segoe UI", Font.PLAIN, 10));
        tl.setForeground(new Color(140, 150, 170));
        bubble.add(tl);
    }

    wrapper.add(bubble);
    return wrapper;
}

// ── Helper: safe get string from JsonObject ──
private String get(JsonObject obj, String key) {
    if (obj == null || !obj.has(key) || obj.get(key).isJsonNull()) return "";
    return obj.get(key).getAsString();
}

