private String getCurrentClientId() {
    String clientId = Database.getCurrentClientId();
    if (clientId == null || clientId.isEmpty()) {
        clientId = this.currentClientId;
    }
    if (clientId == null || clientId.isEmpty()) {
        clientId = loggedInUser;
    }
    return clientId;
}
private void addChatBubble(JPanel chatArea, String sender, String message, boolean isAdmin, Color bubbleColor) {
    JPanel row = new JPanel(new FlowLayout(isAdmin ? FlowLayout.RIGHT : FlowLayout.LEFT, 8, 4));
    row.setOpaque(false);
    row.setAlignmentX(Component.LEFT_ALIGNMENT);
    row.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));

    JPanel bubble = new JPanel() {
        @Override
        protected void paintComponent(Graphics g) {
            Graphics2D g2 = (Graphics2D) g.create();
            g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g2.setColor(bubbleColor);
            g2.fillRoundRect(0, 0, getWidth(), getHeight(), 14, 14);
            g2.dispose();
        }
    };
    bubble.setLayout(new BoxLayout(bubble, BoxLayout.Y_AXIS));
    bubble.setOpaque(false);
    bubble.setBorder(new EmptyBorder(8, 12, 8, 12));

    JLabel senderLbl = new JLabel(sender);
    senderLbl.setFont(new Font("Segoe UI", Font.BOLD, 10));
    senderLbl.setForeground(new Color(180, 220, 180));

    JLabel msgLbl = new JLabel("<html><body style='width:260px'>" +
        message.replace("<", "&lt;").replace(">", "&gt;") + "</body></html>");
    msgLbl.setFont(new Font("Segoe UI", Font.PLAIN, 13));
    msgLbl.setForeground(Color.WHITE);

    String time = java.time.LocalTime.now().format(
        java.time.format.DateTimeFormatter.ofPattern("HH:mm"));
    JLabel timeLbl = new JLabel(time);
    timeLbl.setFont(new Font("Segoe UI", Font.PLAIN, 9));
    timeLbl.setForeground(new Color(140, 160, 140));
    timeLbl.setAlignmentX(Component.RIGHT_ALIGNMENT);

    bubble.add(senderLbl);
    bubble.add(Box.createVerticalStrut(3));
    bubble.add(msgLbl);
    bubble.add(Box.createVerticalStrut(2));
    bubble.add(timeLbl);

    row.add(bubble);
    chatArea.add(row);
}


 
