private boolean isInternetAvailable() {
    try {
        HttpURLConnection connection = (HttpURLConnection)
            new URL("https://www.google.com").openConnection();
        connection.setRequestMethod("HEAD");
        connection.setConnectTimeout(3000);
        connection.connect();
        return (200 <= connection.getResponseCode() && connection.getResponseCode() <= 399);
    } catch (Exception e) {
        return false;
    }
}

private boolean isRestricted(String action) {
    Set<String> restrictions = userRestrictions.getOrDefault(loggedInUser, new HashSet<>());
    return restrictions.contains(action);
}

    private ActionListener createNavigationActionListener(String action) {
        return e -> {
            if (isRestricted(action)) {
                JOptionPane.showMessageDialog(this, "🚫 Authorized user Only", "Access Denied", JOptionPane.WARNING_MESSAGE);
                return;
            }
            switch (action) {
                case "Admin":
                    openAdminPanel();
                    break;
                case "Manual-Fix":
                    openDashboard();
                    break;
                case "Logs":
                    showInventoryLogs();
                    break;
                case "Security":
                    showStaffLedger();
                    break;
                case "Help":
                    openHelpDialog();
                    break;
                case "Notification":
                    showNotification();
                    break;
                case "Backup":
                    showBackupDialog();
                    break;
                case "Notebook":
                    showNote();
                    break;
                case "Send Report":
                    showMessageBox();
                    break;
                case "Download":
                    showDownloadSyncDialog();
                    break;
                case "Sign Out":
    logAuditEvent("LOGOUT", "User " + loggedInUser + " signed out", "SUCCESS");
    signOut();
    break;
                default:
                    JOptionPane.showMessageDialog(this, action + " feature not implemented yet.");
            }
        };
    }
    
