private void performSync(JDialog parent, JProgressBar progress, JLabel status, String type) {
    SwingWorker<Boolean, String> worker = new SwingWorker<Boolean, String>() {
        @Override
        protected Boolean doInBackground() throws Exception {
            publish("Checking cloud connection...");
            boolean connected = SQLiteCloudClient.checkConnection();
            if (!connected) {
                publish("❌ No internet connection");
                return false;
            }
            
            String email = loggedInUser + "@local.local";
            if (email == null) {
                publish("❌ User not logged in");
                return false;
            }
            
            String clientId = SQLiteCloudClient.fetchClientIdForUser(email);
            if (clientId == null) {
                publish("❌ No cloud account found");
                return false;
            }
            
            SQLiteCloudClient.setCurrentUser(email, loggedInUser, clientId);
            
            String dbPath = System.getProperty("user.home") + File.separator + ".gratispos" + 
                           File.separator + "local_" + loggedInUser + ".db";
            SQLiteCloudClient.initLocalConnection(dbPath);
            
            publish(10, "Connected to cloud...");
            
            boolean success = false;
            
            switch (type) {
                case "pull":
                    publish(30, "Pulling data from cloud...");
                    success = SQLiteCloudClient.pullFromCloud();
                    break;
                case "push":
                    publish(30, "Pushing local data to cloud...");
                    success = SQLiteCloudClient.fullSync();
                    break;
                case "full":
                    publish(30, "Pulling from cloud...");
                    SQLiteCloudClient.pullFromCloud();
                    publish(60, "Pushing to cloud...");
                    success = SQLiteCloudClient.fullSync();
                    break;
            }
            
            if (success) {
                publish(100, "✅ Sync completed successfully!");
                loadProductsData();
            } else {
                publish(0, "❌ Sync failed");
            }
            
            return success;
        }
        
        @Override
        protected void process(java.util.List<String> chunks) {
            String last = chunks.get(chunks.size() - 1);
            if (last.contains("%")) {
                String[] parts = last.split(",");
                if (parts.length == 2) {
                    progress.setValue(Integer.parseInt(parts[0]));
                    status.setText(parts[1]);
                } else {
                    status.setText(last);
                }
            } else {
                status.setText(last);
            }
        }
        
        private void publish(int percent, String msg) {
            publish(percent + "," + msg);
        }
        
        @Override
        protected void done() {
            try {
                if (get()) {
                    progress.setForeground(new Color(46, 204, 113));
                    Timer timer = new Timer(2000, e -> parent.dispose());
                    timer.setRepeats(false);
                    timer.start();
                } else {
                    progress.setForeground(Color.RED);
                }
            } catch (Exception ex) {
                status.setText("Error: " + ex.getMessage());
                progress.setForeground(Color.RED);
            }
        }
    };
    worker.execute();
}

