    private void signOut() {
    // 1. Thread safety check
    if (!SwingUtilities.isEventDispatchThread()) {
        SwingUtilities.invokeLater(this::signOut);
        return;
    }

    // 2. Initialize Window Base
    final JDialog confirmDialog = new JDialog(this, "Sign Out", true);
    confirmDialog.setUndecorated(true);
    confirmDialog.setDefaultCloseOperation(JDialog.DISPOSE_ON_CLOSE);
    
    // Crucial: Make the frame transparent so our custom glass painting handles the geometry
    confirmDialog.setBackground(new Color(0, 0, 0, 0));

    final java.util.concurrent.atomic.AtomicBoolean signingOut = new java.util.concurrent.atomic.AtomicBoolean(false);

    // 3. CONCEPT 3 MAIN CANVAS PANEL (Custom Painted Glass + Edge Crimson Blur)
    JPanel mainPanel = new JPanel() {
        @Override
        protected void paintComponent(Graphics g) {
            super.paintComponent(g);
            Graphics2D g2 = (Graphics2D) g.create();
            try {
                g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
                g2.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);

                int w = getWidth();
                int h = getHeight();

                // EFFECT A: The Crimson Edge-Lit Ambient Glow (Soft backing shadow)
                // We layer decreasing opacities outwards to simulate a real hardware or engine glow
                for (int i = 0; i < 10; i++) {
                    int alpha = 18 - (i * 2);
                    if (alpha <= 0) break;
                    g2.setColor(new Color(239, 68, 68, alpha)); // Modern vivid red/crimson hex
                    // Focus the glow heavier towards the bottom half to create a grounded illumination look
                    g2.drawRoundRect(i, i, w - (i * 2) - 1, h - (i * 2) - 1, 24, 24);
                }

                // EFFECT B: The Opaque/Frosted Core Glass Layer (65% Opaque Dark Core)
                g2.setPaint(new GradientPaint(
                    0, 0, new Color(28, 30, 36, 175),
                    0, h, new Color(14, 16, 20, 220)
                ));
                g2.fillRoundRect(10, 10, w - 20, h - 20, 22, 22);

                // EFFECT C: Razor-Thin Sharp High-Refraction Frame Rim
                g2.setStroke(new BasicStroke(1.2f));
                g2.setPaint(new GradientPaint(
                    0, 0, new Color(255, 255, 255, 45),   // Crisp bright top lip
                    0, h, new Color(255, 255, 255, 12)   // Faded bottom rim
                ));
                g2.drawRoundRect(10, 10, w - 20, h - 20, 22, 22);
                
            } finally {
                g2.dispose();
            }
        }
    };

    // Layout configuration matching Concept 3's clean geometric balance
    mainPanel.setLayout(new BorderLayout(0, 24));
    mainPanel.setBorder(new javax.swing.border.EmptyBorder(40, 32, 32, 32));
    mainPanel.setOpaque(false);
    mainPanel.setPreferredSize(new Dimension(440, 290)); // Perfect professional aspect ratio

    // 4. MODULE CONTENT LAYOUT
    JPanel contentPanel = new JPanel(new GridBagLayout());
    contentPanel.setOpaque(false);
    GridBagConstraints gbc = new GridBagConstraints();
    gbc.gridx = 0; 
    gbc.gridy = 0;
    gbc.anchor = GridBagConstraints.CENTER;

    // Premium Core Status Icon (Power/Exit Emblem)
    JLabel iconLabel = new JLabel("⏻"); 
    iconLabel.setFont(new Font("Segoe UI", Font.PLAIN, 48));
    iconLabel.setForeground(new Color(248, 113, 113)); // Radiant modern crimson
    contentPanel.add(iconLabel, gbc);

    // Title Row
    gbc.gridy++;
    gbc.insets = new Insets(14, 0, 6, 0);
    JLabel titleLabel = new JLabel("Terminate Session?");
    titleLabel.setFont(new Font("Segoe UI", Font.BOLD, 22));
    titleLabel.setForeground(Color.WHITE);
    contentPanel.add(titleLabel, gbc);

    // Subtitle Explainer
    gbc.gridy++;
    gbc.insets = new Insets(0, 0, 0, 0);
    JLabel subLabel = new JLabel("Are you sure you want to log out of the Gratis Pos console?");
    subLabel.setFont(new Font("Segoe UI", Font.PLAIN, 13));
    subLabel.setForeground(new Color(156, 163, 175)); // Flat UI neutral gray
    contentPanel.add(subLabel, gbc);

    // 5. ASYMMETRIC CONTROL BUTTONS
    JPanel buttonPanel = new JPanel(new GridLayout(1, 2, 16, 0));
    buttonPanel.setOpaque(false);

    // Custom Glass-Matted Cancel Button
    JButton cancelBtn = createModernButton("Keep Browsing", new Color(43, 47, 54), Color.WHITE);
    // Custom Active Solid Crimson Destructive Button
    JButton confirmBtn = createModernButton("Sign Out", new Color(239, 68, 68), Color.WHITE);

    // Fast-Key Keyboard Navigation Mappings
    confirmDialog.getRootPane().setDefaultButton(confirmBtn);
    confirmDialog.getRootPane().registerKeyboardAction(
            e -> confirmDialog.dispose(),
            KeyStroke.getKeyStroke(KeyEvent.VK_ESCAPE, 0),
            JComponent.WHEN_IN_FOCUSED_WINDOW
    );

    cancelBtn.addActionListener(e -> confirmDialog.dispose());
    confirmBtn.addActionListener(e -> {
        if (signingOut.getAndSet(true)) return;

        confirmBtn.setText("Closing Core...");
        confirmBtn.setEnabled(false);
        cancelBtn.setEnabled(false);

        new SwingWorker<Void, Void>() {
            @Override 
            protected Void doInBackground() { return null; }
            @Override 
            protected void done() {
                confirmDialog.dispose();
                completeSignOut(); // Your backend code execution
            }
        }.execute();
    });

    buttonPanel.add(cancelBtn);
    buttonPanel.add(confirmBtn);

    mainPanel.add(contentPanel, BorderLayout.CENTER);
    mainPanel.add(buttonPanel, BorderLayout.SOUTH);

    confirmDialog.setContentPane(mainPanel);
    confirmDialog.pack();
    confirmDialog.setLocationRelativeTo(this);
    confirmDialog.setVisible(true);
}

