    private JSpinner createGlassSpinner(int value) {
        JSpinner spinner = new JSpinner(new SpinnerNumberModel(value, 0, 999999, 1));
        styleGlassSpinner(spinner);
        return spinner;
    }

    private void styleGlassSpinner(JSpinner spinner) {
        spinner.setFont(new Font("Segoe UI", Font.PLAIN, 13));
        spinner.setForeground(Color.WHITE);
        spinner.setBackground(new Color(60, 60, 60));
        JComponent editor = spinner.getEditor();
        if (editor instanceof JSpinner.DefaultEditor) {
            JTextField textField = ((JSpinner.DefaultEditor) editor).getTextField();
            textField.setBackground(new Color(60, 60, 60));
            textField.setForeground(Color.WHITE);
            textField.setCaretColor(Color.WHITE);
            textField.setHorizontalAlignment(JTextField.RIGHT);
        }
    }

