        dashboardDialog.setSize(1400, 800);
        dashboardDialog.setLocationRelativeTo(this);
        dashboardDialog.setDefaultCloseOperation(WindowConstants.DISPOSE_ON_CLOSE);
        
        // Dark background
        JPanel mainContainer = new JPanel(new BorderLayout(10, 10));
        mainContainer.setBackground(new Color(30, 30, 40));
        mainContainer.setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));
        
        // Header
        JPanel headerPanel = new JPanel(new BorderLayout());
        headerPanel.setBackground(new Color(52, 144, 220));
        headerPanel.setBorder(BorderFactory.createEmptyBorder(15, 20, 15, 20));
        
        JLabel titleLabel = new JLabel("📦 Product Management Dashboard");
        titleLabel.setFont(new Font("Segoe UI", Font.BOLD, 22));
