        selectAllBtn.setBackground(new Color(52, 152, 219));
        selectAllBtn.setForeground(Color.WHITE);
        selectAllBtn.setFocusPainted(false);
        
        JButton deselectAllBtn = new JButton("☐ Deselect All");
        deselectAllBtn.setBackground(new Color(52, 152, 219));
        deselectAllBtn.setForeground(Color.WHITE);
        deselectAllBtn.setFocusPainted(false);
        
        JButton bulkPriceBtn = new JButton("💰 Bulk Price Update");
        bulkPriceBtn.setBackground(new Color(52, 152, 219));
        bulkPriceBtn.setForeground(Color.WHITE);
