    // Quick Stock Methods
    private void quickAddStock(int productId, String productName, int currentStock, 
                               JTable table, DefaultTableModel model, JDialog parent) {
        String qtyStr = JOptionPane.showInputDialog(parent, "Add stock for: " + productName + 
                                                      "\nCurrent stock: " + currentStock + 
                                                      "\nEnter quantity to add:");
        if (qtyStr != null) {
            try {
                int qty = Integer.parseInt(qtyStr);
                if (qty > 0) {
                    String sql = "UPDATE products SET stock_quantity = stock_quantity + ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?";
                    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
                        stmt.setInt(1, qty);
                        stmt.setInt(2, productId);
                        stmt.executeUpdate();
                        
                        logStockAdjustment(productId, productName, currentStock, currentStock + qty, qty, "ADD_STOCK");
                        
                        JOptionPane.showMessageDialog(parent, "Added " + qty + " stock to " + productName);
                        refreshTableData(table, model);
                    }
                }
            } catch(NumberFormatException ex) {
                JOptionPane.showMessageDialog(parent, "Invalid quantity");
            } catch(SQLException ex) {
                JOptionPane.showMessageDialog(parent, "Error: " + ex.getMessage());
            }
        }
    }

    private void quickRemoveStock(int productId, String productName, int currentStock, 
                                  JTable table, DefaultTableModel model, JDialog parent) {
        String qtyStr = JOptionPane.showInputDialog(parent, "Remove stock for: " + productName + 
                                                      "\nCurrent stock: " + currentStock + 
                                                      "\nEnter quantity to remove:");
        if (qtyStr != null) {
            try {
                int qty = Integer.parseInt(qtyStr);
                if (qty > 0 && qty <= currentStock) {
                    String sql = "UPDATE products SET stock_quantity = stock_quantity - ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?";
                    try (PreparedStatement stmt = Database.getConnection().prepareStatement(sql)) {
                        stmt.setInt(1, qty);
                        stmt.setInt(2, productId);
                        stmt.executeUpdate();
                        
                        logStockAdjustment(productId, productName, currentStock, currentStock - qty, qty, "REMOVE_STOCK");
                        
                        JOptionPane.showMessageDialog(parent, "Removed " + qty + " stock from " + productName);
                        refreshTableData(table, model);
                    }
                } else {
                    JOptionPane.showMessageDialog(parent, "Invalid quantity or insufficient stock");
                }
            } catch(NumberFormatException ex) {
                JOptionPane.showMessageDialog(parent, "Invalid quantity");
            } catch(SQLException ex) {
                JOptionPane.showMessageDialog(parent, "Error: " + ex.getMessage());
            }
        }
    }

    // Expiry Status Helper
    private String getExpiryStatus(String expireDateStr) {
        if (expireDateStr == null || expireDateStr.isEmpty()) return "⚪ No Date";
        try {
            LocalDate expireDate = LocalDate.parse(expireDateStr);
            LocalDate today = LocalDate.now();
            if (expireDate.isBefore(today)) return "🔴 EXPIRED";
            else if (expireDate.isBefore(today.plusDays(30))) return "🟡 Expiring Soon";
            else return "🟢 Good";
        } catch(Exception e) {
            return "⚪ Invalid";
        }
    }

