    private void addProductToSale(int saleId, int productId, int quantity, double unitPrice) throws SQLException {
        Connection conn = null;
        try {
            conn = Database.getConnection();
            conn.setAutoCommit(false);
            
            String insertSql = "INSERT INTO sale_items (sale_id, product_id, quantity, unit_price, total_price, client_id, user_email) " +
                               "VALUES (?, ?, ?, ?, ?, ?, ?)";
            try (PreparedStatement ps = conn.prepareStatement(insertSql)) {
                ps.setInt(1, saleId);
                ps.setInt(2, productId);
                ps.setInt(3, quantity);
                ps.setDouble(4, unitPrice);
                ps.setDouble(5, quantity * unitPrice);
                ps.setString(6, Database.getCurrentClientId());
                ps.setString(7, Database.getCurrentUserEmail());
                ps.executeUpdate();
            }
            
            String updateStockSql = "UPDATE products SET stock_quantity = stock_quantity - ? WHERE id = ?";
            try (PreparedStatement ps = conn.prepareStatement(updateStockSql)) {
                ps.setInt(1, quantity);
                ps.setInt(2, productId);
                ps.executeUpdate();
            }
            
            recalculateAndUpdateSaleTotal(saleId);
            conn.commit();
        } catch (SQLException e) {
            if (conn != null) conn.rollback();
            throw e;
        } finally {
            if (conn != null) conn.setAutoCommit(true);
        }
    }

    private void removeSaleItem(int itemId, int quantity, double subtotal, int saleId) throws SQLException {
        Connection conn = null;
        try {
            conn = Database.getConnection();
            conn.setAutoCommit(false);
            
            int productId = 0;
            String getProductSql = "SELECT product_id FROM sale_items WHERE id = ?";
            try (PreparedStatement ps = conn.prepareStatement(getProductSql)) {
                ps.setInt(1, itemId);
                ResultSet rs = ps.executeQuery();
                if (rs.next()) {
                    productId = rs.getInt("product_id");
                }
            }
            
            String deleteSql = "DELETE FROM sale_items WHERE id = ?";
            try (PreparedStatement ps = conn.prepareStatement(deleteSql)) {
                ps.setInt(1, itemId);
                ps.executeUpdate();
            }
            
            String restoreStockSql = "UPDATE products SET stock_quantity = stock_quantity + ? WHERE id = ?";
            try (PreparedStatement ps = conn.prepareStatement(restoreStockSql)) {
                ps.setInt(1, quantity);
                ps.setInt(2, productId);
                ps.executeUpdate();
            }
            
            recalculateAndUpdateSaleTotal(saleId);
            conn.commit();
        } catch (SQLException e) {
            if (conn != null) conn.rollback();
            throw e;
        } finally {
            if (conn != null) conn.setAutoCommit(true);
        }
    }

    private void recalculateAndUpdateSaleTotal(int saleId) throws SQLException {
        String sumSql = "SELECT COALESCE(SUM(total_price), 0) as new_total FROM sale_items WHERE sale_id = ?";
        try (PreparedStatement ps = Database.getConnection().prepareStatement(sumSql)) {
            ps.setInt(1, saleId);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                double newTotal = rs.getDouble("new_total");
                String updateSql = "UPDATE sales SET sales_total = ? WHERE id = ?";
                try (PreparedStatement updatePs = Database.getConnection().prepareStatement(updateSql)) {
                    updatePs.setDouble(1, newTotal);
                    updatePs.setInt(2, saleId);
                    updatePs.executeUpdate();
                }
            }
        }
    }

    private void deleteAllSalesForDate(String date) throws SQLException, IOException {
        Connection conn = null;
        try {
            conn = Database.getConnection();
            conn.setAutoCommit(false);

            // Restore stock for each sold item
            String getItemsSql =
                "SELECT si.id, si.product_id, si.quantity FROM sale_items si " +
                "JOIN sales s ON si.sale_id = s.id " +
                "WHERE DATE(s.sale_date) = ? AND s.client_id = ?";

            List<int[]> itemsToDelete = new ArrayList<>();
            try (PreparedStatement ps = conn.prepareStatement(getItemsSql)) {
                ps.setString(1, date);
                ps.setString(2, Database.getCurrentClientId());
                ResultSet rs = ps.executeQuery();
                while (rs.next()) {
                    itemsToDelete.add(new int[]{rs.getInt("id"),
                        rs.getInt("product_id"), rs.getInt("quantity")});
                }
            }

            for (int[] item : itemsToDelete) {
                try (PreparedStatement ps = conn.prepareStatement(
                        "UPDATE products SET stock_quantity = stock_quantity + ? WHERE id = ?")) {
                    ps.setInt(1, item[2]);
                    ps.setInt(2, item[1]);
                    ps.executeUpdate();
                }
            }

            // Delete sale_items then sales locally
            try (PreparedStatement ps = conn.prepareStatement(
                    "DELETE FROM sale_items WHERE sale_id IN " +
                    "(SELECT id FROM sales WHERE DATE(sale_date) = ? AND client_id = ?)")) {
                ps.setString(1, date);
                ps.setString(2, Database.getCurrentClientId());
                ps.executeUpdate();
            }
            try (PreparedStatement ps = conn.prepareStatement(
                    "DELETE FROM sales WHERE DATE(sale_date) = ? AND client_id = ?")) {
                ps.setString(1, date);
                ps.setString(2, Database.getCurrentClientId());
                ps.executeUpdate();
            }

            conn.commit();

            // Sync to cloud immediately if online
            if (Database.isOnline()) {
                new Thread(() -> {
                    try {
                        String cid = Database.getCurrentClientId();
                        SQLiteCloudClient.executeUpdate(
                            "DELETE FROM sale_items WHERE sale_id IN " +
                            "(SELECT id FROM sales WHERE DATE(sale_date) = ? AND client_id = ?)",
                            date, cid);
                        SQLiteCloudClient.executeUpdate(
                            "DELETE FROM sales WHERE DATE(sale_date) = ? AND client_id = ?",
                            date, cid);
                        // Restore stock in cloud too
                        for (int[] item : itemsToDelete) {
                            SQLiteCloudClient.executeUpdate(
                                "UPDATE products SET stock_quantity = stock_quantity + ? " +
                                "WHERE id = ? AND client_id = ?",
                                item[2], item[1], cid);
                        }
                        LOGGER.info("Cloud sales deletion synced for date: " + date);
                    } catch (Exception e) {
                        LOGGER.warning("Cloud sales deletion failed: " + e.getMessage());
                    }
                }, "cloud-delete-sales-" + date).start();
            }

        } catch (SQLException e) {
            if (conn != null) { try { conn.rollback(); } catch (SQLException ignored) {} }
            throw e;
        } finally {
            if (conn != null) { try { conn.setAutoCommit(true); } catch (SQLException ignored) {} }
        }
    }

    private boolean verifyAdminPassword(String password) {
        try {
            List<com.google.gson.JsonObject> result = SQLiteCloudClient.execute(
                "SELECT password FROM users WHERE email = ? AND privileges IN ('ADMIN', 'SUPERADMIN', 'CEO', 'OWNER')",
                Database.getCurrentUserEmail());
            
            if (!result.isEmpty()) {
                String storedHash = result.get(0).get("password").getAsString();
                return verifyPassword(password, storedHash);
            }
        } catch (IOException e) {
            LOGGER.warning("Admin verification failed: " + e.getMessage());
        }
        return false;
    }

    private boolean verifyPassword(String inputPassword, String storedHash) {
        try {
            java.security.MessageDigest md = java.security.MessageDigest.getInstance("SHA-256");
            byte[] hash = md.digest(inputPassword.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : hash) sb.append(String.format("%02x", b));
            return sb.toString().equals(storedHash);
        } catch (Exception e) {
            return inputPassword.equals(storedHash);
        }
    }

    private void updateStats(DefaultTableModel model, JLabel totalLabel, JLabel lowStockLabel) {
        int totalProducts = model.getRowCount();
        int lowStock = 0;
        
        for (int i = 0; i < totalProducts; i++) {
            int stock = (int) model.getValueAt(i, 6);
            int minStock = (int) model.getValueAt(i, 7);
            
            if (stock <= minStock) {
                lowStock++;
            }
        }
        
        totalLabel.setText("📦 Total Products: " + totalProducts);
        lowStockLabel.setText("⚠️ Low Stock: " + lowStock);
        
        // Optional: Change color based on low stock count
        if (lowStock > 0) {
            lowStockLabel.setForeground(new Color(255, 100, 100));
        } else {
            lowStockLabel.setForeground(new Color(100, 255, 150));
        }
    }
    // end of manual -fix

    

    private void showBasicLogDetails(DefaultTableModel model, int row, JDialog parent) {
        StringBuilder details = new StringBuilder();
        details.append("📋 Log Details:\n\n");
        
        for (int col = 0; col < model.getColumnCount(); col++) {
            Object value = model.getValueAt(row, col);
            details.append(model.getColumnName(col))
                   .append(": ")
                   .append(value != null ? value.toString() : "N/A")
                   .append("\n");
        }
        
        JOptionPane.showMessageDialog(parent, details.toString(), "Log Details", JOptionPane.INFORMATION_MESSAGE);
    }

    private void logActivity(String activity) {
        try {
            String sql = "INSERT INTO activity_log (username, activity, timestamp) VALUES (?, ?, datetime('now'))";
            try (Connection conn = Database.getConnection();
                 PreparedStatement stmt = conn.prepareStatement(sql)) {
                stmt.setString(1, loggedInUser);
                stmt.setString(2, activity);
                stmt.executeUpdate();
            }
        } catch (SQLException e) {
            System.out.println(java.time.LocalDateTime.now() + " - " + activity);
        }
    }

    private void clearSessionData() {
        if (userRestrictions != null) {
            userRestrictions.clear();
        }
    }

